import{n as e}from"./rolldown-runtime-8BhlS34s.js";var t;function n(){return(n=e((()=>{t={configHints:{acp:{label:{"v1-w1ybzr-3":`ACP`},help:{"v1-gwlf91-44":`Настройки среды выполнения ACP для включения диспетчеризации, выбора бэкендов, ограничения допустимых целевых агентов и выбора способа потокового отображения ходов.`}},"acp%2EallowedAgents":{label:{"v1-nvlwwz-i":`Разрешённые агенты ACP`},help:{"v1-f2mw0d-3a":`Список идентификаторов целевых агентов ACP, разрешённых для сеансов среды выполнения ACP. Пустой список означает отсутствие дополнительных ограничений.`}},"acp%2Ebackend":{label:{"v1-vx60lb-b":`Бэкенд ACP`},help:{"v1-1s1l6bz-2v":`Идентификатор бэкенда среды выполнения ACP по умолчанию (например, acpx). Должен соответствовать зарегистрированному бэкенду плагина среды выполнения ACP.`}},"acp%2EdefaultAgent":{label:{"v1-xso6e7-h":`Агент ACP по умолчанию`},help:{"v1-7donnu-2c":`Резервный идентификатор целевого агента ACP, используемый при запуске ACP без явно указанной цели.`}},"acp%2Edispatch%2Eenabled":{label:{"v1-nw9kyy-k":`Диспетчеризация ACP включена`},help:{"v1-1ug9t9m-3w":`Независимый переключатель диспетчеризации ходов в сеансах ACP (по умолчанию: true). Установите false, чтобы сохранить доступность команд ACP, заблокировав выполнение ходов ACP.`}},"acp%2Eenabled":{label:{"v1-5j1g3y-b":`ACP включён`},help:{"v1-1uonl1v-2a":`Глобальный переключатель функций ACP. Оставьте выключенным, пока не настроены среда выполнения и политика ACP.`}},"acp%2Efallbacks":{label:{"v1-j79b6g-l":`Резервные бэкенды ACP`},help:{"v1-1wvdifq-5m":`Упорядоченный список идентификаторов резервных бэкендов ACP, которые проверяются, когда основной бэкенд возвращает ошибку UNAVAILABLE (например, при превышении лимита запросов или исчерпании квоты). Каждая запись должна соответствовать бэкенду зарегистрированного плагина среды выполнения ACP.`}},"acp%2Eruntime%2EinstallCommand":{label:{"v1-14jcqqd-r":`Команда установки среды выполнения ACP`},help:{"v1-1jjuv9m-39":"Необязательная команда установки или настройки для оператора, которую показывают `/acp install` и `/acp doctor`, если подключение бэкенда ACP не настроено."}},"acp%2Estream":{label:{"v1-1j9fe39-a":`Поток ACP`},help:{"v1-1bka5p-2v":`Настройки представления потокового вывода ACP: размер фрагментов, видимость метаданных и доставка без дубликатов.`}},"acp%2Estream%2EdeliveryMode":{label:{"v1-mfvqy2-o":`Режим доставки потока ACP`},help:{"v1-19gdmx1-3s":`Способ доставки ACP: live передаёт представление вывода постепенно, а final_only буферизует всё представление вывода ACP до событий завершения хода.`}},"acp%2Estream%2ErepeatSuppression":{label:{"v1-15imczj-t":`Подавление повторов в потоке ACP`},help:{"v1-manh32-3d":`При значении true (по умолчанию) подавляет повторяющиеся строки представления статуса и инструментов ACP в пределах хода, не изменяя исходные события ACP.`}},"acp%2Estream%2EtagVisibility":{label:{"v1-6o90yj-p":`Видимость тегов потока ACP`},help:{"v1-1ybhx22-34":`Переопределения видимости представления ACP для отдельных типов sessionUpdate (например, usage_update, available_commands_update).`}},agents:{label:{"v1-1sa8ub3-6":`Агенты`},help:{"v1-2rc4v8-55":`Корневой раздел конфигурации среды выполнения агентов. Соседние разделы корневого уровня отвечают за инфраструктуру и общие для агентов значения по умолчанию; agents.defaults — за поведение цикла агента. Записи отдельных агентов могут переопределять и те и другие настройки, где это поддерживается.`}},"agents%2Edefaults":{label:{"v1-16khodg-e":`Настройки агента по умолчанию`},help:{"v1-1af7k5b-5a":`Общие настройки по умолчанию, наследуемые агентами, если они не переопределены в соответствующих записях agents.entries. Используйте настройки по умолчанию, чтобы обеспечить единообразное базовое поведение и сократить дублирование конфигурации отдельных агентов.`}},"agents%2Edefaults%2EauthInheritance":{label:{"v1-9wdrzg-n":`Целевой агент наследования учётных данных`},help:{"v1-2d16wl-2x":`Владелец наследуемого хранилища учётных данных, используемый для совместимости при обновлении, пока учётные данные не будут перенесены отдельно для каждого агента.`}},"agents%2Edefaults%2EauthInheritance%2EagentId":{label:{"v1-bva26o-m":`Владелец наследуемых учётных данных`},help:{"v1-1a1s7nm-4s":`Агент, чьё устаревшее хранилище учётных данных остаётся источником наследования после удаления маркера по умолчанию. Записывается автоматически при обновлении, если прежним владельцем был не main.`}},"agents%2Edefaults%2EbootstrapMaxChars":{label:{"v1-dzxrwm-j":`Максимум символов в файле начальной загрузки`},help:{"v1-drlo3i-37":`Максимальное количество символов из каждого файла начальной загрузки рабочей области, включаемых в системный промпт до усечения (по умолчанию: 20000).`}},"agents%2Edefaults%2EbootstrapTotalMaxChars":{label:{"v1-brbs24-p":`Общий максимум символов начальной загрузки`},help:{"v1-1evwsjb-2c":`Максимальное общее количество символов во всех включаемых файлах начальной загрузки рабочей области (по умолчанию: 60000).`}},"agents%2Edefaults%2Ecompaction":{label:{"v1-1d4drzc-a":`Сжатие`},help:{"v1-1qxdwz8-5p":`Поведение при сжатии контекста, когда его объём приближается к лимиту токенов, включая стратегию и сохранение памяти перед сжатием. Используйте эту настройку, если длительным сеансам необходимо стабильно сохранять преемственность при ограниченном окне контекста.`}},"agents%2Edefaults%2Ecompaction%2Eenabled":{label:{"v1-iri7g4-o":`Встроенное автоматическое сжатие`},help:{"v1-1et7vwu-5l":`Включить встроенное упреждающее автоматическое сжатие (по умолчанию: true). Установите false, чтобы отключить встроенное сжатие по пороговому значению, сохранив восстановление при переполнении OpenClaw, предварительное сжатие и ручную команду /compact.`}},"agents%2Edefaults%2Ecompaction%2EidentifierPolicy":{label:{"v1-i1jgob-s":`Политика сохранения идентификаторов при сжатии`},help:{"v1-hby01l-4l":`Политика сохранения идентификаторов в сводках сжатия: "strict" добавляет в начало встроенные указания по сохранению непрозрачных идентификаторов (по умолчанию), а "off" отключает этот префикс.`}},"agents%2Edefaults%2Ecompaction%2EkeepRecentTokens":{label:{"v1-ljajga-t":`Сохранение последних токенов при сжатии`},help:{"v1-tgysub-5h":`Минимальное количество токенов, сохраняемых из последней части диалога при сжатии. Увеличьте значение, чтобы сохранить непрерывность текущего контекста, или уменьшите, чтобы оставить больше давней истории.`}},"agents%2Edefaults%2Ecompaction%2EmaxActiveTranscriptBytes":{label:{"v1-1il6xj6-17":`Порог размера активной истории для сжатия`},help:{"v1-u715n1-90":`Порог в байтах, при достижении которого видимая модели часть истории (с момента последнего сжатия или сброса) подвергается обычному предварительному локальному сжатию. Задаётся числом байтов или строкой вида "20mb". Установите 0 или оставьте незаданным для отключения. Также ограничивает размер встроенных историй выполнения Codex app-server; при превышении размера встроенные потоки запускаются заново с чистой историей.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush":{label:{"v1-1sphznd-n":`Сохранение памяти перед сжатием`},help:{"v1-18q0ve9-55":`Настройки сохранения памяти перед сжатием: агент записывает данные в память до глубокого сжатия. Оставляйте включённым для длительных сеансов, чтобы важный контекст сохранялся до интенсивного сокращения истории.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2Eenabled":{label:{"v1-14wdoio-v":`Сохранение памяти перед сжатием включено`},help:{"v1-9xllgp-5o":`Включает сохранение памяти перед тем, как среда выполнения начнёт более интенсивное сокращение истории при приближении к лимиту токенов. Оставьте включённым, если только вы намеренно не отключаете операции с памятью в средах с ограниченными ресурсами.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2EforceFlushTranscriptBytes":{label:{"v1-10u43o5-1d":`Порог размера переписки для сохранения памяти перед сжатием`},help:{"v1-1rzov1e-93":`Принудительно запускает сохранение памяти перед сжатием, когда доступная модели часть переписки достигает этого порога (в байтах или в виде строки, например "2mb"). После сжатия учитываются сохранённая заключительная часть и последующие обмены сообщениями, а не удалённая история. Используйте этот параметр, чтобы предотвратить зависания длительных сеансов, даже если счётчики токенов устарели; установите 0 для отключения.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2Emodel":{label:{"v1-z6o9nc-12":`Переопределение модели для сохранения памяти перед сжатием`},help:{"v1-1r3ctyu-7w":`Необязательное переопределение провайдера/модели, используемое только для сохранения памяти перед сжатием. Укажите локальную модель, например ollama/qwen3:8b, если для извлечения данных в долговременную память не следует использовать платную модель текущего сеанса. Используется строго указанная модель; цепочка резервных моделей активной модели не наследуется.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2EsoftThresholdTokens":{label:{"v1-1h1tkzc-12":`Мягкий порог сохранения памяти перед сжатием`},help:{"v1-1dqo2l1-5c":`Пороговое количество токенов, оставшихся до сжатия, при котором запускается сохранение памяти. Установите порог для более раннего запуска, чтобы повысить надёжность сохранения, или ближе к сжатию, чтобы снизить частоту сохранений.`}},"agents%2Edefaults%2Ecompaction%2EmidTurnPrecheck":{label:{"v1-rb9ni9-s":`Предварительная проверка сжатия в ходе обработки`},help:{"v1-am6gbh-6x":`Необязательная предварительная проверка во встроенном цикле вызова инструментов OpenClaw, которая выявляет угрозу переполнения контекста после добавления результата инструмента и перед следующим вызовом модели. Если она включена, OpenClaw использует существующий механизм восстановления при предварительной проверке, чтобы обрезать результаты инструментов или сжать контекст перед повторной попыткой.`}},"agents%2Edefaults%2Ecompaction%2EmidTurnPrecheck%2Eenabled":{label:{"v1-1kxoip4-10":`Предварительная проверка сжатия в ходе обработки включена`},help:{"v1-engbwe-5u":`Включить структурированные проверки угрозы переполнения контекста в ходе обработки во встроенных циклах вызова инструментов OpenClaw. По умолчанию: false. Оставьте выключенным, если только в длительных сеансах с интенсивным использованием инструментов контекст не переполняется до того, как успевает запуститься обычное сжатие в конце обработки.`}},"agents%2Edefaults%2Ecompaction%2Emode":{label:{"v1-70zfez-f":`Режим сжатия`},help:{"v1-1unahwc-76":`Режим стратегии сжатия: "safeguard" (используется по умолчанию, если значение не задано) применяет защитные меры для сохранения недавнего контекста, а "default" использует базовое суммирование без них. Устанавливайте "default", только если суммирование в режиме safeguard вызывает проблемы у вашего провайдера.`}},"agents%2Edefaults%2Ecompaction%2Emodel":{label:{"v1-rqz37z-p":`Переопределение модели для сжатия`},help:{"v1-cfeys9-6q":`Необязательное значение в формате provider/model или настроенный псевдоним без префикса, используемый только для суммирования при сжатии. Псевдонимы без префикса разрешаются до отправки запроса; если явно настроенный идентификатор модели совпадает с псевдонимом, приоритет имеет идентификатор. Оставьте незаданным, чтобы продолжать использовать основную модель агента.`}},"agents%2Edefaults%2Ecompaction%2EnotifyUser":{label:{"v1-ub28vk-m":`Уведомлять пользователя о сжатии`},help:{"v1-lvymm8-bv":`Если включено, отправляет пользователю краткие уведомления об обслуживании контекста: о начале и завершении сжатия (например, «🧹 Сжатие контекста...» и «🧹 Сжатие завершено»), а также об исчерпании попыток сохранения памяти перед сжатием, из-за чего формирование ответа продолжается в ограниченном режиме (например, «⚠️ Временный сбой обслуживания памяти; продолжаем формировать ответ.»). По умолчанию отключено, чтобы обслуживание контекста происходило незаметно и не отвлекало пользователя.`}},"agents%2Edefaults%2Ecompaction%2EpostCompactionSections":{label:{"v1-x1uxbk-w":`Разделы контекста после сжатия`},help:{"v1-1n0ln2u-5f":`Имена разделов H2/H3 из AGENTS.md, которые повторно добавляются в контекст после сжатия при явном указании. Оставьте значение незаданным или укажите [], чтобы отключить повторное добавление. Явно задайте ["Session Startup", "Red Lines"], чтобы включить пару разделов, ранее использовавшуюся по умолчанию.`}},"agents%2Edefaults%2Ecompaction%2EpostIndexSync":{label:{"v1-1p0j1ty-q":`Синхронизация индекса после сжатия`},help:{"v1-ekpjeq-6l":`Управляет режимом переиндексации памяти сеанса после сжатия: "off", "async" или "await" (по умолчанию: "async"). Используйте "await" для максимальной актуальности, "async" для уменьшения задержки при сжатии, а "off" — только если синхронизация памяти сеанса выполняется другим механизмом.`}},"agents%2Edefaults%2Ecompaction%2Eprovider":{label:{"v1-1autmd-j":`Провайдер сжатия`},help:{"v1-kiwk91-86":`Идентификатор зарегистрированного плагина провайдера сжатия, используемого для создания сводок. Если значение задано и провайдер зарегистрирован, вместо встроенного конвейера summarizeInStages вызывается его метод summarize(). При сбое провайдера используется встроенный механизм. Оставьте значение незаданным, чтобы использовать стандартный встроенный механизм создания сводок.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard":{label:{"v1-nh0x1k-o":`Контроль качества сжатия`},help:{"v1-u9ognp-4k":`Настройки повторных попыток проверки качества сводок при сжатии в режиме safeguard. В режиме safeguard эта функция включена по умолчанию; задайте enabled: false, чтобы пропустить проверки сводок и их повторную генерацию.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard%2Eenabled":{label:{"v1-14z377t-w":`Контроль качества сжатия включён`},help:{"v1-1xk2vt3-36":`Включает проверки качества сводок и повторные попытки генерации при сжатии в режиме safeguard. По умолчанию: true в режиме safeguard.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard%2EmaxRetries":{label:{"v1-1wbiubo-10":`Максимум повторных попыток контроля качества сжатия`},help:{"v1-n7l46y-3y":`Максимальное число повторных попыток генерации после неудачной проверки качества сводки в режиме safeguard. Используйте небольшие значения, чтобы ограничить дополнительную задержку и затраты на токены.`}},"agents%2Edefaults%2Ecompaction%2ErecentTurnsPreserve":{label:{"v1-lhuyqv-w":`Сохранение последних реплик при сжатии`},help:{"v1-y34ihi-5k":`Количество последних реплик пользователя и ассистента, сохраняемых дословно и не включаемых в сводку в режиме safeguard (по умолчанию: 3). Увеличьте значение, чтобы сохранить точный контекст недавнего диалога, или уменьшите его для максимальной экономии при сжатии.`}},"agents%2Edefaults%2Ecompaction%2EthinkingLevel":{label:{"v1-5qtj6m-p":`Уровень рассуждения при сжатии`},help:{"v1-1vafgaw-g1":`Уровень рассуждений, используемый только для встроенных сводок сжатия контекста OpenClaw: "off", "minimal", "low", "medium", "high", "xhigh", "adaptive", "max", "ultra" или "inherit". По умолчанию используется предпочтительный уровень сжатия провайдера, а если он не задан — "low"; для нативного локального Ollama предпочтителен "off". Установите "inherit", чтобы использовать уровень сеанса. Явные настройки переопределяют значения провайдера по умолчанию, а выбранный уровень ограничивается возможностями фактической модели и среды выполнения сжатия. Нативное сжатие Codex app-server игнорирует эту настройку, поскольку его запрос compact не поддерживает переопределение уровня рассуждений для отдельной операции; OpenClaw при этом записывает предупреждение в журнал.`}},"agents%2Edefaults%2Ecompaction%2EtimeoutSeconds":{label:{"v1-1x6zijf-s":`Тайм-аут сжатия контекста (секунды)`},help:{"v1-2bhn29-7m":`Предельное время в секундах для каждого запроса к модели при встроенном сжатии контекста (по умолчанию: 180). При многоэтапном сжатии отсчёт начинается заново с каждым последовательным запросом, поэтому весь процесс может занять больше времени; при сжатии, выполняемом плагином, этот срок отводится на всю операцию.`}},"agents%2Edefaults%2EcontextInjection":{label:{"v1-1blm5yl-h":`Вставка контекста`},help:{"v1-u18x0-7u":`Управляет включением файлов начальной настройки рабочего пространства в контекст во встроенной среде выполнения: "always" — обычное включение (по умолчанию), "continuation-skip" — пропуск включения на подходящих шагах продолжения после зафиксированного шага с полной начальной настройкой, "never" — отключение включения. Не управляет подготовкой промптов через CLI.`}},"agents%2Edefaults%2EcontextLimits":{label:{"v1-1lphwvv-m":`Ограничения контекста по умолчанию`},help:{"v1-1coeez8-5d":`Целевые ограничения объёма по умолчанию для отдельных больших фрагментов и вставляемых блоков промпта в контексте каждого агента. Используйте их для настройки предельных объёмов чтения и вставки, не возвращая неограниченные пути вызовов.`}},"agents%2Edefaults%2EcontextLimits%2EmemoryGetMaxChars":{label:{"v1-197rwel-s":`Максимум символов memory_get по умолчанию`},help:{"v1-1qb40qv-4v":`Максимальное количество символов по умолчанию, возвращаемых memory_get до добавления метаданных об усечении и уведомления о продолжении. Увеличьте значение, чтобы приблизиться к прежним более длинным фрагментам, но сохраняйте разумное ограничение.`}},"agents%2Edefaults%2EcontextLimits%2EpostCompactionMaxChars":{label:{"v1-hh1flp-x":`Максимум символов после сжатия по умолчанию`},help:{"v1-64qo8g-5r":`Максимальное количество символов по умолчанию, сохраняемых из AGENTS.md при обновлении контекста после сжатия. Уменьшите значение, чтобы снизить затраты на восстановление после сжатия, или увеличьте его для агентов, которым нужны более подробные начальные инструкции.`}},"agents%2Edefaults%2Ecwd":{label:{"v1-1akuwgr-h":`Рабочий каталог`},help:{"v1-1y8wlxn-6a":`Рабочий каталог для запусков агента при формировании ответов, отдельный от файлов инициализации рабочего пространства и памяти. Значения cwd, заданные для конкретного агента или при создании сеанса, имеют приоритет. Поддерживаются ~ и относительные пути; отдельный cwd требует запуска вне песочницы.`}},"agents%2Edefaults%2EdecisionModel":{label:{"v1-45jwcu-e":`Модель принятия решений`},help:{"v1-7nd7ze-64":`Необязательный провайдер/модель для типизированных вариантов выбора, оценок и вероятностей логических значений. Если значение не задано или пусто, вызовы для принятия решений отключены. Поддерживающие эту функцию плагины отправляют этому провайдеру ограниченный объём данных по задаче; модели чата и служебные модели остаются без изменений.`}},"agents%2Edefaults%2EembeddedAgent":{label:{"v1-78x3fi-h":`Встроенный OpenClaw`},help:{"v1-1keek32-3k":`Настройки усиления защиты встроенной среды выполнения OpenClaw, определяющие доверие к локальным настройкам агента в рабочем пространстве и их применение в сеансах OpenClaw.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover":{label:{"v1-1qnu0am-l":`Резервное переключение при отказе по политике кибербезопасности`},help:{"v1-xvv6wl-2r":`Автоматическая передача запроса в Daybreak при отказах OpenAI по политике кибербезопасности во встроенной среде выполнения, если повторное выполнение безопасно.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2EcooloffMs":{label:{"v1-j5ckj0-t":`Пауза резервного переключения при отказе по политике кибербезопасности`},help:{"v1-16smtrl-25":`Как долго недоступная цель передачи запросов пропускается в текущем сеансе.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2Emode":{label:{"v1-1mx8pup-q":`Режим резервного переключения при отказе по политике кибербезопасности`},help:{"v1-rzsd2b-2h":`Включить автоматическую передачу запроса ("auto", по умолчанию) или считать отказы поставщика окончательными ("off").`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2Emodel":{label:{"v1-1oxd3p3-r":`Модель резервного переключения при отказе по политике кибербезопасности`},help:{"v1-1aaj8nn-1t":`Целевой поставщик или модель для автоматической передачи запроса при отказе по политике кибербезопасности.`}},"agents%2Edefaults%2EembeddedAgent%2EexecutionContract":{label:{"v1-1e1r7sa-10":`Контракт выполнения встроенного OpenClaw`},help:{"v1-1fch2ig-66":`Контракт выполнения встроенного OpenClaw: "default" сохраняет стандартное поведение среды выполнения, а "strict-agentic" включает структурированное отслеживание плана и скрытое от пользователя восстановление хода для поддерживаемых запусков моделей семейства GPT-5 в OpenAI/OpenAI Codex.`}},"agents%2Edefaults%2EembeddedAgent%2EprojectSettingsPolicy":{label:{"v1-xaw8em-15":`Политика настроек проекта встроенного OpenClaw`},help:{"v1-fdyy04-65":'Способ обработки встроенным OpenClaw локального файла рабочей области `.openclaw/settings.json`: "sanitize" (по умолчанию) удаляет shellPath/shellCommandPrefix, "ignore" полностью отключает настройки проекта, а "trusted" применяет настройки проекта без изменений.'}},"agents%2Edefaults%2Eexperimental":{label:{"v1-biomsl-o":`Экспериментальные флаги агента`},help:{"v1-cvv5cl-2w":`Экспериментальные флаги агента по умолчанию. Не включайте их, если не планируете тестировать предварительные версии функций.`}},"agents%2Edefaults%2Eexperimental%2ElocalModelLean":{label:{"v1-x4h50k-17":`Включить облегчённый режим локальной модели (экспериментальный)`},help:{"v1-gj06u6-7b":`Расширенная настройка для устранения неполадок, ограничивающая необязательные инструменты, такие как browser, automations и message. По умолчанию отключена; поддерживаемые локальные среды выполнения используют автоматический Tool Search без этого ограничения. Явные разрешения на использование инструментов и обязательные инструменты доставки сохраняются.`}},"agents%2Edefaults%2EfastModeDefault":{label:{"v1-1l6uhpu-n":`Быстрый режим агента по умолчанию`},help:{"v1-zv4y98-2z":`Политика быстрого режима по умолчанию для цикла агента ("auto", true или false). Настройки отдельных агентов переопределяют её.`}},"agents%2Edefaults%2Eheartbeat%2EagentId":{label:{"v1-1kugcom-f":`Агент фоновых проверок`},help:{"v1-1jynxej-3w":`Агент, отвечающий за фоновые периодические проверки, если для отдельных агентов они не настроены. Оставьте незаданным, чтобы сохранить настроенную маршрутизацию по умолчанию.`}},"agents%2Edefaults%2Eheartbeat%2EdirectPolicy":{label:{"v1-19ubfku-n":`Политика личных сообщений для фоновых проверок`},help:{"v1-nhyxa9-41":`Определяет, можно ли отправлять результаты фоновых проверок в личные чаты: "allow" (по умолчанию) разрешает доставку в личные сообщения, а "block" блокирует отправку в личные чаты.`}},"agents%2Edefaults%2Eheartbeat%2EtimeoutSeconds":{label:{"v1-17pcf3w-r":`Тайм-аут пульса (секунды)`},help:{"v1-1se21py-5f":`Максимальное время в секундах для хода агента при пульсе, после которого ход прерывается. Если не задано, используется agents.defaults.timeoutSeconds, если этот параметр указан; иначе — интервал пульса, но не более 600 секунд.`}},"agents%2Edefaults%2EhumanDelay%2EmaxMs":{label:{"v1-1mrn73i-k":`Максимальная задержка для имитации человека (мс)`},help:{"v1-vnmvli-1m":`Максимальная задержка в мс для пользовательской настройки humanDelay (по умолчанию: 2500).`}},"agents%2Edefaults%2EhumanDelay%2EminMs":{label:{"v1-1wd5i8o-k":`Минимальная задержка для имитации человека (мс)`},help:{"v1-5nrtr5-1l":`Минимальная задержка в мс для пользовательской настройки humanDelay (по умолчанию: 800).`}},"agents%2Edefaults%2EhumanDelay%2Emode":{label:{"v1-ck9798-g":`Режим задержки для имитации человека`},help:{"v1-k7hyg3-1n":`Тип задержки для ответов блоками ("off", "natural", "custom").`}},"agents%2Edefaults%2EimageMaxDimensionPx":{label:{"v1-qmer27-o":`Максимальный размер изображения (пиксели)`},help:{"v1-vju8x-2u":`Максимальная длина стороны изображения в пикселях при очистке данных изображений в истории диалога и результатах инструментов (по умолчанию: 1200).`}},"agents%2Edefaults%2EimageModel%2Efallbacks":{label:{"v1-d75sz8-l":`Резервные модели для изображений`},help:{"v1-1kgx5i9-1b":`Резервные модели для изображений в порядке использования (provider/model).`}},"agents%2Edefaults%2EimageModel%2Eprimary":{label:{"v1-1533tn-b":`Модель для изображений`},help:{"v1-dstqyh-2c":`Необязательная модель для изображений (provider/model), используемая, если основная модель не поддерживает изображения на входе.`}},"agents%2Edefaults%2EimageQuality":{label:{"v1-1x0wkcr-d":`Качество изображения`},help:{"v1-1uyxc5s-6u":`Предпочтительный режим сжатия медиа для инструмента работы с изображениями: "auto" адаптируется к ограничениям провайдера/модели и количеству изображений, "efficient" экономит токены и байты, "balanced" сохраняет текущий баланс, а "high" сохраняет больше деталей на скриншотах и изображениях документов.`}},"agents%2Edefaults%2EmediaModels%2Eimage%2Efallbacks":{label:{"v1-104q8cy-w":`Резервные модели генерации изображений`},help:{"v1-oljfk4-1m":`Резервные модели генерации изображений в порядке использования (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Eimage%2Eprimary":{label:{"v1-hzzdnh-m":`Модель генерации изображений`},help:{"v1-g4yw0h-2o":`Необязательная модель генерации изображений (provider/model), используемая общей функцией генерации изображений.`}},"agents%2Edefaults%2EmediaModels%2Eimage%2EtimeoutMs":{label:{"v1-4y5oza-t":`Время ожидания генерации изображений (мс)`},help:{"v1-9yesfj-31":`Время ожидания ответа на запрос к провайдеру по умолчанию в миллисекундах для вызовов image_generate. Параметр timeoutMs в отдельном вызове переопределяет это значение.`}},"agents%2Edefaults%2EmediaModels%2Emusic%2Efallbacks":{label:{"v1-qkwbmc-w":`Резервные модели генерации музыки`},help:{"v1-wyg9xe-1m":`Резервные модели генерации музыки в порядке использования (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Emusic%2Eprimary":{label:{"v1-f7mzln-m":`Модель генерации музыки`},help:{"v1-xs1e2h-2o":`Необязательная модель генерации музыки (provider/model), используемая общей функцией генерации музыки.`}},"agents%2Edefaults%2EmediaModels%2Evideo%2Efallbacks":{label:{"v1-xoqak-w":`Резервные модели генерации видео`},help:{"v1-wpbf1e-1m":`Резервные модели генерации видео в порядке приоритета (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Evideo%2Eprimary":{label:{"v1-fokknn-m":`Модель генерации видео`},help:{"v1-hfmlbl-2o":`Необязательная модель генерации видео (provider/model), используемая общей функцией генерации видео.`}},"agents%2Edefaults%2EmediaModels%2Evideo%2EtimeoutMs":{label:{"v1-1dtok9w-t":`Тайм-аут генерации видео (мс)`},help:{"v1-1bqj80s-4i":`Тайм-аут запроса к провайдеру по умолчанию в миллисекундах для вызовов video_generate. Параметр timeoutMs отдельного вызова переопределяет это значение, а оно переопределяет значения по умолчанию, заданные провайдером.`}},"agents%2Edefaults%2Emodel%2Efallbacks":{label:{"v1-dz2y4l-f":`Резервные модели`},help:{"v1-t4djq2-24":`Резервные модели в порядке приоритета (provider/model). Используются при сбое основной модели.`}},"agents%2Edefaults%2Emodel%2Eprimary":{label:{"v1-1jjnzq0-d":`Основная модель`},help:{"v1-1i8a1v4-v":`Основная модель (provider/model).`}},"agents%2Edefaults%2EmodelPolicy":{label:{"v1-m0l2o-c":`Политика моделей`},help:{"v1-z0txb7-2e":`Явная политика переопределения модели. Не указывайте её или оставьте allow пустым, чтобы разрешить любую модель.`}},"agents%2Edefaults%2EmodelPolicy%2Eallow":{label:{"v1-a807hj-e":`Разрешённые модели`},help:{"v1-1fqace-3x":`Разрешённые ссылки для переопределения модели. Поддерживаются псевдонимы, полные ссылки вида "provider/model" и шаблоны провайдеров, например "openai/*". Пустое значение разрешает любую модель.`}},"agents%2Edefaults%2Emodels":{label:{"v1-hzmwb-6":`Модели`},help:{"v1-13cvq23-4i":`Настроенный каталог моделей и индивидуальные настройки моделей. Записи задают псевдонимы, параметры, метаданные среды выполнения и переопределения режима кода; они не ограничивают переопределение модели.`}},"agents%2Edefaults%2Emodels%2E*%2EagentRuntime":{label:{"v1-7nd0vy-r":`Среда выполнения модели агента по умолчанию`},help:{"v1-6km9kx-41":`Необязательная политика среды выполнения для отдельной модели агента по умолчанию. Используйте её для исключений, зависящих от модели, вместо настройки среды выполнения для всего агента.`}},"agents%2Edefaults%2Emodels%2E*%2EagentRuntime%2Eid":{label:{"v1-y10gjb-u":`ID среды выполнения модели агента по умолчанию`},help:{"v1-1co96w7-4a":`Идентификатор среды выполнения модели агента по умолчанию: "openclaw", "auto", идентификатор зарегистрированной плагинной обвязки, например "codex", или поддерживаемый псевдоним бэкенда CLI, например "claude-cli".`}},"agents%2Edefaults%2Emodels%2E*%2EcodeMode":{label:{"v1-194jdgf-9":`Режим кода`},help:{"v1-rsdl5o-6x":`Режим работы с кодом OpenClaw для этой конкретной пары провайдер/модель: «Включено» принудительно включает его, «Выключено» отключает, а «По умолчанию» наследует tools.codeMode.enabled. Настройки активации для конкретного агента имеют приоритет. Это не меняет выбранную среду выполнения или встроенный режим работы с кодом Codex.`}},"agents%2Edefaults%2EmodelSelectionScope":{label:{"v1-rtarqk-l":`Область действия выбора модели`},help:{"v1-sj8owq-bl":`Область действия команд чата и обновлений модели сессии Gateway, если она не указана явно: "session" (по умолчанию) меняет только текущую сессию, "agent" также обновляет основную модель этого агента, а "global" дополнительно обновляет общую резервную модель agents.defaults.model. Явные флаги области действия имеют приоритет; для изменения настроенных значений по умолчанию требуются права владельца или администратора. Выбор через callback-кнопки Telegram и встроенный локальный TUI по-прежнему действует только в пределах сессии.`}},"agents%2Edefaults%2EpdfMaxMb":{label:{"v1-ked92u-h":`Максимальный размер PDF (МБ)`},help:{"v1-1uig1dr-1u":`Максимальный размер PDF-файла в мегабайтах для инструмента PDF (по умолчанию: 10).`}},"agents%2Edefaults%2EpdfMaxPages":{label:{"v1-1mbzuxr-d":`Максимальное число страниц PDF`},help:{"v1-11na7hp-1y":`Максимальное количество страниц PDF для обработки инструментом PDF (по умолчанию: 20).`}},"agents%2Edefaults%2EpdfModel%2Efallbacks":{label:{"v1-pu595v-j":`Резервные модели для PDF`},help:{"v1-89ebd8-19":`Резервные модели для PDF в порядке использования (provider/model).`}},"agents%2Edefaults%2EpdfModel%2Eprimary":{label:{"v1-u2jryk-9":`Модель для PDF`},help:{"v1-2ktkxt-2y":`Необязательная модель для инструмента анализа PDF (provider/model). По умолчанию используется imageModel, затем модель сеанса.`}},"agents%2Edefaults%2ErepoRoot":{label:{"v1-1wgofmz-9":`Корневой каталог репозитория`},help:{"v1-j3sh74-2h":`Необязательный корневой каталог репозитория, отображаемый в строке среды выполнения системного промпта (переопределяет автоматическое определение).`}},"agents%2Edefaults%2Esandbox%2Ebrowser%2EcdpSourceRange":{label:{"v1-a168yk-11":`Диапазон исходных портов CDP браузера в песочнице`},help:{"v1-1jkowdc-2b":`Необязательный список разрешённых CIDR для входящего трафика CDP на границе контейнера (например, 172.21.0.1/32).`}},"agents%2Edefaults%2Esandbox%2Ebrowser%2Enetwork":{label:{"v1-w9qjiq-n":`Сеть браузера в песочнице`},help:{"v1-8m74ud-5w":`Сеть Docker для контейнеров браузера в песочнице (по умолчанию: openclaw-sandbox-browser). Используйте выделенную сеть по умолчанию или собственную мостовую сеть; "none" не поддерживается, поскольку для управления браузером необходимы опубликованные порты CDP.`}},"agents%2Edefaults%2Esandbox%2Edocker%2EdangerouslyAllowContainerNamespaceJoin":{label:{"v1-m0t0f7-19":`Разрешить присоединение к пространству имён контейнера в Docker-песочнице`},help:{"v1-qm39de-4c":`ОПАСНОЕ аварийное переопределение, разрешающее сетевой режим Docker container:<id> в песочнице. Это приводит к присоединению к пространству имён другого контейнера и ослабляет изоляцию песочницы.`}},"agents%2Edefaults%2Esandbox%2Edocker%2Egpus":{label:{"v1-c8tb-j":`GPU Docker в песочнице`},help:{"v1-jj0yhw-4k":`Необязательное значение для проброса GPU в Docker, передаваемое параметру --gpus, например "all" или "device=GPU-uuid". Требуется совместимая среда выполнения на хосте, например NVIDIA Container Toolkit.`}},"agents%2Edefaults%2EsessionStore":{label:{"v1-qna6lw-r":`Целевое хранилище устаревших сессий`},help:{"v1-1xkej6i-2g":`Владелец для обеспечения совместимости при обновлении: используется для устаревших записей main-agent и фиксированных хранилищ сессий прежнего формата.`}},"agents%2Edefaults%2EsessionStore%2EagentId":{label:{"v1-3s8frc-q":`Владелец хранилища устаревших сессий`},help:{"v1-ommm7e-5w":`Агент, которому принадлежат устаревшие записи main-agent или записи без привязки к агенту в фиксированном хранилище сессий прежнего формата после отмены маркера по умолчанию. Записывается автоматически при обновлении, если прежний владелец не был main или единственным агентом.`}},"agents%2Edefaults%2Eskills":{label:{"v1-1bk7xrz-6":`Skills`},help:{"v1-1pbsu94-75":`Необязательный список разрешённых навыков по умолчанию, наследуемый агентами, у которых не задано agents.entries.*.skills. Не задавайте его, чтобы не ограничивать навыки; укажите [], чтобы наследующие агенты не получали навыков. Обратите внимание: явно заданное agents.entries.*.skills заменяет этот список по умолчанию, а не объединяется с ним.`}},"agents%2Edefaults%2EskipBootstrap":{label:{"v1-10c1qje-x":`Пропускать создание файлов начальной настройки рабочего пространства`},help:{"v1-kbstgw-5v":`Пропускает автоматическое создание файлов начальной настройки рабочего пространства, но не включение существующих файлов в контекст. Чтобы отключить включение во встроенной среде выполнения, задайте для agents.defaults.contextInjection значение "never". Этот параметр можно переопределить для отдельного агента.`}},"agents%2Edefaults%2EskipOptionalBootstrapFiles":{label:{"v1-xzxxz4-w":`Пропускаемые необязательные файлы начальной настройки`},help:{"v1-1j2z4yj-4c":`Необязательные файлы начальной настройки, которые не следует создавать в рабочих пространствах агентов. Допустимые значения: SOUL.md, USER.md, IDENTITY.md (HEARTBEAT.md принимается, но не оказывает никакого действия).`}},"agents%2Edefaults%2EstartupContext":{label:{"v1-2srlwp-f":`Контекст при запуске`},help:{"v1-1ugsihy-5o":`Вступительный контекст для первого хода, формируемый средой выполнения при вызове "/new" и "/reset" без аргументов. Позволяет настроить предварительную загрузку последних ежедневных файлов памяти в первый промпт, вместо того чтобы поручать модели решать, что читать.`}},"agents%2Edefaults%2EstartupContext%2EapplyOn":{label:{"v1-8ngrte-o":`Команды для применения стартового контекста`},help:{"v1-wav4a5-36":`Определяет, какие команды сброса без аргументов получают стартовый контекст: укажите "new", "reset" или обе (по умолчанию: ["new","reset"]).`}},"agents%2Edefaults%2EstartupContext%2EdailyMemoryDays":{label:{"v1-oj0fzi-x":`Количество дней ежедневной памяти в стартовом контексте`},help:{"v1-4i5xcm-3p":`Количество датированных файлов памяти для загрузки с отсчётом назад от сегодняшнего дня в настроенном часовом поясе пользователя (по умолчанию: 2 — за сегодня и вчера).`}},"agents%2Edefaults%2EstartupContext%2Eenabled":{label:{"v1-1iode8k-m":`Включить стартовый контекст`},help:{"v1-1d5vz2u-4i":`Включает добавление стартового контекста при сбросе сеанса командой без аргументов (по умолчанию: true). Отключите, чтобы использовать только промпт, без загрузки ежедневной памяти средой выполнения.`}},"agents%2Edefaults%2EstartupContext%2EmaxFileBytes":{label:{"v1-816erw-u":`Максимальный размер файла стартового контекста в байтах`},help:{"v1-11cbian-41":`Максимально допустимое количество байтов в каждом ежедневном файле памяти при формировании стартового контекста (по умолчанию: 16384). Файлы, превышающие этот предел безопасного чтения с соблюдением границ, пропускаются.`}},"agents%2Edefaults%2EstartupContext%2EmaxFileChars":{label:{"v1-1xzziaa-u":`Максимальное количество символов файла стартового контекста`},help:{"v1-10z53s-2u":`Максимальное количество символов из каждого загруженного ежедневного файла памяти, сохраняемых во вступительном контексте (по умолчанию: 1200).`}},"agents%2Edefaults%2EstartupContext%2EmaxTotalChars":{label:{"v1-1gx8bpc-v":`Максимальное общее число символов стартового контекста`},help:{"v1-sf676u-54":`Максимальное общее число символов из всех загруженных ежедневных файлов памяти, сохраняемых во вводной части при запуске (по умолчанию: 2800). При достижении этого ограничения содержимое дополнительных файлов обрезается.`}},"agents%2Edefaults%2Esubagents%2EdelegationMode":{label:{"v1-bhpjpo-p":`Режим делегирования субагентам`},help:{"v1-pqewbk-5o":`Степень настойчивости инструкций по делегированию субагентам, задаваемая только через промпт. По умолчанию используется "prefer" в основной сессии каждого агента и "suggest" в остальных; "prefer" настоятельно предписывает агенту делегировать нетривиальные задачи через sessions_spawn.`}},"agents%2Edefaults%2EsystemAgent":{label:{"v1-d8xvga-j":`Целевые настройки системного агента`},help:{"v1-1wwimo9-34":`Целевые настройки фоновых вызовов модели системным агентом OpenClaw и Custodian, а также отдельных операций чтения оператора без явно заданной области действия.`}},"agents%2Edefaults%2EsystemAgent%2EagentId":{label:{"v1-xsnrm-i":`Владелец системного агента`},help:{"v1-15rvt92-8c":`Агент, чьи модель и учётные данные используются для фоновых обращений системного агента и Custodian. Также используется, если в models.list, models.authStatus, skills.status, doctor.memory.status или команде CLI infer, определяющей модель или состояние авторизации агента, не указан agentId или --agent; явно указанный в запросе agentId всегда имеет приоритет.`}},"agents%2Edefaults%2EtypingIntervalSeconds":{label:{"v1-5vbq6f-p":`Интервал индикации набора текста (секунды)`},help:{"v1-1y701ox-42":`Задаёт интервал обновления индикатора набора текста в секундах для всех агентов. Увеличьте его, чтобы снизить частоту обновлений во всех каналах, поддерживающих индикацию набора текста.`}},"agents%2Edefaults%2EtypingMode":{label:{"v1-17u58e1-b":`Режим индикации набора текста`},help:{"v1-m2hvpw-3m":`Определяет, когда агенты начинают показывать индикатор набора текста: "never", "instant", "thinking" или "message". Параметр typingMode отдельного агента переопределяет это значение по умолчанию.`}},"agents%2Edefaults%2EutilityModel":{label:{"v1-7gi7gi-d":`Вспомогательная модель`},help:{"v1-1wg7h1a-7s":`Необязательная менее затратная модель (provider/model или псевдоним) для коротких внутренних задач, таких как создание заголовков и описание хода выполнения. Если параметр не задан, используется малая модель, объявленная основным провайдером, если она доступна (иначе — основная модель). Задайте пустую строку, чтобы отключить маршрутизацию на вспомогательную модель.`}},"agents%2Edefaults%2EvoiceModel%2Efallbacks":{label:{"v1-v34llj-l":`Резервные голосовые модели`},help:{"v1-faazv4-1b":`Резервные голосовые модели (provider/model) в порядке использования.`}},"agents%2Edefaults%2EvoiceModel%2Eprimary":{label:{"v1-hvyby0-b":`Голосовая модель`},help:{"v1-1yeh3h4-2t":`Необязательная голосовая модель (provider/model) для синтеза речи, транскрибации и голосового взаимодействия в реальном времени.`}},"agents%2Edefaults%2EvoiceModel%2EtimeoutMs":{label:{"v1-1hw6a5x-i":`Тайм-аут голосовых операций (мс)`},help:{"v1-1sbergs-32":`Тайм-аут запроса к провайдеру по умолчанию в миллисекундах для операций с голосовой моделью, если вызывающая сторона поддерживает тайм-ауты.`}},"agents%2Edefaults%2Eworkspace":{label:{"v1-aw4cba-9":`Рабочее пространство`},help:{"v1-1lssx8l-5w":`Рабочее пространство агента по умолчанию для файлов начальной настройки и памяти. Также используется как рабочий каталог, если agents.defaults.cwd не задан. Укажите его явно при запуске через обёртки, чтобы пути разрешались однозначно.`}},"agents%2Eentries":{label:{"v1-1ts48oe-a":`Список агентов`},help:{"v1-yurood-5l":`Явный список настроенных агентов с идентификаторами и необязательными переопределениями модели, инструментов, профиля и рабочего пространства. Не меняйте идентификаторы со временем, чтобы привязки, разрешения и маршрутизация сеансов оставались однозначными.`}},"agents%2Eentries%2E*%2EagentRuntime":{label:{"v1-rmaqyr-k":`Устаревшая среда выполнения агента`}},"agents%2Eentries%2E*%2EagentRuntime%2Eid":{label:{"v1-mtthss-n":`ID устаревшей среды выполнения агента`}},"agents%2Eentries%2E*%2EbootstrapMaxChars":{label:{"v1-beqsv3-p":`Максимум символов в файле инициализации агента`},help:{"v1-rsf1es-4j":`Индивидуальное ограничение для агента на максимальное число символов в каждом файле инициализации рабочей области, добавляемом в системный промпт этого агента. Не указывайте, чтобы наследовать agents.defaults.bootstrapMaxChars.`}},"agents%2Eentries%2E*%2EbootstrapTotalMaxChars":{label:{"v1-1hf8zr9-v":`Максимальное суммарное число символов инициализации агента`},help:{"v1-1bal68p-4y":`Индивидуальное ограничение для агента на максимальное суммарное число символов во всех файлах инициализации рабочей области, добавляемых в системный промпт этого агента. Не указывайте, чтобы наследовать agents.defaults.bootstrapTotalMaxChars.`}},"agents%2Eentries%2E*%2EcontextInjection":{label:{"v1-1rpaags-n":`Добавление контекста агента`},help:{"v1-1j68ys8-50":`Индивидуальная настройка внедрения файлов начальной загрузки рабочего пространства для агента во встроенной среде выполнения. Не указывайте её, чтобы наследовать agents.defaults.contextInjection. Не управляет подготовкой промптов через CLI.`}},"agents%2Eentries%2E*%2EcontextLimits":{label:{"v1-1nx137n-k":`Ограничения контекста агента`},help:{"v1-f1qxq8-3c":`Необязательные индивидуальные настройки агента для отдельных ограничений объёма контекста. Неуказанные поля наследуют agents.defaults.contextLimits.`}},"agents%2Eentries%2E*%2EcontextLimits%2EmemoryGetMaxChars":{label:{"v1-7rulph-q":`Максимум символов memory_get для агента`},help:{"v1-12hlmsv-1v":`Индивидуальное ограничение для агента, заменяющее максимальное число символов memory_get по умолчанию.`}},"agents%2Eentries%2E*%2EcontextLimits%2EpostCompactionMaxChars":{label:{"v1-s7gnc5-v":`Максимум символов после сжатия для агента`},help:{"v1-15s0npd-1w":`Переопределение лимита объёма выдержки из AGENTS.md после сжатия контекста для отдельного агента.`}},"agents%2Eentries%2E*%2Ecwd":{label:{"v1-19t4x9u-n":`Рабочий каталог агента`},help:{"v1-mv43ak-6a":`Рабочий каталог для запусков этого агента при формировании ответов. Переопределяет agents.defaults.cwd, но не cwd, заданный при создании сессии; файлы начальной настройки и памяти остаются в рабочем пространстве. Поддерживает ~ и относительные пути; отдельный cwd требует запуска вне песочницы.`}},"agents%2Eentries%2E*%2EdecisionModel":{label:{"v1-73avf9-k":`Модель принятия решений агента`},help:{"v1-1mih8bf-3j":`Модель принятия решений для отдельного агента. Если значение не задано, наследуется agents.defaults.decisionModel; пустая строка отключает вызовы для принятия решений для этого агента.`}},"agents%2Eentries%2E*%2EembeddedAgent":{label:{"v1-5clak7-n":`Встроенный OpenClaw агента`},help:{"v1-uoomza-4b":`Необязательные переопределения настроек встроенного OpenClaw для отдельного агента. Позволяют включить более строгий режим выполнения GPT-5 для определённых агентов, не меняя глобальные настройки по умолчанию.`}},"agents%2Eentries%2E*%2EembeddedAgent%2EexecutionContract":{label:{"v1-za8cop-16":`Контракт выполнения встроенного OpenClaw агента`},help:{"v1-1d1jaoi-7k":`Необязательное переопределение контракта выполнения встроенного OpenClaw для отдельного агента. Установите "strict-agentic", чтобы включить структурированное отслеживание плана и скрытое восстановление ходов для этого агента при поддерживаемых запусках моделей семейства GPT-5 от OpenAI/OpenAI Codex, или "default", чтобы наследовать стандартное поведение среды выполнения.`}},"agents%2Eentries%2E*%2Eexperimental":{label:{"v1-lzii83-o":`Экспериментальные флаги агента`},help:{"v1-1r06jov-2a":`Экспериментальные флаги для отдельного агента. Неуказанные поля наследуют значения из agents.defaults.experimental.`}},"agents%2Eentries%2E*%2Eexperimental%2ElocalModelLean":{label:{"v1-9htxgz-r":`Облегчённый режим локальной модели агента`},help:{"v1-5o3tgx-58":`Настройка для устранения неполадок в режиме локальной модели с ограниченным набором инструментов для отдельного агента. Включайте её, только если ограничение необязательных инструментов устраняет подтверждённый сбой модели, не сокращая набор инструментов у всех агентов.`}},"agents%2Eentries%2E*%2EfastModeDefault":{label:{"v1-9gqmky-n":`Быстрый режим агента по умолчанию`},help:{"v1-1ujydjc-3o":`Необязательное значение быстрого режима по умолчанию для отдельного агента ("auto", true или false). Применяется, если быстрый режим не переопределён для сообщения или сеанса.`}},"agents%2Eentries%2E*%2Eheartbeat%2EdirectPolicy":{label:{"v1-19ubfku-n":`Политика доставки периодических уведомлений в личные сообщения`},help:{"v1-11gl9l0-41":`Переопределение политики доставки периодических уведомлений в личные сообщения для отдельного агента; используйте "block" для агентов, которые должны отправлять такие уведомления только за пределами личных сообщений.`}},"agents%2Eentries%2E*%2Eheartbeat%2EtimeoutSeconds":{label:{"v1-17pcf3w-r":`Время ожидания периодической проверки (в секундах)`},help:{"v1-kdetv4-6s":`Максимальное время в секундах, отведённое отдельному агенту на выполнение шага периодической проверки до его прерывания. Если не задано, наследуется время ожидания из объединённых настроек периодической проверки, затем — agents.defaults.timeoutSeconds, если оно задано, иначе — интервал периодических проверок, но не более 600 секунд.`}},"agents%2Eentries%2E*%2Eidentity%2Eavatar":{label:{"v1-fs5x3k-f":`Аватар профиля`},help:{"v1-pzp9gr-1t":`Аватар агента (путь относительно рабочей области, URL http(s) или URI data).`}},"agents%2Eentries%2E*%2EmodelPolicy":{label:{"v1-1locq7r-i":`Политика моделей агента`},help:{"v1-17d5je8-2r":`Политика переопределения модели для отдельного агента. Явно заданный список разрешённых моделей заменяет политику по умолчанию для этого агента.`}},"agents%2Eentries%2E*%2EmodelPolicy%2Eallow":{label:{"v1-xgq0i8-k":`Разрешённые модели агента`},help:{"v1-v1ueke-5b":`Разрешённые идентификаторы моделей для переопределения модели этого агента. Поддерживаются псевдонимы, полные идентификаторы "provider/model" и шаблоны с подстановочным символом в конце, например "provider/*" или "provider/namespace/*"; пустое значение разрешает любую модель.`}},"agents%2Eentries%2E*%2Emodels":{label:{"v1-yawisy-l":`Переопределения моделей агента`},help:{"v1-nld1vq-1v":`Переопределения каталога моделей для отдельного агента с полными идентификаторами provider/model в качестве ключей.`}},"agents%2Eentries%2E*%2Emodels%2E*%2EagentRuntime":{label:{"v1-1cv283-j":`Среда выполнения модели агента`},help:{"v1-7b59y-3s":`Необязательная политика среды выполнения для отдельной модели этого агента. Используйте её для исключений на уровне моделей конкретного агента вместо настройки среды выполнения для всего агента.`}},"agents%2Eentries%2E*%2Emodels%2E*%2EagentRuntime%2Eid":{label:{"v1-1j5q5p8-m":`Идентификатор среды выполнения модели агента`},help:{"v1-1ckfc39-46":`Идентификатор среды выполнения модели для отдельного агента: "openclaw", "auto", идентификатор зарегистрированной среды плагина, например "codex", или поддерживаемый псевдоним бэкенда CLI, например "claude-cli".`}},"agents%2Eentries%2E*%2Emodels%2E*%2EcodeMode":{label:{"v1-194jdgf-9":`Режим кода`},help:{"v1-91zu7f-7m":`Режим работы с кодом OpenClaw для этого агента и конкретной пары provider/model: «Вкл.» принудительно включает его, «Выкл.» отключает, а «По умолчанию» наследует настройку активации агента, затем общее переопределение модели, затем tools.codeMode.enabled. Это не меняет выбранную среду выполнения или встроенный режим работы с кодом Codex.`}},"agents%2Eentries%2E*%2EreasoningDefault":{label:{"v1-drq4cj-n":`Отображение рассуждений агента по умолчанию`},help:{"v1-13ly0xf-3m":`Необязательная настройка отображения рассуждений по умолчанию для отдельного агента (on|off|stream). Применяется, если для сообщения или сеанса не задано переопределение отображения рассуждений.`}},"agents%2Eentries%2E*%2Eruntime":{label:{"v1-10xv3pm-d":`Среда выполнения агента`},help:{"v1-avjgkf-3l":`Необязательное описание среды выполнения этого агента. Используйте embedded для стандартного выполнения в OpenClaw или acp для настроек по умолчанию внешней среды ACP.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp":{label:{"v1-81375y-h":`Среда выполнения ACP агента`},help:{"v1-91zvdk-3i":`Настройки среды выполнения ACP по умолчанию для этого агента при runtime.type=acp. Переопределения ACP на уровне привязки по-прежнему имеют приоритет для каждого разговора.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Eagent":{label:{"v1-ildwsn-n":`Агент среды ACP для этого агента`},help:{"v1-1pm98vp-37":`Необязательный идентификатор агента среды ACP для этого агента OpenClaw (например, codex, claude, cursor, gemini, openclaw).`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Ebackend":{label:{"v1-1vygqw2-h":`Бэкенд ACP агента`},help:{"v1-1u3cdsg-2n":`Необязательное переопределение бэкенда ACP для сеансов ACP этого агента (по умолчанию используется глобальное значение acp.backend).`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Ecwd":{label:{"v1-1ts2vd2-r":`Рабочий каталог ACP агента`},help:{"v1-d9p9rf-1t":`Необязательный рабочий каталог по умолчанию для сеансов ACP этого агента.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Emode":{label:{"v1-1zgumd-e":`Режим ACP агента`},help:{"v1-yatuk4-21":`Необязательный режим сеанса ACP по умолчанию для этого агента (persistent или oneshot).`}},"agents%2Eentries%2E*%2Eruntime%2Etype":{label:{"v1-8wr11a-i":`Тип среды выполнения агента`},help:{"v1-139fbk6-2r":`Тип среды выполнения этого агента: "embedded" (среда выполнения OpenClaw по умолчанию) или "acp" (настройки среды ACP по умолчанию).`}},"agents%2Eentries%2E*%2Esandbox%2Ebrowser%2EcdpSourceRange":{label:{"v1-k202bg-12":`Диапазон исходных адресов CDP браузера в песочнице агента`},help:{"v1-1q1qyso-1d":`Переопределение списка разрешённых исходных CIDR-диапазонов CDP для отдельного агента.`}},"agents%2Eentries%2E*%2Esandbox%2Ebrowser%2Enetwork":{label:{"v1-7jh9lr-t":`Сеть браузера в песочнице агента`},help:{"v1-13bdfww-4c":`Переопределение сети Docker для браузера в песочнице отдельного агента. Используйте сеть типа bridge; "none" не поддерживается, поскольку для управления браузером требуются опубликованные порты CDP.`}},"agents%2Eentries%2E*%2Esandbox%2Edocker%2EdangerouslyAllowContainerNamespaceJoin":{label:{"v1-n1z0dm-1f":`Разрешить подключение к пространству имён контейнера в Docker-песочнице агента`},help:{"v1-1xtnseb-2i":`ОПАСНОЕ переопределение для отдельного агента, разрешающее подключение к пространствам имён контейнеров в сетевом режиме Docker-песочницы.`}},"agents%2Eentries%2E*%2Esandbox%2Edocker%2Egpus":{label:{"v1-nbwnmy-p":`Графические процессоры Docker-песочницы агента`},help:{"v1-1kek1n2-1t":`Переопределение проброса графических процессоров Docker в контейнеры песочницы для отдельного агента.`}},"agents%2Eentries%2E*%2Eskills":{label:{"v1-nfmhzv-i":`Фильтр навыков агента`},help:{"v1-igchue-6v":`Необязательный список разрешённых навыков для этого агента. Если не указан, агент наследует agents.defaults.skills, когда этот параметр задан; иначе навыки не ограничиваются. Укажите [], чтобы отключить все навыки. Явно заданный список полностью заменяет унаследованные значения по умолчанию, а не объединяется с ними.`}},"agents%2Eentries%2E*%2EskillsLimits":{label:{"v1-dghtbk-j":`Лимиты Skills агента`},help:{"v1-1sv10v9-4y":`Необязательные переопределения лимитов подсистемы навыков для отдельного агента. Используйте, если агенту нужен другой лимит объёма промпта навыков, без добавления второго общего механизма ограничения контекста.`}},"agents%2Eentries%2E*%2EskillsLimits%2EmaxSkillsPromptChars":{label:{"v1-mg9zup-t":`Максимальное число символов в промпте Skills агента`},help:{"v1-dys63y-52":`Индивидуальное ограничение числа символов в промпте навыков для агента. Расширяет существующий путь skills.limits.maxSkillsPromptChars, а не задаёт то же ограничение через contextLimits.`}},"agents%2Eentries%2E*%2Esubagents%2EdelegationMode":{label:{"v1-bhpjpo-p":`Режим делегирования субагентам`},help:{"v1-1rkgh6p-4s":`Индивидуальная настройка приоритета делегирования субагентам для агента. Если не задана, в основной сессии этого агента используется "prefer", а в остальных — "suggest"; явно заданное значение "prefer" или "suggest" всегда имеет приоритет.`}},"agents%2Eentries%2E*%2EthinkingDefault":{label:{"v1-ymctpn-m":`Уровень размышления агента по умолчанию`},help:{"v1-173q7vy-43":`Необязательный уровень размышления по умолчанию для отдельного агента. Переопределяет agents.defaults.thinkingDefault для этого агента, если не задано переопределение на уровне сообщения или сессии.`}},"agents%2Eentries%2E*%2Etools%2EalsoAllow":{label:{"v1-1kf1wpw-u":`Дополнения к списку разрешённых инструментов агента`},help:{"v1-1550ui9-46":`Дополнительный список разрешённых инструментов для отдельного агента, дополняющий глобальную политику и политику профиля. Ограничивайте этот список, чтобы избежать случайного расширения прав специализированных агентов.`}},"agents%2Eentries%2E*%2Etools%2EbyProvider":{label:{"v1-w3qxm8-t":`Политика инструментов агента по провайдерам`},help:{"v1-mthxv9-4t":`Переопределения политики инструментов отдельного агента для конкретных провайдеров, позволяющие управлять возможностями в рамках каналов. Используйте, когда одному агенту нужны более строгие ограничения для одного провайдера, чем для остальных.`}},"agents%2Eentries%2E*%2Etools%2EcodeMode":{label:{"v1-1l1vsai-f":`Режим кода агента`},help:{"v1-118t8u5-65":`Параметры режима кода для отдельного агента. Явно заданный enabled переопределяет общие настройки активации модели и глобальные настройки активации по умолчанию; приоритет имеет переопределение codeMode модели для конкретного агента. Остальные параметры объединяются с tools.codeMode, переопределяя его значения без изменения активации.`}},"agents%2Eentries%2E*%2Etools%2Eexec%2EtimeoutSeconds":{label:{"v1-leof0k-s":`Тайм-аут выполнения агента (секунды)`}},"agents%2Eentries%2E*%2Etools%2Egithub":{label:{"v1-1nky9u1-y":`Переопределение учётной записи GitHub CLI для агента`},help:{"v1-mjwdh4-38":`Полное переопределение управляемой учётной записи GitHub CLI и данных автора Git для этого агента. Не задавайте этот параметр, чтобы наследовать системные учётные данные.`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EgitAuthor%2Eemail":{label:{"v1-1i4m01d-m":`Электронная почта автора Git для агента`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EgitAuthor%2Ename":{label:{"v1-1j0pl20-l":`Имя автора Git для агента`}},"agents%2Eentries%2E*%2Etools%2Egithub%2Ekind":{label:{"v1-14pqhd4-s":`Тип учётных данных GitHub для агента`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EprofileId":{label:{"v1-1fmzzvk-s":`Версия профиля GitHub для агента`}},"agents%2Eentries%2E*%2Etools%2Emessage%2Eactions%2Eallow":{label:{"v1-1cpyq5g-u":`Список разрешённых действий с сообщениями для агента`},help:{"v1-1g5gov3-67":`Список разрешённых действий с сообщениями в инструменте message для отдельного агента. Для публичных агентов в изолированной среде задайте минимальный список, например ["send"], чтобы чтение, редактирование, удаление, реакции и другие действия с сообщениями, специфичные для провайдера, оставались скрытыми и заблокированными.`}},"agents%2Eentries%2E*%2Etools%2Emessage%2EcrossContext%2EallowAcrossProviders":{label:{"v1-1js3r9e-1c":`Обмен сообщениями между контекстами агента (между провайдерами)`},help:{"v1-pehesn-49":`Индивидуальная настройка агента для отправки сообщений между провайдерами. Наследует глобальную настройку (по умолчанию: true). Установите false, чтобы запретить этому агенту отправку сообщений между провайдерами.`}},"agents%2Eentries%2E*%2Etools%2Emessage%2EcrossContext%2EallowWithinProvider":{label:{"v1-z29ji-19":`Обмен сообщениями агента между контекстами (один провайдер)`},help:{"v1-s9u09h-4t":`Ограничение для отдельного агента на отправку сообщений в другие беседы у того же провайдера. Установите false для этой настройки и allowAcrossProviders, чтобы публичные агенты могли отправлять сообщения только в текущую беседу.`}},"agents%2Eentries%2E*%2Etools%2Eprofile":{label:{"v1-kybcdd-i":`Профиль инструментов агента`},help:{"v1-1du76ix-57":`Переопределение профиля инструментов для отдельного агента, которому нужен другой базовый набор возможностей. Используйте выборочно, чтобы различия в политиках агентов оставались осознанными и доступными для проверки.`}},"agents%2Eentries%2E*%2Etools%2Eswarm":{label:{"v1-54zhti-b":`Рой агента`},help:{"v1-420ljs-2c":`Переопределение настроек роя для отдельного агента. Значения объединяются с конфигурацией верхнего уровня tools.swarm, имея приоритет над ней.`}},"agents%2Eentries%2E*%2EtypingMode":{label:{"v1-1nl61h4-h":`Режим индикации набора текста агента`},help:{"v1-oxir52-2e":`Переопределяет политику начала индикации набора текста по умолчанию для одного агента, не затрагивая остальных.`}},"agents%2Eentries%2E*%2EutilityModel":{label:{"v1-1k6g1v3-j":`Вспомогательная модель агента`},help:{"v1-1v9oskz-2z":`Необязательное переопределение вспомогательной модели для коротких внутренних задач отдельного агента. Имеет приоритет над agents.defaults.utilityModel.`}},"agents%2Eownership":{label:{"v1-uuzaon-q":`Поколение назначения агентов-владельцев`},help:{"v1-m2hp61-8g":`Постоянный маркер поколения назначения владельцев в многоагентной системе. "explicit" означает, что фоновые каналы, heartbeat, обращения к системному агенту, Talk, cron и операции CLI без явного указания агента должны определить владельца для конкретного интерфейса или заблокировать выполнение. OpenClaw автоматически устанавливает этот маркер при создании или миграции группы агентов; для единственного агента его можно не указывать.`}},approvals:{label:{"v1-1m405m7-9":`Согласования`},help:{"v1-4y3in-5w":`Настройки маршрутизации запросов на подтверждение выполнения команд и действий плагинов в чаты за пределами исходного сеанса. Оставьте их отключёнными, если операторам не требуется явно отслеживать подтверждения вне сеанса.`}},"approvals%2Eexec":{label:{"v1-hhphou-o":`Пересылка запросов на подтверждение выполнения команд`},help:{"v1-1r2mozk-5v":`Объединяет настройки пересылки запросов на подтверждение выполнения команд: включение, режим маршрутизации, фильтры и явно заданные получатели. Настройте этот раздел, если запросы на подтверждение должны поступать в рабочие каналы, а не только в исходную ветку обсуждения.`}},"approvals%2Eexec%2EagentFilter":{label:{"v1-1gg1zh3-l":`Фильтр агентов для запросов на подтверждение`},help:{"v1-xbuhd3-5i":'Необязательный список разрешённых идентификаторов агентов, для которых доступна пересылка запросов на подтверждение, например `["primary", "ops-agent"]`. Используйте его, чтобы ограничить охват пересылки и не отправлять в каналы уведомления о других агентах.'}},"approvals%2Eexec%2Eenabled":{label:{"v1-oukdkb-m":`Пересылать запросы на подтверждение выполнения команд`},help:{"v1-1t0whe8-5s":`Включает пересылку запросов на подтверждение выполнения команд настроенным получателям (по умолчанию: false). Оставьте отключённым в средах с низким риском и включайте, только если ответственным за подтверждение пользователям нужно видеть запросы в каналах.`}},"approvals%2Eexec%2Emode":{label:{"v1-733gc4-o":`Режим пересылки запросов на подтверждение`},help:{"v1-1dedfo4-69":`Определяет, куда отправляются запросы на подтверждение: "session" — в исходный чат, "targets" — настроенным получателям, "both" — по обоим маршрутам. Используйте "session" как базовый вариант и расширяйте охват, только если рабочий процесс требует дублирования.`}},"approvals%2Eexec%2EsessionFilter":{label:{"v1-1lqr9y4-n":`Фильтр сеансов для запросов на подтверждение`},help:{"v1-smeg8e-5u":'Необязательные фильтры ключей сеансов для сопоставления по подстроке или шаблонам регулярных выражений, например `["discord:", "^agent:ops:"]`. Используйте узкие шаблоны, чтобы в общие места назначения пересылались только запросы на подтверждение из нужных контекстов.'}},"approvals%2Eexec%2Etargets":{label:{"v1-uht69z-r":`Цели пересылки запросов на подтверждение`},help:{"v1-17ah848-5u":`Явно заданные цели доставки, используемые, когда режим пересылки включает цели; каждая содержит сведения о канале и месте назначения. Ограничивайте списки целей по принципу минимальных привилегий и проверяйте каждое место назначения, прежде чем включать широкую пересылку.`}},"approvals%2Eexec%2Etargets%5B%5D%2EaccountId":{label:{"v1-1pizj1x-q":`ID учётной записи для доставки запросов на подтверждение`},help:{"v1-16zopng-5e":`Необязательный выбор учётной записи для каналов с несколькими учётными записями, когда запросы на подтверждение должны направляться через определённую учётную запись. Используйте только в том случае, если для целевого канала настроено несколько учётных записей.`}},"approvals%2Eexec%2Etargets%5B%5D%2Echannel":{label:{"v1-14ol0m8-n":`Канал доставки запросов на подтверждение`},help:{"v1-ji1igl-59":`ID канала или провайдера для доставки пересылаемых запросов на подтверждение, например discord, slack или ID канала плагина. Используйте только допустимые ID каналов, чтобы доставка запросов не завершалась сбоем без уведомления из-за неизвестных маршрутов.`}},"approvals%2Eexec%2Etargets%5B%5D%2EthreadId":{label:{"v1-18ez6dm-p":`ID ветки доставки запросов на подтверждение`},help:{"v1-1axynw7-59":`Необязательная целевая ветка или тема для каналов, поддерживающих доставку пересылаемых запросов на подтверждение в ветки. Используйте, чтобы запросы на подтверждение оставались в рабочих ветках, а не в основных каналах.`}},"approvals%2Eexec%2Etargets%5B%5D%2Eto":{label:{"v1-19bm483-r":`Место назначения запросов на подтверждение`},help:{"v1-1ijng7e-5n":`Идентификатор назначения в целевом канале (ID канала, ID пользователя или корневое сообщение ветки — в зависимости от провайдера). Уточняйте значение для каждого провайдера, поскольку формат назначения различается между интеграциями каналов.`}},"approvals%2Eplugin":{label:{"v1-swf7m4-q":`Пересылка запросов на одобрение плагинов`},help:{"v1-1m6pzxv-6b":`Объединяет настройки пересылки запросов на одобрение плагинов: включение, режим маршрутизации, фильтры и явно заданные получатели. Не зависит от пересылки запросов на одобрение выполнения команд. Используйте эти настройки, если запросы на одобрение плагинов должны поступать в рабочие каналы.`}},"approvals%2Eplugin%2EagentFilter":{label:{"v1-12csxm6-s":`Фильтр агентов для одобрения плагинов`},help:{"v1-jb1bra-4b":'Необязательный список разрешённых ID агентов, для которых пересылаются запросы на одобрение плагинов, например `["primary", "ops-agent"]`. Используйте его, чтобы ограничить область пересылки.'}},"approvals%2Eplugin%2Eenabled":{label:{"v1-q9f62x-o":`Пересылать запросы на одобрение плагинов`},help:{"v1-1ntctaf-3v":`Включает пересылку запросов на одобрение плагинов настроенным получателям (по умолчанию: false). Не зависит от approvals.exec.enabled.`}},"approvals%2Eplugin%2Emode":{label:{"v1-1mgp0vb-v":`Режим пересылки запросов на одобрение плагинов`},help:{"v1-1h62vy4-3z":`Определяет, куда отправляются запросы на одобрение плагинов: "session" — в исходный чат, "targets" — настроенным получателям, "both" — по обоим направлениям.`}},"approvals%2Eplugin%2EsessionFilter":{label:{"v1-15vplo5-u":`Фильтр сеансов для одобрения плагинов`},help:{"v1-1eppxmt-57":'Необязательные фильтры ключей сеансов для сопоставления по подстроке или шаблонам регулярных выражений, например `["discord:", "^agent:ops:"]`. Используйте узкие шаблоны, чтобы пересылались только запросы на одобрение из нужных контекстов.'}},"approvals%2Eplugin%2Etargets":{label:{"v1-1snpvju-y":`Адресаты пересылки запросов на одобрение плагинов`},help:{"v1-o92qze-3k":`Явно заданные адресаты доставки, используемые, когда режим пересылки запросов на одобрение плагинов включает адресатов. Для каждого указываются канал и данные назначения.`}},"approvals%2Eplugin%2Etargets%5B%5D%2EaccountId":{label:{"v1-oxqv86-x":`ID учётной записи адресата запросов на одобрение плагинов`},help:{"v1-1wf3lqn-3j":`Необязательный параметр выбора учётной записи для каналов с несколькими учётными записями, когда запросы на одобрение плагинов должны направляться через определённую учётную запись.`}},"approvals%2Eplugin%2Etargets%5B%5D%2Echannel":{label:{"v1-1jz34xt-u":`Канал доставки запросов на одобрение плагинов`},help:{"v1-1mzhzi9-34":`ID канала или провайдера для доставки пересылаемых запросов на одобрение плагинов, например discord, slack или ID канала плагина.`}},"approvals%2Eplugin%2Etargets%5B%5D%2EthreadId":{label:{"v1-1beipnf-w":`ID ветки для доставки запросов на одобрение плагинов`},help:{"v1-1scaw9c-2v":`Необязательная целевая ветка или тема для каналов, поддерживающих доставку пересылаемых запросов на одобрение плагинов в ветки.`}},"approvals%2Eplugin%2Etargets%5B%5D%2Eto":{label:{"v1-1df4m22-y":`Место назначения запросов на одобрение плагинов`},help:{"v1-sh5te1-31":`Идентификатор места назначения в целевом канале (ID канала, ID пользователя или корневое сообщение ветки в зависимости от провайдера).`}},attachments:{label:{"v1-8925gh-b":`Вложения`},help:{"v1-1xvgkss-40":`Общие правила хранения верхнего уровня для провайдеров и инструментов, сохраняющих медиафайлы. Используйте ttlHours, чтобы ограничить срок хранения временно размещённых медиафайлов.`}},"attachments%2EttlHours":{label:{"v1-m9sx0s-w":`Срок хранения вложений TTL (часы)`},help:{"v1-1g90day-9e":`Необязательный срок хранения в часах для сохранённых медиафайлов, обрабатываемых общей очисткой по mtime. Оставьте незаданным, чтобы отключить эту очистку, или задайте значение, например 24 (1 день) или 168 (7 дней), для периодического удаления старых подготовленных медиафайлов. Управляемые исходящие медиафайлы (вложения, созданные в чате) исключены: для них действуют отдельные правила хранения с учётом SQLite и истории переписки.`}},audio:{label:{"v1-11wczsp-5":`Аудио`}},auth:{label:{"v1-5xz433-4":`Аутентификация`},help:{"v1-1eu3aud-5c":`Корневой раздел профилей аутентификации для учётных данных нескольких профилей провайдеров и порядка резервного переключения с учётом периодов ожидания. Используйте минимальные и явно заданные профили, чтобы поведение автоматического переключения оставалось проверяемым.`}},"auth%2Eorder":{label:{"v1-gadtii-i":`Порядок профилей аутентификации`},help:{"v1-1x6kknp-1w":`Упорядоченные идентификаторы профилей аутентификации для каждого провайдера (используются для автоматического резервного переключения).`}},"auth%2Eprofiles":{label:{"v1-nbj2kv-d":`Профили аутентификации`},help:{"v1-kzoqcn-1j":`Именованные профили аутентификации (провайдер + режим + необязательный адрес электронной почты).`}},bindings:{label:{"v1-1hcih9f-8":`Привязки`},help:{"v1-y7hrzb-4i":`Правила привязки верхнего уровня для маршрутизации и постоянного закрепления диалогов ACP. Используйте type=route для обычной маршрутизации и type=acp для постоянных привязок к среде выполнения ACP.`}},"bindings%5B%5D%2Eacp":{label:{"v1-1c1of5r-l":`Переопределения привязки ACP`},help:{"v1-1t4lisi-44":`Необязательные переопределения ACP для отдельных привязок с bindings[].type=acp. Этот уровень переопределяет значения по умолчанию agents.entries.*.runtime.acp для соответствующего диалога.`}},"bindings%5B%5D%2Eacp%2Ebackend":{label:{"v1-1qfk8bu-j":`Бэкенд привязки ACP`},help:{"v1-rsrbkp-2x":`Переопределение бэкенда ACP для этой привязки (если не задано, используется бэкенд ACP среды выполнения агента, затем глобальный acp.backend).`}},"bindings%5B%5D%2Eacp%2Ecwd":{label:{"v1-1w2wp4u-t":`Рабочий каталог привязки ACP`},help:{"v1-ngpkj0-1y":`Переопределение рабочего каталога для сеансов ACP, созданных из этой привязки.`}},"bindings%5B%5D%2Eacp%2Elabel":{label:{"v1-mc3w70-h":`Метка привязки ACP`},help:{"v1-azce82-23":`Понятная пользователю метка для отображения статуса и диагностики ACP в этом привязанном разговоре.`}},"bindings%5B%5D%2Eacp%2Emode":{label:{"v1-1mko9zx-g":`Режим привязки ACP`},help:{"v1-cgq8xv-1v":`Переопределение режима сеанса ACP для этой привязки (persistent или oneshot).`}},"bindings%5B%5D%2EagentId":{label:{"v1-1j1g5rg-g":`ID агента привязки`},help:{"v1-17ra0cl-4m":`ID целевого агента, который получает трафик при выполнении соответствующего правила привязки. Используйте только действительные ID настроенных агентов, чтобы избежать сбоев маршрутизации во время выполнения.`}},"bindings%5B%5D%2Ematch":{label:{"v1-13eg2e3-i":`Правило соответствия привязки`},help:{"v1-sc1w2e-51":`Объект правила соответствия, определяющий, когда применяется привязка, включая канал и необязательные ограничения по учётной записи или собеседнику. Задавайте узкие условия, чтобы агент случайно не перехватывал обработку в других контекстах.`}},"bindings%5B%5D%2Ematch%2EaccountId":{label:{"v1-1csp6k6-i":`ID учётной записи привязки`},help:{"v1-1d209g7-56":`Необязательный селектор учётной записи для каналов с несколькими учётными записями, позволяющий применять привязку только к одной из них. Используйте его, когда маршрут нужно ограничить конкретной учётной записью; в остальных случаях оставьте незаданным.`}},"bindings%5B%5D%2Ematch%2Echannel":{label:{"v1-mucsyp-f":`Канал привязки`},help:{"v1-d22m5-54":"Идентификатор канала или провайдера, к которому применяется эта привязка, например `telegram`, `discord` или ID канала плагина. Указывайте ключ канала точно так, как он задан в конфигурации, чтобы проверка привязки работала надёжно."}},"bindings%5B%5D%2Ematch%2EguildId":{label:{"v1-1hgwzxi-g":`ID гильдии привязки`},help:{"v1-jzzfj1-4x":`Необязательное ограничение по ID гильдии/сервера в стиле Discord для проверки привязок в многосерверных развёртываниях. Используйте, если одинаковые идентификаторы собеседников могут встречаться в разных гильдиях.`}},"bindings%5B%5D%2Ematch%2Epeer":{label:{"v1-1x3w5cz-i":`Условие привязки по собеседнику`},help:{"v1-gcjxff-4i":`Необязательное условие сопоставления для конкретных бесед, включающее тип и идентификатор собеседника. Используйте, если за агентом нужно закрепить только одну личную беседу, группу или канал.`}},"bindings%5B%5D%2Ematch%2Epeer%2Eid":{label:{"v1-181lr2n-f":`ID собеседника для привязки`},help:{"v1-86fbh7-4b":`Идентификатор беседы для сопоставления по собеседнику, например ID чата, канала или группы у провайдера. Указывайте его точно, чтобы избежать отсутствия совпадений без уведомления об ошибке.`}},"bindings%5B%5D%2Ematch%2Epeer%2Ekind":{label:{"v1-wii7p0-h":`Тип собеседника для привязки`},help:{"v1-uufscp-4x":`Тип беседы: "direct", "group", "channel" или устаревшее "dm" (устаревший псевдоним для direct). В новых конфигурациях используйте "direct" и задавайте kind в соответствии с семантикой канала.`}},"bindings%5B%5D%2Ematch%2Eroles":{label:{"v1-1ishhl3-d":`Роли для привязки`},help:{"v1-6s891m-4k":`Необязательный список фильтров по ролям для провайдеров, которые добавляют роли в контекст чата. Используйте для маршрутизации сообщений от привилегированных или операционных ролей специализированным агентам.`}},"bindings%5B%5D%2Ematch%2EteamId":{label:{"v1-1yh6sjs-f":`ID команды для привязки`},help:{"v1-hh9ps2-48":`Необязательное ограничение по ID команды/рабочего пространства для провайдеров, у которых чаты относятся к командам. Добавьте его, если нужно ограничить привязки контекстом одного рабочего пространства.`}},"bindings%5B%5D%2Esession":{label:{"v1-1weokpm-f":`Сеанс привязки`},help:{"v1-x325l2-4v":`Необязательные переопределения параметров сессии маршрута для разговоров, соответствующих этой привязке. Используйте их, когда для отдельного маршрута нужно сохранить того же агента, но иначе изолировать контекст сессии.`}},"bindings%5B%5D%2Esession%2EdmScope":{label:{"v1-1jcplmp-o":`Область сессии личных сообщений для привязки`},help:{"v1-10sg3xw-4s":`Необязательное переопределение области сессии личных сообщений для этой привязки маршрута. Например, можно оставить глобальное значение session.dmScope="main", а для отдельных собеседников использовать "per-account-channel-peer".`}},"bindings%5B%5D%2Esession%2EgroupScope":{label:{"v1-1dkb0a1-r":`Область групповой сессии для привязки`},help:{"v1-1ys2u7k-6n":`Необязательное переопределение области сессии группы или канала для этой привязки маршрута. Значение "per-group" сохраняет соответствующие чаты раздельными, а основная сессия агента наблюдает за ними в фоновом режиме независимо от dmScope; значение "main" объединяет их контекст с основной сессией и не требует наблюдения.`}},"bindings%5B%5D%2Etype":{label:{"v1-1l3bpjq-c":`Тип привязки`},help:{"v1-172mhtk-3o":`Вид привязки. Используйте "route" (или не указывайте значение для устаревших записей маршрутов) для обычной маршрутизации, а "acp" — для постоянных привязок разговоров ACP.`}},broadcast:{label:{"v1-awqjh0-j":`Ветки групп агентов`},help:{"v1-1tz72sr-6b":`Используйте ветки групп агентов, чтобы запускать несколько настроенных агентов в одном входящем диалоге, каждого в отдельном сеансе. Записи с указанием канала поддерживают ограниченное число последующих раундов; устаревшие массивы собеседников WhatsApp сохраняют однопроходный режим работы.`}},"broadcast%2E*":{label:{"v1-k5obp6-10":`Участники и параметры группы агентов`},help:{"v1-1b63zmt-7d":`Используйте идентификатор собеседника с указанием канала (например, "telegram:-100123"), чтобы настроить массив идентификаторов агентов или объект со строгой структурой, содержащий agents, mentionGating, maxRounds и maxTurns. Записи с указанием канала имеют приоритет над устаревшими ключами собеседников WhatsApp и допускают не более 16 агентов.`}},"broadcast%2E*%2Eagents":{label:{"v1-od29y1-o":`Участники группы агентов`},help:{"v1-g5o0ky-43":`Идентификаторы агентов-участников из agents.entries (не более 16). Каждый участник использует собственный сеанс для этого канала, учётной записи, диалога и ветки.`}},"broadcast%2E*%2EmaxRounds":{label:{"v1-1l8x0fc-q":`Максимальное число раундов группы агентов`},help:{"v1-i6v4jc-5a":`Максимальное число раундов на входящее сообщение, включая начальный раунд (целое число: 1–4, по умолчанию: 1). В последующих раундах участникам передаются ответы других участников в ограниченном объёме и с указанием авторов. Раунды прекращаются, когда все участники пропускают ход.`}},"broadcast%2E*%2EmaxTurns":{label:{"v1-aobwmz-p":`Максимальное число ходов группы агентов`},help:{"v1-1kiv8dy-72":`Максимальное число ходов участников на входящее сообщение во всех раундах (целое число: 1–32, по умолчанию: agents.length). Слоты резервируются перед параллельным запуском; это ограничивает число ходов агентов, а не отдельных фрагментов сообщений или отправок через инструменты. После перезапуска отсчёт лимитов не возобновляется.`}},"broadcast%2E*%2EmentionGating":{label:{"v1-1ykkdid-t":`Выбор участников группы агентов по упоминаниям`},help:{"v1-uay9zu-5u":`Выбирать только участников с явным @упоминанием, если найдены совпадения; иначе запускать всех участников (по умолчанию: true). Имена без @ и эмодзи не используются для выбора участников. Списки разрешённых каналов и правила допуска по-прежнему действуют.`}},"broadcast%2Estrategy":{label:{"v1-nm62ea-k":`Стратегия группы агентов`},help:{"v1-p4k9hu-4q":`Порядок выполнения участников: "parallel" (по умолчанию) запускает агентов одновременно, а "sequential" — в настроенном порядке. Каждый раунд завершается до начала следующего.`}},browser:{label:{"v1-13dzmen-7":`Браузер`},help:{"v1-5b74wi-5l":`Настройки работы браузера: локальное или удалённое подключение по CDP, маршрутизация профилей, создание скриншотов и снимков состояния. Сохраняйте значения по умолчанию, если ваш сценарий автоматизации не требует особых настроек транспорта браузера.`}},"browser%2EallowSystemProfileImport":{label:{"v1-17h3693-r":`Разрешить импорт системного профиля`},help:{"v1-1lsvlxw-5w":`Позволяет хостам macOS импортировать файлы cookie из локального системного профиля браузера семейства Chrome в управляемый профиль браузера OpenClaw. Отключите эту настройку, чтобы запретить импорт файлов cookie из профиля браузера и исключить связанный с ним запрос разрешения на доступ к Связке ключей macOS.`}},"browser%2EattachOnly":{label:{"v1-1pt3uds-o":`Режим браузера «Только подключение»`},help:{"v1-xaw7xm-4s":`Ограничивает работу браузера подключением к существующим сеансам без запуска локальных процессов браузера. Используйте этот режим, если всеми сеансами браузера управляет внешний удалённый провайдер CDP.`}},"browser%2EcdpUrl":{label:{"v1-oc982r-f":`URL CDP браузера`},help:{"v1-2n72jb-65":`URL конечной точки CDP/DevTools для подключения к экземпляру браузера под внешним управлением. Используйте его для централизованных хостов браузера, туннелей или подключения к существующим сеансам. Ограничьте доступ к URL доверенными сетевыми маршрутами.`}},"browser%2EdefaultProfile":{label:{"v1-gx1r6n-n":`Профиль браузера по умолчанию`},help:{"v1-a6xo96-52":`Имя профиля браузера, выбираемого по умолчанию, если при вызове профиль не указан явно. Используйте постоянный профиль с минимальными привилегиями, чтобы снизить риск случайного использования состояния из другого контекста.`}},"browser%2Eenabled":{label:{"v1-ur2izq-f":`Браузер включён`},help:{"v1-19qr4oj-56":`Включает поддержку браузера в Gateway для работы браузерных инструментов и процессов на базе CDP. Отключите, если автоматизация браузера не нужна, чтобы уменьшить поверхность атаки и объём работы при запуске.`}},"browser%2EevaluateEnabled":{label:{"v1-17r8d2b-o":`Выполнение скриптов в браузере`},help:{"v1-1oa79mq-59":`Включает вспомогательные средства выполнения скриптов в браузере во время работы, если эта возможность поддерживается. Оставьте отключённым, если вашим рабочим процессам достаточно снимков состояния и навигации и не требуется выполнение скриптов.`}},"browser%2EexecutablePath":{label:{"v1-nxumpk-n":`Путь к исполняемому файлу браузера`},help:{"v1-1plb4ki-6i":`Явно заданный путь к исполняемому файлу браузера, если автоматического обнаружения недостаточно в вашей среде. Используйте неизменный абсолютный путь или путь, начинающийся с ~ для обозначения домашнего каталога ОС, чтобы поведение при запуске оставалось предсказуемым после перезапусков.`}},"browser%2EextensionRelay":{label:{"v1-1fifm3z-n":`Ретранслятор расширения браузера`},help:{"v1-6ywlwr-4e":`Настройки совместимости аутентификации ретранслятора расширения Chrome. Сохраняйте поддержку устаревшего режима только до тех пор, пока она нужна ранее сопряжённым расширениям или внешним клиентам CDP.`}},"browser%2EextensionRelay%2EallowLegacyAuth":{label:{"v1-2qob0y-v":`Разрешить устаревшую аутентификацию ретранслятора браузера`},help:{"v1-pj2e90-63":`Временно разрешает устаревшие способы аутентификации ретранслятора: Bearer, Basic и передачу токена через подпротокол. По умолчанию: true на один переходный период. Установите false после перехода всех расширений и внешних клиентов CDP на Browser Relay Authentication v2.`}},"browser%2Eheadless":{label:{"v1-1ksb99t-l":`Режим браузера без графического интерфейса`},help:{"v1-1rswq8j-5a":`Принудительно запускает браузер без графического интерфейса, когда экземпляры браузера создаются локальным средством запуска. Оставьте этот режим включённым в серверных средах и отключайте только для отладки с видимым интерфейсом.`}},"browser%2EnoSandbox":{label:{"v1-nx4cbr-n":`Режим браузера без песочницы`},help:{"v1-slntux-4w":`Отключает флаги изоляции песочницы Chromium для сред, в которых песочница не работает во время выполнения. По возможности оставляйте этот режим выключенным, поскольку он снижает защиту за счёт изоляции процессов.`}},"browser%2Eprofiles":{label:{"v1-fih34f-g":`Профили браузера`},help:{"v1-1x8lf05-51":`Карта подключений именованных профилей браузера для явной маршрутизации к портам или URL CDP с необязательными метаданными. Используйте согласованные имена профилей и избегайте пересекающихся определений конечных точек.`}},"browser%2Eprofiles%2E*%2EattachOnly":{label:{"v1-32uv4v-w":`Режим профиля браузера только для подключения`},help:{"v1-2b5zs0-5a":`Переопределяет режим только для подключения на уровне профиля: пропускает локальный запуск браузера и подключается только к существующей конечной точке CDP. Полезно, когда один профиль управляется извне, а остальные запускаются локально.`}},"browser%2Eprofiles%2E*%2EcdpPort":{label:{"v1-1avgh1q-o":`Порт CDP профиля браузера`},help:{"v1-gx1yiq-49":`Локальный порт CDP для отдельного профиля, используемый при подключении к экземплярам браузера по порту, а не по URL. Используйте уникальные порты для каждого профиля, чтобы избежать конфликтов подключений.`}},"browser%2Eprofiles%2E*%2EcdpUrl":{label:{"v1-elwsl2-n":`URL CDP профиля браузера`},help:{"v1-x491r0-64":`URL конечной точки CDP/DevTools для отдельного профиля, используемый для явной маршрутизации к браузеру по имени профиля. Используйте его для удалённых хостов CDP, туннелей или профилей существующих сеансов, которые должны подключаться через работающую конечную точку Chrome DevTools.`}},"browser%2Eprofiles%2E*%2Edriver":{label:{"v1-1j1f8vg-m":`Драйвер профиля браузера`},help:{"v1-17byyx6-5r":`Режим драйвера браузера для отдельного профиля. Используйте "openclaw" (или устаревший "clawd") для профилей на базе CDP, "existing-session" для подключения через Chrome DevTools MCP или "extension" для ретрансляции через расширение Chrome с аутентификацией.`}},"browser%2Eprofiles%2E*%2EexecutablePath":{label:{"v1-154onzh-v":`Путь к исполняемому файлу браузера для профиля`},help:{"v1-29azyv-4w":`Путь к исполняемому файлу браузера для отдельного управляемого профиля, запускаемого локально. Переопределяет browser.executablePath и поддерживает пути, начинающиеся с ~ для обозначения домашнего каталога пользователя ОС.`}},"browser%2Eprofiles%2E*%2Eheadless":{label:{"v1-1dkezh4-t":`Режим без графического интерфейса для профиля браузера`},help:{"v1-p4jtgv-4u":`Переопределение режима без графического интерфейса для отдельного профиля при локальном запуске браузера. Используйте, если один профиль должен работать без графического интерфейса, не применяя browser.headless ко всем остальным профилям.`}},"browser%2Eprofiles%2E*%2EmcpArgs":{label:{"v1-1l3gwbt-v":`Аргументы Chrome MCP для профиля браузера`},help:{"v1-rc45ke-5g":`Дополнительные аргументы Chrome DevTools MCP для отдельного профиля при подключении в режиме existing-session, например --no-usage-statistics. Указанные здесь аргументы конечной точки переопределяют встроенное автоматическое подключение или выбор URL браузера.`}},"browser%2Eprofiles%2E*%2EmcpCommand":{label:{"v1-fncq59-y":`Команда Chrome MCP для профиля браузера`},help:{"v1-1xpty8o-2h":`Команда Chrome DevTools MCP для отдельного профиля при подключении в режиме existing-session. По умолчанию — npx.`}},"browser%2Eprofiles%2E*%2EuserDataDir":{label:{"v1-if29w-t":`Каталог пользовательских данных профиля браузера`},help:{"v1-5xvgex-9h":`Каталог пользовательских данных Chromium для отдельного профиля, используемый для подключения к существующему сеансу через Chrome DevTools MCP. Используйте его для Brave, Edge, Chromium или нестандартных профилей Chrome, если встроенный механизм автоматического подключения выбирает неверный каталог данных браузера на выбранном хосте или узле браузера. Пути, начинающиеся с ~, раскрываются в домашний каталог ОС.`}},"browser%2EsnapshotDefaults":{label:{"v1-1svdjip-p":`Настройки снимков браузера по умолчанию`},help:{"v1-v19wdy-4y":`Конфигурация создания снимков по умолчанию, используемая, когда при вызове не указаны явные параметры снимка. Настройте её для единообразного создания снимков во всех каналах и сценариях автоматизации.`}},"browser%2EsnapshotDefaults%2Emode":{label:{"v1-hishns-l":`Режим снимков браузера`},help:{"v1-joeyxp-5c":`Режим извлечения снимков по умолчанию, определяющий, как содержимое страницы преобразуется для обработки агентом. Выберите режим, обеспечивающий баланс между читаемостью, точностью и расходом токенов для ваших рабочих процессов.`}},"browser%2EssrfPolicy":{label:{"v1-18gkqpb-j":`Политика SSRF браузера`},help:{"v1-1qbp9im-5e":`Настройки защиты от подделки серверных запросов для запросов браузера и сетевой загрузки, которые могут обращаться к внутренним хостам. В рабочей среде сохраняйте строгие настройки по умолчанию и разрешайте доступ только к явно одобренным целям.`}},"browser%2EssrfPolicy%2EallowedHostnames":{label:{"v1-198z5mx-p":`Разрешённые имена хостов браузера`},help:{"v1-1rng39-2k":`Точные имена хостов или явно заданные IP-адреса, разрешённые проверками политики SSRF браузера. Ограничьте список необходимым минимумом.`}},"browser%2EssrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-1phaujk-11":`Разрешить уникальный локальный диапазон IPv6 в браузере`},help:{"v1-1glx5cy-2c":`Разрешить уникальные локальные адреса IPv6 (fc00::/7) для доверенных прокси-сред с fake-IP.`}},"browser%2EssrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-1tpn2sq-12":`Браузер: разрешить диапазон тестирования RFC 2544`},help:{"v1-10ateu3-2i":`Разрешает IP-адреса из диапазона тестирования RFC 2544 (198.18.0.0/15) для доверенных прокси-сред с подставными IP-адресами.`}},"browser%2EssrfPolicy%2EblockedHostnames":{label:{"v1-1iun7q1-p":`Браузер: заблокированные имена хостов`},help:{"v1-nug0we-6k":`Шаблоны имён хостов, блокируемых до разрешения DNS и применения разрешающих правил, даже если включён доступ к частной сети. Поддерживаются точные имена хостов и "*.example.com" только для поддоменов; чтобы заблокировать корневой домен, добавьте "example.com" отдельно. Если значение пустое или не задано, дополнительные запреты не применяются.`}},"browser%2EssrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-1cr58dw-15":`Браузер: разрешить доступ к частной сети (опасно)`},help:{"v1-17103pi-4m":`Разрешает инструментам браузера доступ к диапазонам адресов частных сетей. Если значение не задано, доступ по умолчанию отключён; включайте его только для явно доверенных ресурсов частной сети.`}},"browser%2EtabCleanup":{label:{"v1-gn8gk0-j":`Очистка вкладок браузера`},help:{"v1-1ctwaad-4y":`Политика очистки вкладок браузера, открытых сеансами основного агента, по мере возможности. Оставьте включённой, чтобы неиспользуемые вкладки песочницы или управляемого браузера не накапливались в длительно работающих экземплярах Gateway.`}},"browser%2EtabCleanup%2Eenabled":{label:{"v1-1blo8gh-r":`Очистка вкладок браузера включена`},help:{"v1-4sv97p-3u":`Включает очистку отслеживаемых неактивных вкладок браузера для сеансов основного агента. Отключайте только в том случае, если внешние инструменты полностью управляют жизненным циклом вкладок.`}},channels:{label:{"v1-1ju93md-8":`Каналы`},help:{"v1-12yv6ma-5n":`Настройки провайдеров каналов и общие значения по умолчанию, управляющие политиками доступа, отображением сигналов активности и поведением в отдельных интерфейсах. Храните значения по умолчанию централизованно и переопределяйте их для отдельных провайдеров только при необходимости.`}},"channels%2Edefaults":{label:{"v1-1wd3bq-g":`Настройки каналов по умолчанию`},help:{"v1-uz6veb-4p":`Поведение каналов по умолчанию для всех провайдеров, если настройки конкретного провайдера не заданы. Используйте для применения единой базовой политики перед настройкой отдельных провайдеров.`}},"channels%2Edefaults%2EbotLoopProtection":{label:{"v1-8f25je-r":`Защита от циклов между ботами по умолчанию`},help:{"v1-1lpznyk-4w":`Настройки защиты от циклов в паре по умолчанию для провайдеров каналов, поддерживающих защиту от циклического обмена между ботами. Переопределяйте их для конкретного провайдера, только если одному из каналов нужен другой лимит.`}},"channels%2Edefaults%2EbotLoopProtection%2EcooldownSeconds":{label:{"v1-wfzv79-x":`Пауза после обнаружения цикла между ботами по умолчанию (секунды)`},help:{"v1-1yl5ird-2z":`Длительность паузы в секундах для пары после превышения лимита циклического обмена. Значение по умолчанию для поддерживаемых каналов — 60.`}},"channels%2Edefaults%2EbotLoopProtection%2Eenabled":{label:{"v1-1245lyz-z":`Защита от циклов между ботами включена по умолчанию`},help:{"v1-3ruik-4r":`Включает защиту от циклов в паре по умолчанию для поддерживаемых каналов, если сообщения ботов могут поступать на обработку. Провайдеры по-прежнему могут отключать защиту, если боты игнорируются.`}},"channels%2Edefaults%2EbotLoopProtection%2EmaxEventsPerWindow":{label:{"v1-i8sfy1-y":`Лимит событий в окне для циклов между ботами по умолчанию`},help:{"v1-1u0mdjc-41":`Максимальное число событий, которыми пара отправитель/получатель может обменяться в заданном временном окне до начала блокировки. Значение по умолчанию для поддерживаемых каналов — 20.`}},"channels%2Edefaults%2EbotLoopProtection%2EwindowSeconds":{label:{"v1-vkrwg4-v":`Временное окно для циклов между ботами по умолчанию (секунды)`},help:{"v1-12xpmen-2m":`Длина скользящего окна в секундах для лимитов циклического обмена между парами ботов. По умолчанию для поддерживающих каналов — 60.`}},"channels%2Edefaults%2EcontextVisibility":{label:{"v1-xrgozf-q":`Видимость контекста по умолчанию`},help:{"v1-1hze3g1-5o":`Видимость дополнительного контекста по умолчанию для загруженного содержимого цитат, веток обсуждений и истории: "all" (сохранять весь контекст), "allowlist" (только отправители из списка разрешённых) или "allowlist_quote" (список разрешённых и сохранение явных цитат).`}},"channels%2Edefaults%2EgroupPolicy":{label:{"v1-1tib8bt-k":`Политика групп по умолчанию`},help:{"v1-ntl9m4-4n":`Политика групп по умолчанию для всех каналов: "open", "disabled" или "allowlist". Для большей безопасности в рабочей среде оставьте "allowlist", если широкое участие в группах не предусмотрено намеренно.`}},"channels%2Edefaults%2EheartbeatVisibility":{label:{"v1-knuq96-s":`Видимость сигналов активности по умолчанию`},help:{"v1-49bw75-4v":`Настройки видимости сигналов активности по умолчанию для сообщений о состоянии от провайдеров и каналов. Настройте их глобально, чтобы сократить поток сообщений о нормальной работе, сохранив видимость предупреждений.`}},"channels%2Edefaults%2EheartbeatVisibility%2EshowAlerts":{label:{"v1-8z6943-l":`Показывать предупреждения сигналов активности`},help:{"v1-8dk8zx-4g":`При значении true показывает предупреждения сигналов активности об ухудшении работы и ошибках, чтобы проблемы своевременно отображались в каналах операторов. Оставьте включённым в рабочей среде, чтобы сбои каналов были видны.`}},"channels%2Edefaults%2EheartbeatVisibility%2EshowOk":{label:{"v1-z25yzy-h":`Показывать сигналы нормальной работы`},help:{"v1-17tg3mk-4z":`При значении true показывает записи об успешных проверках работоспособности в выводе состояния каналов. Оставьте false в средах с большим количеством уведомлений и включайте только тогда, когда операторам нужны явные подтверждения нормальной работы.`}},"channels%2Edefaults%2EheartbeatVisibility%2EuseIndicator":{label:{"v1-16d7e6t-n":`Использовать индикатор проверки работоспособности`},help:{"v1-1w12cs2-4m":`Включает компактное отображение проверок работоспособности в виде индикатора вместо подробного текста состояния, если это поддерживается. Используйте режим индикатора на насыщенных панелях мониторинга с большим количеством активных каналов.`}},"channels%2Edefaults%2EimplicitMentions":{label:{"v1-1xvvux0-p":`Неявные упоминания по умолчанию`},help:{"v1-4gtdyv-48":`Политика по умолчанию, определяющая, активируют ли ответы боту, цитирование бота и сообщения в ветках с его участием каналы обмена сообщениями, поддерживающие эту функцию, без явного упоминания.`}},"channels%2Edefaults%2EimplicitMentions%2EquotedBot":{label:{"v1-190ozts-10":`Неявные упоминания при цитировании бота по умолчанию`},help:{"v1-va1u5v-2v":`По умолчанию считать цитирование сообщений бота неявным упоминанием. Для обратной совместимости значение по умолчанию — true.`}},"channels%2Edefaults%2EimplicitMentions%2EreplyToBot":{label:{"v1-1y8bnfy-12":`Неявные упоминания при ответе боту по умолчанию`},help:{"v1-lm44c3-39":`По умолчанию считать ответы на собственные сообщения бота неявными упоминаниями. Для обратной совместимости значение по умолчанию — true.`}},"channels%2Edefaults%2EimplicitMentions%2EthreadParticipation":{label:{"v1-lsf3e8-1a":`Неявные упоминания в ветках с участием бота по умолчанию`},help:{"v1-160205h-3o":`По умолчанию считать последующие сообщения в ветках, где участвовал бот, неявными упоминаниями. Для обратной совместимости значение по умолчанию — true.`}},"channels%2EmodelByChannel":{label:{"v1-k5b3gw-n":`Переопределения моделей для каналов`},help:{"v1-1b01spx-2p":`Сопоставление: провайдер -> идентификатор канала / собеседника в личных сообщениях -> переопределение модели (значения в формате provider/model или псевдонимы).`}},cli:{label:{"v1-mb8vjd-3":`CLI`}},cloudWorkers:{label:{"v1-1un3411-d":`Облачные воркеры`},help:{"v1-10carc4-5v":`Явно включаемые профили облачных воркеров для одноразовых удалённых окружений. Если этот раздел отсутствует или не содержит профилей, создание облачных воркеров остаётся недоступным, а текущее поведение статусов Gateway и узлов не меняется.`}},"cloudWorkers%2Edesktop":{label:{"v1-11xu2ur-r":`Рабочий стол облачного воркера (экспериментально)`},help:{"v1-vllayc-3n":`Включает экспериментальный интерфейс worker.desktop.observe и панель рабочего стола в Control UI для окружений облачных воркеров с поддержкой рабочего стола.`}},"cloudWorkers%2EpreparedPool":{label:{"v1-s34lt5-q":`Пул подготовленных облачных рабочих процессов`},help:{"v1-rw51o5-6b":`Лимиты для подготовленных облачных рабочих процессов, поддерживаемых в состоянии готовности для последующих сеансов. За зарезервированные ресурсы взимается плата как за работающие машины до завершения очистки на стороне провайдера; их фиксированный срок действия определяется фактической потребностью проекта и действующей политикой провайдера в отношении простоя.`}},"cloudWorkers%2EpreparedPool%2EmaxTotal":{label:{"v1-c8ff5f-u":`Лимит резерва готовых облачных воркеров`},help:{"v1-1mpd1dt-7u":`Общий для Gateway лимит неназначенных подготовленных облачных воркеров во всех проектах и профилях (по умолчанию: 4). Воркеры в процессе подготовки и резервные воркеры, удаление которых ещё не подтверждено, учитываются в лимите. Установите 0, чтобы удалить неназначенные резервы и отключить пополнение, сохранив повторное использование снимков и активные сеансы.`}},"cloudWorkers%2Eprofiles":{label:{"v1-xctezy-l":`Профили облачных воркеров`},help:{"v1-eii67l-3j":`Именованные профили облачных воркеров. Каждый профиль выбирает провайдера воркеров, зарегистрированного плагином, и содержит настройки этого провайдера.`}},"cloudWorkers%2Eprofiles%2E*":{label:{"v1-lsdort-k":`Профиль облачного воркера`},help:{"v1-1v2w7jl-4u":`Профиль облачного воркера, выбираемый по имени при создании окружения. Используйте поддерживаемые ссылки на учётные данные провайдера вместо размещения секретных данных непосредственно в этом блоке.`}},"cloudWorkers%2Eprofiles%2E*%2Einstall":{label:{"v1-1y9aivk-r":`Способ установки облачного воркера`},help:{"v1-blrtbf-74":`Способ установки воркера: "bundle" (по умолчанию) переносит установленную сборку Gateway с хешем содержимого и поддерживает выпущенные версии, версии для разработки и ещё не выпущенные версии; "npm" устанавливает ту же версию, что и у Gateway, и доступен только для выпущенных версий.`}},"cloudWorkers%2Eprofiles%2E*%2Eprovider":{label:{"v1-v7eu21-l":`Провайдер облачного воркера`},help:{"v1-1p4s4c1-44":`Идентификатор провайдера рабочих процессов, зарегистрированный плагином. Настроенный плагин должен предоставлять этот идентификатор, чтобы Gateway мог создавать среды на основе профиля.`}},"cloudWorkers%2Eprofiles%2E*%2EreadyWorkers":{label:{"v1-g69eog-x":`Целевой размер резерва готовых облачных воркеров`},help:{"v1-1nwve9s-7w":`Целевое число неназначенных подготовленных воркеров для каждого подходящего проекта, использующего этот профиль (по умолчанию: 1), с учётом общего для Gateway лимита пула подготовленных воркеров. Установите 0, чтобы отключить резервы этого профиля, сохранив повторное использование снимков. Воркеры в процессе подготовки и резервные воркеры, удаление которых ещё не подтверждено, учитываются в целевом числе.`}},"cloudWorkers%2Eprofiles%2E*%2Esettings":{label:{"v1-p040za-u":`Настройки провайдера облачных рабочих процессов`},help:{"v1-mq7u32-4j":`Настройки провайдера, проверяемые выбранным плагином. Используйте объекты SecretRef для значений, содержащих секреты; в непрозрачных настройках ссылки на секреты не разрешаются автоматически.`}},"cloudWorkers%2Eprofiles%2E*%2EsuspendAfter":{label:{"v1-2izlgm-y":`Время простоя до приостановки облачного рабочего процесса`},help:{"v1-1keuwgh-4w":`Автоматически освобождает ресурсы простаивающего облачного рабочего процесса по истечении указанного времени, например 45m или 2h; следующее сообщение создаёт замену. Минимум: 1m. Оставьте незаданным, чтобы рабочие процессы продолжали работать.`}},"cloudWorkers%2EprojectProfiles":{label:{"v1-10hp68d-t":`Профили облачных рабочих процессов для проектов`},help:{"v1-1kkfrif-46":`Имена профилей облачных рабочих процессов по умолчанию с ключами в виде нормализованных идентификаторов репозиториев в нижнем регистре (host/owner/repo). Явно указанные при отправке идентификаторы профилей имеют приоритет.`}},"cloudWorkers%2EprojectProfiles%2E*":{label:{"v1-17lr59o-s":`Профиль облачного рабочего процесса для проекта`},help:{"v1-1mux5u0-30":`Имя профиля облачного рабочего процесса, используемое по умолчанию, когда origin рабочего дерева сеанса соответствует этому идентификатору репозитория.`}},commands:{label:{"v1-15x4mpf-8":`Команды`},help:{"v1-1gi0dr2-5a":`Управляет доступностью команд в чате, ограничениями доступа по владельцу и доступом к командам с повышенными привилегиями у разных провайдеров. Сохраните значения по умолчанию, если вам не нужны более строгие ограничения для операторов или более широкая доступность команд.`}},"commands%2EallowFrom":{label:{"v1-axacxh-t":`Правила доступа к командам с повышенными привилегиями`},help:{"v1-7azkw-5g":`Задаёт правила разрешения привилегированных команд по каналам и отправителям для интерфейсов команд уровня владельца. Используйте конкретные идентификаторы пользователей соответствующего провайдера, чтобы привилегированные команды не были доступны широкой аудитории чата.`}},"commands%2Ebash":{label:{"v1-1nbpj93-n":`Разрешить команду Bash в чате`},help:{"v1-83ah7w-36":"Разрешить команде bash в чате (`!`; псевдоним `/bash`) выполнять команды оболочки хоста (по умолчанию: false; требуется tools.elevated)."}},"commands%2EbashForegroundMs":{label:{"v1-1vfppjv-r":`Время работы Bash на переднем плане (мс)`},help:{"v1-1o0o4dw-2c":`Время ожидания bash перед переходом в фоновый режим (по умолчанию: 2000; 0 — немедленный переход в фоновый режим).`}},"commands%2Econfig":{label:{"v1-14wzjd5-d":`Разрешить /config`},help:{"v1-151bb7c-21":`Разрешить команде /config в чате читать и записывать конфигурацию на диске (по умолчанию: false).`}},"commands%2Edebug":{label:{"v1-12w2s6q-c":`Разрешить /debug`},help:{"v1-y1lc3j-1y":`Разрешить команду /debug в чате для переопределения настроек только на время работы (по умолчанию: false).`}},"commands%2Emcp":{label:{"v1-16ynh2x-a":`Разрешить /mcp`},help:{"v1-1rtwcgd-2o":`Разрешить команде /mcp в чате управлять конфигурацией серверов MCP в OpenClaw в разделе mcp.servers (по умолчанию: false).`}},"commands%2Enative":{label:{"v1-11r5pqs-f":`Нативные команды`},help:{"v1-dighr2-5n":`Регистрирует нативные слеш-команды и команды меню в каналах, поддерживающих регистрацию команд (Discord, Slack, Telegram). Оставьте включённым, чтобы команды было проще находить, если только вы намеренно не используете исключительно текстовые команды.`}},"commands%2EnativeSkills":{label:{"v1-hpi0k3-l":`Нативные команды навыков`},help:{"v1-19gtqci-5h":`Регистрирует нативные команды навыков, чтобы пользователи могли вызывать навыки непосредственно из меню команд провайдера, если это поддерживается. Согласуйте эту настройку с вашей политикой использования навыков, чтобы доступные команды соответствовали ожиданиям операторов.`}},"commands%2EownerAllowFrom":{label:{"v1-1bc6u1a-e":`Владельцы команд`},help:{"v1-1di38gv-3y":`Явный список разрешённых владельцев для команд, доступных только владельцам. Используйте идентификаторы в формате канала (при необходимости с префиксом, например "whatsapp:+15551234567"). '*' игнорируется.`}},"commands%2Eplugins":{label:{"v1-culv09-e":`Разрешить /plugins`},help:{"v1-akwy9y-33":`Разрешить команду чата /plugins для просмотра списка обнаруженных плагинов и их включения или отключения в конфигурации (по умолчанию: false).`}},"commands%2Erestart":{label:{"v1-d0qh1l-d":`Разрешить перезапуск`},help:{"v1-m32fv2-27":`Разрешить /restart, /update и внешние запросы на перезапуск через SIGUSR2 (по умолчанию: true).`}},"commands%2Etext":{label:{"v1-5g1c88-d":`Текстовые команды`},help:{"v1-1utu76s-5j":`Включает распознавание текстовых команд в сообщениях чата в дополнение к встроенным интерфейсам команд, если они доступны. Оставьте включённым для совместимости с каналами, которые не поддерживают встроенную регистрацию команд.`}},cron:{label:{"v1-1qlte4b-b":`Автоматизации`},help:{"v1-4md8ic-5u":`Глобальные настройки планировщика для сохранённых автоматизаций, параллельного выполнения, резервной доставки и срока хранения сеансов выполнения. Используйте значения по умолчанию, если не увеличиваете объём автоматизаций и не подключаете внешние обработчики вебхуков.`}},"cron%2Eenabled":{label:{"v1-1amdki2-j":`Автоматизации включены`},help:{"v1-y8otx6-5i":`Включает выполнение автоматизаций по сохранённым расписаниям, управляемым Gateway. Оставьте включённым для обычной работы напоминаний и автоматизаций. Отключайте только для приостановки всех автоматизаций без удаления заданий.`}},"cron%2EsessionRetention":{label:{"v1-1cvkclx-t":`Срок хранения сеансов автоматизаций`},help:{"v1-4wagu6-7e":"Определяет, как долго хранятся сеансы завершённых запусков автоматизаций до очистки (`24h`, `7d`, `1h30m` или `false` для отключения очистки; нулевая длительность, например `0h`, также отключает очистку; по умолчанию: `24h`). Сократите срок хранения, чтобы уменьшить рост объёма данных при частых запусках по расписанию."}},"cron%2EskipMissedJobs":{label:{"v1-1wkngn0-x":`Пропускать пропущенные запуски повторяющихся автоматизаций`},help:{"v1-w9wfmo-66":`При запуске Gateway пропускает пропущенные запуски по расписаниям cron/every и планирует следующие будущие запуски вместо выполнения пропущенных. По умолчанию: false. Включите, чтобы избежать устаревших напоминаний после простоя; пропущенные одноразовые задания at по-прежнему выполняются.`}},"cron%2EwebhookSsrfPolicy":{label:{"v1-xrkjiu-v":`Политика SSRF для вебхуков автоматизаций`},help:{"v1-1xlfqnu-5h":`Политика SSRF, применяемая ко всем исходящим вебхукам автоматизаций. Частные, петлевые, локальные для канала и внутренние адреса остаются заблокированными, если эта политика явно их не разрешает. Оставьте параметр незаданным, чтобы сохранить строгие ограничения доставки.`}},"cron%2EwebhookSsrfPolicy%2EallowedHostnames":{label:{"v1-w1bhls-11":`Разрешённые имена хостов для вебхуков автоматизаций`},help:{"v1-1i94hyz-3n":`Точные имена хостов или IP-адреса, разрешённые для доставки вебхуков автоматизаций, включая адреса, которые иначе были бы заблокированы. Добавляйте в список только необходимое.`}},"cron%2EwebhookSsrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-1p9upj5-1d":`Разрешить уникальные локальные адреса IPv6 для вебхуков автоматизаций`},help:{"v1-rke0oj-3b":`Разрешает отправку вебхуков автоматизаций на уникальные локальные адреса IPv6 (fc00::/7). Используйте только в доверенных средах с прокси fake-IP.`}},"cron%2EwebhookSsrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-y1ryjx-1e":`Разрешить диапазон для тестирования производительности RFC 2544 для вебхуков автоматизаций`},help:{"v1-x1usg4-3h":`Разрешает отправку вебхуков автоматизаций на IP-адреса из диапазона RFC 2544 для тестирования производительности (198.18.0.0/15). Используйте только в доверенных средах с прокси fake-IP.`}},"cron%2EwebhookSsrfPolicy%2EblockedHostnames":{label:{"v1-6c1248-11":`Заблокированные имена хостов для вебхуков автоматизаций`},help:{"v1-16cv1ic-6a":`Шаблоны имён хостов, блокируемых до разрешения DNS и применения разрешающих правил при доставке вебхуков автоматизаций. Поддерживаются точные имена хостов и "*.example.com" только для поддоменов; для блокировки корневого домена добавьте "example.com" отдельно. Если значение пустое или не задано, дополнительные запреты не применяются.`}},"cron%2EwebhookSsrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-o4lenl-1h":`Разрешить вебхукам автоматизаций доступ к частной сети (опасно)`},help:{"v1-1n9710c-3t":`Разрешает отправку вебхуков автоматизаций на адреса в частных и внутренних сетях. Оставьте отключённым, если не все настроенные адреса назначения вебхуков являются доверенными.`}},"cron%2EwebhookToken":{label:{"v1-18ivgo6-w":`Токен Bearer для вебхуков автоматизаций`},help:{"v1-1l90hxg-5l":`Токен Bearer, добавляемый к POST-запросам доставки вебхуков автоматизаций в режиме вебхука. Предпочтительно использовать подстановку секретов или переменных окружения и регулярно менять этот токен, если общие конечные точки вебхуков доступны из интернета.`}},desktop:{label:{"v1-rs698z-7":`Рабочий стол`}},"desktop%2Ehost":{label:{"v1-rh14ls-d":`Локальный рабочий стол`},help:{"v1-99weio-30":`Наблюдение за рабочим столом сопряжённых узлов или экспериментальным источником на хосте Gateway с использованием локального VNC-сервера.`}},"desktop%2Ehost%2Eenabled":{label:{"v1-10wailb-f":`Общий доступ к рабочему столу`},help:{"v1-m9lbcj-83":`Включает источник рабочего стола на этом компьютере. Для сопряжённых узлов macOS, Windows и Linux он включён по умолчанию; явно заданная настройка общего доступа в настольном приложении имеет приоритет. Источник Labs на хосте Gateway по умолчанию отключён и применяет изменения без перезапуска. После изменения конфигурации рабочего стола сопряжённого узла перезапустите этот узел.`}},"desktop%2Ehost%2Emanaged":{label:{"v1-3hgdsm-q":`Управляемый рабочий стол хоста Linux`},help:{"v1-1r7n22m-49":`Запускает и контролирует работу рабочего стола TigerVNC/XFCE без физического дисплея в Linux, доступного только через loopback. Явно указанный порт или уже работающий VNC-сервер на порту по умолчанию по-прежнему имеют приоритет.`}},"desktop%2Ehost%2EpasswordFile":{label:{"v1-pdfkek-n":`Локальный файл пароля VNC`},help:{"v1-1m5lsox-37":`Абсолютный путь к файлу пароля VNC. В macOS не указывайте его, чтобы вводить учётные данные при открытии средства просмотра рабочего стола.`}},"desktop%2Ehost%2Eport":{label:{"v1-1bci0ps-e":`Локальный порт VNC`},help:{"v1-1ku4w9b-2b":`Порт RFB на интерфейсе loopback уже запущенного VNC-сервера на этом компьютере (по умолчанию: 5900).`}},diagnostics:{label:{"v1-1stxhg7-b":`Диагностика`},help:{"v1-1d5rnym-5p":`Настройки диагностики для целевой трассировки, экспорта телеметрии и проверки кэша при отладке. В рабочей среде используйте минимальный набор диагностики и включайте сбор подробных данных только при исследовании проблем.`}},"diagnostics%2EcacheTrace":{label:{"v1-d7o58-b":`Трассировка кэша`},help:{"v1-10523zm-5b":`Настройки журналирования трассировки кэша для наблюдения за решениями о кэшировании и контекстом полезной нагрузки при встроенных запусках. Включайте временно для отладки, а затем отключайте, чтобы сократить объём конфиденциальных данных в журналах.`}},"diagnostics%2EcacheTrace%2Eenabled":{label:{"v1-u2445x-j":`Трассировка кэша включена`},help:{"v1-2c1umi-1v":`Записывать в журнал снимки трассировки кэша при встроенных запусках агента (по умолчанию: false).`}},"diagnostics%2Eenabled":{label:{"v1-17k9ppq-j":`Диагностика включена`},help:{"v1-a46pxt-4h":`Общий переключатель вывода диагностических данных в журналы и каналы телеметрии. По умолчанию включён; устанавливайте false только в средах со строгими ограничениями.`}},"diagnostics%2Eflags":{label:{"v1-x05x98-h":`Флаги диагностики`},help:{"v1-x4w5ok-33":`Включение целевых диагностических журналов по флагу (например, ["telegram.http"]). Поддерживаются подстановочные шаблоны, такие как "telegram.*" или "*".`}},"diagnostics%2Eotel":{label:{"v1-wfx8h0-d":`OpenTelemetry`},help:{"v1-isgk7l-5b":`Настройки экспорта OpenTelemetry для трассировок, метрик и журналов, создаваемых компонентами Gateway. Используйте для интеграции с централизованными системами наблюдаемости и конвейерами распределённой трассировки.`}},"diagnostics%2Eotel%2EcaptureContent":{label:{"v1-1xxk57n-t":`Захват содержимого OpenTelemetry`},help:{"v1-19tid4t-2t":`Захват содержимого спанов OTEL, включаемый явно. По умолчанию отключён; значение true включает захват содержимого несистемных сообщений и инструментов.`}},"diagnostics%2Eotel%2Eenabled":{label:{"v1-bh3lp-l":`OpenTelemetry включён`},help:{"v1-193bm0-5b":`Включает конвейер экспорта OpenTelemetry для трассировок, метрик и журналов с учётом заданных настроек конечной точки и протокола. Оставьте отключённым, пока конечная точка коллектора и аутентификация не будут полностью настроены.`}},"diagnostics%2Eotel%2Eendpoint":{label:{"v1-mpv6hp-m":`Конечная точка OpenTelemetry`},help:{"v1-4rrd1x-4y":`URL конечной точки коллектора для передачи экспортируемых данных OpenTelemetry, включая схему и порт. Используйте доступную доверенную конечную точку коллектора и отслеживайте ошибки приёма данных после развёртывания.`}},"diagnostics%2Eotel%2EflushIntervalMs":{label:{"v1-1rqdzae-x":`Интервал отправки OpenTelemetry (мс)`},help:{"v1-1moqogc-53":`Интервал в миллисекундах для периодической отправки телеметрии из буферов в коллектор. Увеличьте его, чтобы сократить частоту отправок, или уменьшите, чтобы быстрее получать данные при активном реагировании на инциденты.`}},"diagnostics%2Eotel%2Eheaders":{label:{"v1-kknm0u-l":`Заголовки OpenTelemetry`},help:{"v1-s26t2a-52":`Дополнительные HTTP-заголовки, отправляемые с запросами экспорта OpenTelemetry. Часто используются для аутентификации арендатора или маршрутизации. Храните секреты в значениях, получаемых из переменных окружения, и не добавляйте лишние заголовки.`}},"diagnostics%2Eotel%2Elogs":{label:{"v1-1o5ymv2-q":`Экспорт журналов OpenTelemetry включён`},help:{"v1-12wo6rv-4k":`Включает экспорт журналов через OpenTelemetry в дополнение к локальным приёмникам журналов. Используйте, когда требуется централизованная корреляция журналов разных сервисов и агентов.`}},"diagnostics%2Eotel%2ElogsEndpoint":{label:{"v1-7bltwc-r":`Конечная точка журналов OpenTelemetry`},help:{"v1-1vgzldu-40":`Отдельная конечная точка OTLP/HTTP для журналов. Если задана, переопределяет diagnostics.otel.endpoint и OTEL_EXPORTER_OTLP_ENDPOINT только для экспорта журналов.`}},"diagnostics%2Eotel%2ElogsExporter":{label:{"v1-16nvfm8-r":`Экспортёр журналов OpenTelemetry`},help:{"v1-9bzywd-5q":`Приёмник экспорта журналов для diagnostics.otel.logs. Используйте "otlp" для настроенной конечной точки журналов OTLP, "stdout" для вывода одной записи JSON на строку stdout в конвейерах журналов контейнеров и "both", если нужны оба приёмника.`}},"diagnostics%2Eotel%2EmetricNamePrefix":{label:{"v1-hrys5-w":`Префикс имён метрик OpenTelemetry`},help:{"v1-1epdpi9-b2":`Заменяет стандартный префикс "openclaw." в именах собственных метрик OpenClaw. Используйте пустую строку, чтобы удалить префикс, или строку длиной до 128 символов из букв ASCII, цифр, знаков подчёркивания, точек, дефисов и косых черт, начинающуюся с буквы. Добавьте нужный разделитель, например "acme."; стандартные имена метрик gen_ai.* остаются без изменений. При изменении этого значения необходимо обновить панели мониторинга и оповещения, использующие старые имена в запросах.`}},"diagnostics%2Eotel%2Emetrics":{label:{"v1-1o16jew-t":`Экспорт метрик OpenTelemetry включён`},help:{"v1-13r4cf4-4x":`Включает экспорт метрик на настроенный адрес коллектора OpenTelemetry. Оставьте включённым для панелей мониторинга состояния системы и отключайте только при необходимости минимизировать объём метрик.`}},"diagnostics%2Eotel%2EmetricsEndpoint":{label:{"v1-ahl7w6-u":`Адрес для метрик OpenTelemetry`},help:{"v1-qlfh7x-47":`Отдельный адрес OTLP/HTTP для метрик. Если задан, переопределяет diagnostics.otel.endpoint и OTEL_EXPORTER_OTLP_ENDPOINT только для экспорта метрик.`}},"diagnostics%2Eotel%2Eprotocol":{label:{"v1-4ikcpk-m":`Протокол OpenTelemetry`},help:{"v1-17ine8s-5e":`Транспортный протокол OTel для экспорта телеметрии. Допускается только "http/protobuf"; выполните "openclaw doctor --fix", чтобы исправить сохранённое устаревшее значение "grpc" или получить инструкции по ручному редактированию для конкретного источника.`}},"diagnostics%2Eotel%2EsampleRate":{label:{"v1-1qd4hmt-v":`Доля выборки трассировок OpenTelemetry`},help:{"v1-brcwep-50":`Доля выборки трассировок (0–1), определяющая, какая часть данных трассировки экспортируется в системы наблюдаемости. Низкие значения уменьшают накладные расходы и затраты, а высокие повышают детализацию отладки.`}},"diagnostics%2Eotel%2EserviceName":{label:{"v1-1b6j4ku-q":`Имя сервиса OpenTelemetry`},help:{"v1-1hpiqon-5d":`Имя сервиса, передаваемое в атрибутах ресурса телеметрии для идентификации этого экземпляра Gateway в системах наблюдаемости. Используйте стабильные имена, чтобы панели мониторинга и оповещения оставались согласованными при повторных развёртываниях.`}},"diagnostics%2Eotel%2Etraces":{label:{"v1-ypycsr-s":`Трассировки OpenTelemetry включены`},help:{"v1-j7zrrp-4s":`Включает экспорт трассировок на настроенный адрес коллектора OpenTelemetry. Оставьте включённым, если трассировки нужны для анализа задержек или отладки, и отключите, если нужны только метрики и журналы.`}},"diagnostics%2Eotel%2EtracesEndpoint":{label:{"v1-1m2hzmb-t":`Конечная точка трассировок OpenTelemetry`},help:{"v1-8yw5p1-43":`Конечная точка OTLP/HTTP для трассировок как отдельного типа телеметрии. Если задана, переопределяет diagnostics.otel.endpoint и OTEL_EXPORTER_OTLP_ENDPOINT только для экспорта трассировок.`}},discovery:{label:{"v1-l2sr05-9":`Обнаружение`},help:{"v1-1sqleij-4w":`Настройки обнаружения сервисов для локальных объявлений mDNS и необязательного оповещения о присутствии за пределами локальной сети. Ограничивайте обнаружение предполагаемыми сетями, чтобы избежать утечки метаданных сервисов.`}},"discovery%2Emdns":{label:{"v1-1sefhx1-e":`Обнаружение через mDNS`},help:{"v1-vtbyyq-4w":`Группа настроек обнаружения через mDNS для объявлений в локальной сети и управления поведением обнаружения. Для обычного обнаружения в локальной сети используйте минимальный режим, если дополнительные метаданные не требуются.`}},"discovery%2Emdns%2Emode":{label:{"v1-ybee7c-j":`Режим обнаружения через mDNS`},help:{"v1-1p28pd5-2m":`Режим широковещательной рассылки mDNS ("minimal" — по умолчанию, "full" включает cliPath/sshPort, "off" отключает mDNS).`}},"discovery%2EwideArea":{label:{"v1-1u2kx7q-j":`Обнаружение за пределами локальной сети`},help:{"v1-1akkqjm-53":`Группа настроек обнаружения для публикации сведений о присутствии за пределами локального сегмента сети. Включайте только в развёртываниях, где намеренно собираются сведения о присутствии шлюзов на разных площадках.`}},"discovery%2EwideArea%2Edomain":{label:{"v1-1uxd2qe-q":`Домен обнаружения за пределами локальной сети`},help:{"v1-rxrygo-4m":`Необязательный домен одноадресного DNS-SD для обнаружения за пределами локальной сети, например openclaw.internal. Используйте, если намеренно публикуете сведения для обнаружения шлюза за пределами локальной области mDNS.`}},env:{label:{"v1-1zc80q-b":`Окружение`},help:{"v1-1ao5po6-55":`Настройки импорта и переопределения окружения для передачи переменных процессу шлюза во время выполнения. Используйте этот раздел для управления загрузкой окружения оболочки и явным заданием переменных.`}},"env%2EshellEnv":{label:{"v1-hd6v1l-o":`Импорт окружения оболочки`},help:{"v1-1gw487t-4y":`Настройки импорта переменных окружения из вашей оболочки входа при запуске. Оставьте включённым, если вы используете секреты или настройки PATH, заданные в профиле.`}},"env%2EshellEnv%2Eenabled":{label:{"v1-9bbyvk-w":`Импорт окружения оболочки включён`},help:{"v1-5tiuup-5u":`Включает загрузку переменных окружения из профиля оболочки пользователя при инициализации. Оставьте включённым на машинах разработчиков или отключите в сервисных средах с ограниченным доступом и явным управлением переменными окружения.`}},"env%2EshellEnv%2EtimeoutMs":{label:{"v1-g0i751-11":`Тайм-аут импорта окружения оболочки (мс)`},help:{"v1-nsk2yf-5c":`Максимальное время в миллисекундах, отведённое на получение окружения оболочки до перехода к резервному поведению. Уменьшите тайм-аут для более быстрого запуска или увеличьте его, если инициализация оболочки занимает много времени.`}},"env%2Evars":{label:{"v1-grhbhj-u":`Переопределения переменных окружения`},help:{"v1-yxc3z7-5n":`Явные переопределения переменных окружения в виде пар ключ/значение, добавляемые в окружение процесса OpenClaw. Используйте их для предсказуемой настройки окружения, не полагаясь только на побочные эффекты профиля оболочки.`}},gateway:{label:{"v1-7gz34p-7":`Gateway`},help:{"v1-19p5env-5v":`Параметры работы Gateway: режим привязки, аутентификация, Control UI, удалённый транспорт и средства обеспечения безопасности эксплуатации. Сохраняйте безопасные значения по умолчанию, если вы не планируете открывать доступ к Gateway за пределами доверенных локальных интерфейсов.`}},"gateway%2EallowRealIpFallback":{label:{"v1-1xoyrfn-w":`Разрешить резервное использование x-real-ip в Gateway`},help:{"v1-1wr3qmw-4c":`Разрешает резервное использование x-real-ip при отсутствии x-forwarded-for в сценариях с прокси. Оставьте отключённым, если ваша инфраструктура входящего трафика не требует такого поведения для совместимости.`}},"gateway%2Eauth":{label:{"v1-1uh91et-c":`Аутентификация Gateway`},help:{"v1-70b6ni-50":`Политика аутентификации для доступа к Gateway по HTTP/WebSocket: режим, учётные данные, поведение доверенного прокси и ограничение частоты запросов. Оставляйте аутентификацию включённой во всех развёртываниях с доступом за пределами loopback.`}},"gateway%2Eauth%2EallowTailscale":{label:{"v1-fyw82a-11":`Разрешить аутентификацию Gateway по идентификационным данным Tailscale`},help:{"v1-vqtmgw-53":`Позволяет проходить проверки аутентификации Gateway через доверенные механизмы идентификации Tailscale, если они настроены. Используйте это только при надёжной защите идентификационных данных в вашей сети tailnet и если от этого зависят рабочие процессы операторов.`}},"gateway%2Eauth%2EidentityScopes":{label:{"v1-1y4ivis-t":`Права Gateway по идентификационным данным`},help:{"v1-1h0zxy7-5n":`Сопоставляет проверенные идентификационные данные от доверенного прокси или Tailscale с правами оператора, действующими только в рамках соединения. Ключи с адресами электронной почты сопоставляются без учёта регистра; выданные права дополняют права устройства до применения ограничения прав соединения.`}},"gateway%2Eauth%2Emode":{label:{"v1-av63g8-h":`Режим аутентификации Gateway`},help:{"v1-j8rodq-9t":`Режим аутентификации Gateway: "none", "token", "password" или "trusted-proxy" в зависимости от архитектуры сетевого периметра. Режим token/password выбирает настроенный секрет (gateway.auth.token или gateway.auth.password); клиенты могут передавать его в любом из двух полей аутентификации при подключении. Используйте token/password при прямом доступе извне, а trusted-proxy — только за надёжно защищёнными прокси с проверкой идентификационных данных.`}},"gateway%2Eauth%2Epassword":{label:{"v1-1b8jhsq-g":`Пароль Gateway`},help:{"v1-1ndt0u2-4g":`Общий секрет, выбираемый при gateway.auth.mode=password. Клиенты могут передавать его в auth.token или auth.password. Для Tailscale Funnel требуется режим аутентификации по паролю.`}},"gateway%2Eauth%2ErateLimit":{label:{"v1-cb86oa-n":`Ограничение частоты запросов аутентификации Gateway`},help:{"v1-1kstr42-54":`Настройки ограничения частоты попыток входа и аутентификации для снижения риска подбора учётных данных на границе Gateway. Не отключайте в средах с внешним доступом и настраивайте пороговые значения с учётом обычного объёма трафика.`}},"gateway%2Eauth%2Etoken":{label:{"v1-nq7dbs-d":`Токен Gateway`},help:{"v1-16i7cxs-5q":`Общий секрет, используемый при gateway.auth.mode=token — режиме по умолчанию для новой локальной настройки. Клиенты могут передавать его в auth.token или auth.password. Для привязки к адресам, отличным от loopback, требуется включённый режим аутентификации.`}},"gateway%2Eauth%2EtrustedProxy":{label:{"v1-17f14p4-q":`Аутентификация Gateway через доверенный прокси`},help:{"v1-12fsi5d-58":`Сопоставление заголовков аутентификации через доверенный прокси для вышестоящих поставщиков удостоверений, добавляющих сведения о пользователе. Используйте только с известными CIDR-диапазонами прокси и строгими списками разрешённых заголовков, чтобы предотвратить подделку заголовков идентификации.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc":{label:{"v1-1hiowhq-12":`Идентификация GitHub через Cloudflare Access OIDC`},help:{"v1-1puth4k-6t":`Необязательные подтверждённые данные учётной записи GitHub от выбранного провайдера Cloudflare Access OIDC. Требуются стандартные заголовки Access с адресом электронной почты и утверждением. При отсутствии атрибутов профили остаются привязанными только к электронной почте; существующие роли профилей и настройки соавторства сохраняются.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2EgithubAccountIdClaim":{label:{"v1-appie6-n":`Атрибут ID учётной записи GitHub`},help:{"v1-pcaaw7-57":`Точное имя передаваемого атрибута OIDC, значение которого — подтверждённый ID учётной записи GitHub в виде строки с положительным десятичным числом. Настройте Access для его передачи в oidc_fields; никогда не используйте непроверенный атрибут, доступный для редактирования пользователем.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2Eissuer":{label:{"v1-8flf1b-o":`Издатель Cloudflare Access`},help:{"v1-gykv03-56":`Точный HTTPS-адрес источника доверенной команды Cloudflare Access, например https://example.cloudflareaccess.com, без завершающей косой черты. Утверждения от других издателей не предоставляют данные идентификации GitHub.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2EproviderId":{label:{"v1-1vne6sn-y":`Идентификатор провайдера OIDC в Cloudflare Access`},help:{"v1-kbyo5w-44":`Точный идентификатор провайдера идентификации Access для доверенной интеграции OIDC. Одного лишь отображаемого имени провайдера или совпадающего имени утверждения недостаточно для установления доверия.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove":{label:{"v1-19sx4ub-y":`Автоматическое одобрение устройств через доверенный прокси`},help:{"v1-uh32ha-6z":`Необязательная политика автоматического одобрения новых устройств операторов с браузерным и нативным интерфейсом, а также расширения прав для того же ключа после аутентификации через доверенный прокси. Предоставляемые права ограничены deviceAutoApprove.scopes и заголовком прокси x-openclaw-scopes, если он присутствует.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove%2Eenabled":{label:{"v1-1hdecc2-16":`Автоматическое одобрение устройств через доверенный прокси включено`},help:{"v1-1nntwls-78":`Автоматически одобряет новые устройства операторов с браузерным и нативным интерфейсом, а также расширение прав для того же ключа после того, как обратный прокси аутентифицирует разрешённого пользователя. По умолчанию: false. Включайте только в том случае, если проверка личности на границе прокси достаточно надёжна, чтобы заменить ручное сопряжение устройств.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove%2Escopes":{label:{"v1-erslbw-15":`Права доступа при автоматическом одобрении устройств через доверенный прокси`},help:{"v1-raeila-g3":`Максимальные права доступа, предоставляемые автоматически одобренным устройствам операторов. По умолчанию: operator.read, operator.write, operator.approvals и operator.questions. Запрашиваемые права ограничиваются этим списком; если права не указаны в запросе, предоставляются права из этого списка. Если значение не задано, при автоматическом одобрении также добавляется operator.questions для старых UI-клиентов; явно заданный список никогда не расширяется. Явное включение operator.admin позволяет каждому пользователю, прошедшему аутентификацию через прокси, автоматически получать полные права администратора; запросы без указания прав также автоматически получают полные права администратора. Это также приводит к регистрации критической проблемы при аудите безопасности и появлению предупреждения при запуске Gateway.`}},"gateway%2Ebind":{label:{"v1-1g0dmdr-h":`Режим привязки Gateway`},help:{"v1-1unqude-4y":`Профиль сетевой привязки: "auto", "lan", "loopback", "custom" или "tailnet" — определяет, какие интерфейсы доступны. Оставьте "loopback" для работы только локально; "auto" может открыть доступ через все интерфейсы.`}},"gateway%2EcliAgents":{label:{"v1-1noo169-a":`CLI-агенты`},help:{"v1-1qqo8m2-5a":`Обнаружение в Control UI внешних движков сеансов CLI, доступных через каталог сеансов Gateway. По умолчанию включено; отключите, чтобы запретить запуск этих движков из списка выбора модели для нового сеанса.`}},"gateway%2EcliAgents%2Eenabled":{label:{"v1-11gsfq0-i":`CLI-агенты включены`},help:{"v1-ufu7fx-8p":`При значении true показывает CLI-агентов из каталога в списке выбора модели для нового сеанса в Control UI (по умолчанию: true). Установите false, чтобы отключить CLI-агентов и создание нативных CLI-сеансов. Отображаются только каталоги, заявляющие о поддержке создания сеансов; список выбора скрыт, если Gateway не заявляет о поддержке каталога сеансов.`}},"gateway%2EcontrolUi":{label:{"v1-1cl7zto-a":`Control UI`},help:{"v1-bkw4g1-5i":`Настройки размещения Control UI, включая включение, пути и усиление защиты источников браузера и аутентификации. Сведите доступность интерфейса извне к минимуму и настройте надёжную аутентификацию перед развёртыванием с доступом из интернета.`}},"gateway%2EcontrolUi%2EallowedOrigins":{label:{"v1-11jcj2v-q":`Разрешённые источники Control UI`},help:{"v1-1stgitk-9i":`Разрешённые источники браузера для WebSocket-подключений Control UI/WebChat (только полные адреса источников, например https://control.example.com). Обязательны при развёртывании Control UI за пределами петлевого интерфейса, если явно не включён опасный резервный механизм на основе заголовка Host. Значение ["*"] разрешает любой источник браузера; его следует избегать за исключением строго контролируемого локального тестирования.`}},"gateway%2EcontrolUi%2EallowExternalEmbedUrls":{label:{"v1-1flu103-10":`Разрешить внешние URL для встраивания в Control UI`},help:{"v1-obwpfg-6s":`ОПАСНЫЙ переключатель, разрешающий размещённым встраиваемым элементам загружать абсолютные внешние URL http(s). Оставьте его выключенным, если только ваш Control UI не предназначен для встраивания доверенных сторонних страниц; размещённым документам /__openclaw__/canvas и /__openclaw__/a2ui он не нужен.`}},"gateway%2EcontrolUi%2EautomaticallyFetchFavicons":{label:{"v1-spcu6r-x":`Автоматически загружать значки сайтов для ссылок`},help:{"v1-bn9u34-ag":`Загружать значки сайтов для ссылок и превью для соцсетей для вкладок браузера через Gateway (по умолчанию включено). Карточки вкладок браузера загружают общедоступные метаданные страниц и указанные в них изображения без файлов cookie браузера и учётных данных сайтов. Для всех запросов применяются строгие проверки для защиты от SSRF и ограничения на обработку HTML и изображений. Установите false, чтобы отключить автоматическую загрузку как значков сайтов, так и превью страниц; это не влияет на снимки экрана браузера в реальном времени.`}},"gateway%2EcontrolUi%2EbasePath":{label:{"v1-qnzlec-k":`Базовый путь Control UI`},help:{"v1-1dx68ar-1w":`Необязательный префикс URL, по которому доступен Control UI (например, /openclaw).`}},"gateway%2EcontrolUi%2EcommunityInvite":{label:{"v1-1j7cpqc-v":`Приглашение в сообщество в Control UI`},help:{"v1-1rz3zsx-73":`Показывать приглашение в сообщество Discord в Control UI, предоставляемом этим Gateway (по умолчанию включено). Установите false, чтобы скрыть его во всех браузерах, использующих этот экземпляр интерфейса. Изменения применяются после обновления страницы в браузере или повторного подключения; при повторном включении сохраняется информация о закрытии приглашения в каждом браузере.`}},"gateway%2EcontrolUi%2EdangerouslyAllowHostHeaderOriginFallback":{label:{"v1-vvl359-19":`Разрешить небезопасное резервное определение источника по заголовку Host`},help:{"v1-1t1qi4c-7v":`ОПАСНЫЙ переключатель, включающий резервное определение источника по заголовку Host при проверках WebSocket для Control UI/WebChat. Этот режим поддерживается, если ваше развёртывание намеренно использует политику источников на основе заголовка Host; явное указание gateway.controlUi.allowedOrigins остаётся рекомендуемым вариантом с усиленной защитой по умолчанию.`}},"gateway%2EcontrolUi%2EembedSandbox":{label:{"v1-1hknvfl-t":`Режим песочницы для встроенного содержимого Control UI`},help:{"v1-d54l3a-7c":'Политика песочницы iframe для встроенного содержимого в размещённом Control UI. "strict" отключает скрипты, "scripts" разрешает интерактивное встроенное содержимое с сохранением изоляции источников (по умолчанию), а "trusted" добавляет `allow-same-origin` для документов того же сайта, которым намеренно требуются расширенные привилегии.'}},"gateway%2EcontrolUi%2Eenabled":{label:{"v1-1jokhv9-i":`Control UI включён`},help:{"v1-1hhyymc-4w":`При значении true включает предоставление Control UI шлюза через HTTP-процесс шлюза. Оставьте включённым для локального администрирования и отключите, если вместо него используется внешний интерфейс управления.`}},"gateway%2EcontrolUi%2Eenvironment":{label:{"v1-tmefut-m":`Окружение Control UI`},help:{"v1-paarso-4n":`Необязательное общедоступное обозначение окружения, отображаемое на полосе Control UI, аватаре агента, плашках меток, в заголовке вкладки браузера и значке сайта. Не задавайте его, чтобы сохранить внешний вид по умолчанию.`}},"gateway%2EcontrolUi%2Eenvironment%2Ecolor":{label:{"v1-vy6f72-s":`Цвет окружения в Control UI`},help:{"v1-mp6cta-2i":`Именованная цветовая шкала окружения: teal, amber, purple, coral, pink, blue, green, red или gray.`}},"gateway%2EcontrolUi%2Eenvironment%2Elabel":{label:{"v1-1yr90xz-s":`Метка окружения в Control UI`},help:{"v1-1njve3z-3z":`Метка окружения, отображаемая в Control UI и на вкладке браузера; пробельные символы по краям удаляются, а длина метки должна составлять от 1 до 24 символов.`}},"gateway%2EcontrolUi%2Eexperimental":{label:{"v1-10uccgr-w":`Экспериментальные функции Control UI`},help:{"v1-1qobi2m-3g":`Экспериментальные функции Control UI, включаемые по желанию. Эти возможности могут меняться от версии к версии и остаются отключёнными, пока их явно не включат.`}},"gateway%2EcontrolUi%2Eexperimental%2EcustomPlugins":{label:{"v1-1gaae1x-g":`Интерфейс пользовательских плагинов`},help:{"v1-108u6ts-9e":`Разрешить установленным пользователем плагинам выполнять нативный JavaScript в Control UI (по умолчанию: false). Представления встроенных плагинов остаются доступными. Пользовательский интерфейс сторонних плагинов использует права доступа текущего оператора к Gateway; включайте его только для доверенных плагинов. Изменения применяются без перезапуска Gateway. Перезагрузите открытые страницы Control UI, чтобы удалить ранее загруженный код плагинов.`}},"gateway%2EcontrolUi%2Egithub%2Etoken":{label:{"v1-1036yk1-10":`Учётные данные сервиса GitHub для Control UI`},help:{"v1-1p31phh-d6":`Учётные данные сервиса на основе SecretRef для обнаружения проектов в Control UI и предварительного просмотра GitHub при наведении без управляемой идентификации. Для предварительного просмотра при наведении предпочтительно используется настроенная идентификация GitHub выбранного агента; если она не переопределена, наследуется системная идентификация. Рекомендуется явная настройка, чтобы чётко определить владельца сервиса. Не задавайте это значение, чтобы сохранить резервное использование GH_TOKEN/GITHUB_TOKEN из общего окружения процесса Gateway. Если явно настроенные учётные данные недоступны, доступ блокируется.`}},"gateway%2EcontrolUi%2Eroot":{label:{"v1-t5p3aj-m":`Корневой каталог ресурсов Control UI`},help:{"v1-elck04-25":`Необязательный корневой каталог файловой системы для ресурсов Control UI (по умолчанию dist/control-ui).`}},"gateway%2EcontrolUi%2EsessionObserver":{label:{"v1-tjwi96-r":`Наблюдатель сеансов Control UI`},help:{"v1-1ahs80-8a":`Создаёт сводки о состоянии сеансов в реальном времени для подписанных клиентов Control UI с помощью вспомогательной модели каждого агента (по умолчанию включено). Установите false, чтобы отключить вызовы модели наблюдателя во всём Gateway; установка agents.defaults.utilityModel в пустую строку отключает наблюдение с помощью вспомогательной модели для агентов, которые не переопределяют этот параметр.`}},"gateway%2EcustomBindHost":{label:{"v1-upmb47-o":`Пользовательский адрес привязки Gateway`},help:{"v1-lwjcyo-4d":`IPv4-адрес для пользовательской привязки. При использовании конкретных IPv4-адресов также требуется тот же порт Gateway на 127.0.0.1; избегайте 0.0.0.0, если не требуется доступ через все интерфейсы.`}},"gateway%2Ehttp":{label:{"v1-1dyy3ff-g":`HTTP API Gateway`},help:{"v1-ebtex7-4j":`Настройки HTTP API Gateway, объединяющие переключатели конечных точек и параметры доступности API на транспортном уровне. Чтобы уменьшить поверхность атаки, оставляйте включёнными только необходимые конечные точки.`}},"gateway%2Ehttp%2Eendpoints":{label:{"v1-1hyy5m9-m":`Конечные точки HTTP Gateway`},help:{"v1-1a0r104-55":`Переключатели HTTP-эндпоинтов в API Gateway для маршрутов совместимости и дополнительных интеграций. Включайте эндпоинты осознанно и отслеживайте характер обращений после внедрения.`}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eenabled":{label:{"v1-1lv2qyt-w":`Эндпоинт OpenAI Chat Completions`},help:{"v1-1271mpb-2b":"Включить совместимый с OpenAI эндпоинт `POST /v1/chat/completions` (по умолчанию: false)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages":{label:{"v1-9q1ao7-10":`Ограничения изображений OpenAI Chat Completions`},help:{"v1-xgscw1-20":"Настройки загрузки и проверки изображений для совместимых с OpenAI частей `image_url`."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EallowedMimes":{label:{"v1-1acpvsy-18":`Список разрешённых MIME-типов изображений OpenAI Chat Completions`},help:{"v1-1guijf3-1t":"Разрешённые MIME-типы для частей `image_url` (список без учёта регистра)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EallowUrl":{label:{"v1-ivns2a-14":`Разрешить URL изображений в OpenAI Chat Completions`},help:{"v1-55cb3n-47":"Разрешить загрузку по URL на стороне сервера для частей `image_url` (по умолчанию: false; URI данных по-прежнему поддерживаются). Установите значение `false`, чтобы полностью отключить загрузку по URL."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EmaxBytes":{label:{"v1-1aakvdk-13":`Максимальный размер изображений OpenAI Chat Completions в байтах`},help:{"v1-d920yx-1s":"Максимальный размер каждого загруженного или декодированного изображения `image_url` в байтах (по умолчанию: 10 МБ)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EmaxRedirects":{label:{"v1-gi6vbe-17":`Максимум перенаправлений для изображений OpenAI Chat Completions`},help:{"v1-1enujsk-1z":"Максимальное число HTTP-перенаправлений при загрузке по URL из `image_url` (по умолчанию: 3)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EtimeoutMs":{label:{"v1-rg0i4t-16":`Тайм-аут загрузки изображений OpenAI Chat Completions (мс)`},help:{"v1-89w2b9-1x":"Тайм-аут в миллисекундах для загрузки по URL из `image_url` (по умолчанию: 10000)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EurlAllowlist":{label:{"v1-1sb0si1-17":`Список разрешённых URL изображений OpenAI Chat Completions`},help:{"v1-n4hlt1-4r":"Необязательный список разрешённых имён хостов для загрузки по URL из `image_url`; поддерживаются точные имена хостов и шаблоны вида `*.example.com`. Если список пуст или не задан, ограничения по именам хостов не применяются."}},"gateway%2Ehttp%2EsecurityHeaders":{label:{"v1-5g4go1-t":`Заголовки безопасности HTTP для Gateway`},help:{"v1-n8z1hb-44":`Необязательные заголовки безопасности HTTP-ответов, добавляемые самим процессом Gateway. Если TLS-соединение завершается на обратном прокси, рекомендуется задавать эти заголовки там.`}},"gateway%2Ehttp%2EsecurityHeaders%2EstrictTransportSecurity":{label:{"v1-16ryvji-w":`Заголовок Strict-Transport-Security`},help:{"v1-1buwhc3-3v":`Значение заголовка ответа Strict-Transport-Security. Задавайте только для HTTPS-источников, которые вы полностью контролируете; используйте false для явного отключения.`}},"gateway%2Emode":{label:{"v1-1f0xa2s-c":`Режим Gateway`},help:{"v1-nfjirv-5m":`Режим работы Gateway: "local" запускает каналы и среду выполнения агента на этом хосте, а "remote" подключается через удалённый транспорт. Оставьте "local", если вы не планируете использовать распределённую топологию с удалённым Gateway.`}},"gateway%2Enodes%2EallowSkills":{label:{"v1-bnyeyy-r":`Skills узлов Gateway включены`},help:{"v1-1xwu6at-3g":`Принимать навыки, опубликованные сопряжёнными узлами, пока они подключены (по умолчанию: true). Установите false, чтобы игнорировать навыки, опубликованные узлами.`}},"gateway%2Enodes%2Ebrowser%2Emode":{label:{"v1-no31im-p":`Режим браузера узла Gateway`},help:{"v1-oeu1nc-69":`Маршрутизация браузера через узлы ("auto" = предпочитать браузер хоста, использовать единственный подключённый браузерный узел, если локальная возможность недоступна; "manual" = требовать явного выбора узла или настроенной привязки; "off" = отключить маршрутизацию через узлы).`}},"gateway%2Enodes%2Ebrowser%2Enode":{label:{"v1-1fqwdc0-o":`Закрепление браузера за узлом Gateway`},help:{"v1-1cykty2-1p":`Закрепить маршрутизацию браузера за конкретным узлом по идентификатору или имени (необязательно).`}},"gateway%2Enodes%2Ecommands%2Eallow":{label:{"v1-9snt7h-13":`Список разрешений узлов Gateway (дополнительные команды)`},help:{"v1-6l4otb-5m":"Дополнительные команды node.invoke, разрешённые помимо стандартных разрешений Gateway (массив строк с командами). Разрешение опасных команд здесь переопределяет ограничения безопасности и отмечается при проверке `openclaw security audit`."}},"gateway%2Enodes%2Ecommands%2Edeny":{label:{"v1-vauwib-l":`Список запретов узлов Gateway`},help:{"v1-u7c8wx-53":"Имена команд узлов, которые следует блокировать, даже если они заявлены узлом или включены в стандартный список разрешений (только точное совпадение имени команды, например `system.run`; текст командной оболочки внутри этой команды не проверяется)."}},"gateway%2Enodes%2Epairing":{label:{"v1-1skp3xv-k":`Сопряжение узлов Gateway`},help:{"v1-gldsi2-4s":`Настройки политики сопряжения узлов. Автоматическое одобрение с проверкой по SSH включено по умолчанию; автоматическое одобрение по CIDR отключено, пока явно не настроены списки разрешённых доверенных CIDR/IP.`}},"gateway%2Enodes%2Epairing%2EautoApproveCidrs":{label:{"v1-11ih0u1-13":`CIDR для автоматического одобрения сопряжения узлов Gateway`},help:{"v1-1m6jsxj-6x":`Явно задаваемый список разрешённых CIDR/IP для автоматического одобрения первого сопряжения устройств с ролью узла без запрошенных областей доступа. Если список не задан, функция отключена. Сопряжение оператора, браузера, Control UI, а также любое сопряжение с изменением роли, области доступа, метаданных или открытого ключа по-прежнему требует ручного одобрения.`}},"gateway%2Enodes%2Epairing%2EautoApproveLocal":{label:{"v1-178lial-13":`Автоматическое одобрение локального сопряжения узлов Gateway`},help:{"v1-glzm36-41":`Одобрять доверенное локальное сопряжение и расширение доступа без уведомлений (по умолчанию: true); установите false, чтобы вместо этого явно одобрять каждое устройство.`}},"gateway%2Enodes%2Epairing%2EsshVerify":{label:{"v1-muqemo-11":`Проверка сопряжения узлов Gateway по SSH`},help:{"v1-1e4da92-ct":"Автоматическое одобрение первого сопряжения устройств с ролью узла после проверки по SSH (по умолчанию: включено). Gateway подключается по SSH к хосту, запросившему сопряжение (BatchMode, строгая проверка ключей хоста), и одобряет запрос, только если вывод удалённой команды `openclaw node identity` совпадает с ключом устройства, ожидающего одобрения. Установите false, чтобы отключить проверку по SSH (независимо от autoApproveCidrs, который остаётся активным); для исключительно ручного сопряжения также удалите значение autoApproveCidrs. Передайте объект, чтобы переопределить user/identity/timeoutMs/cidrs."}},"gateway%2Enodes%2EpluginTools":{label:{"v1-1cgl9u5-p":`Инструменты плагинов узлов Gateway`},help:{"v1-1c24iq3-28":`Определяет, могут ли сопряжённые узлы публиковать описания инструментов плагинов, доступные агенту.`}},"gateway%2Enodes%2EpluginTools%2Eenabled":{label:{"v1-1osj3kc-x":`Инструменты плагинов узлов Gateway включены`},help:{"v1-14lgfu6-47":`Принимать дескрипторы инструментов плагинов, доступных агенту, которые публикуют сопряжённые узлы (по умолчанию: true). Установите false, чтобы игнорировать и удалить все инструменты плагинов, опубликованные узлами.`}},"gateway%2Eport":{label:{"v1-sqxdfo-c":`Порт Gateway`},help:{"v1-for8t5-54":`TCP-порт, на котором Gateway принимает входящие подключения к API, Control UI и маршрутам каналов. Используйте выделенный порт и избегайте конфликтов с обратными прокси или локальными сервисами разработки.`}},"gateway%2Eportals":{label:{"v1-zf0m5q-f":`Порталы Gateway`},help:{"v1-1v2lkw9-1c":`Настройки публикации порталов и частного входящего трафика.`}},"gateway%2Eportals%2Eingress":{label:{"v1-1cafvtp-m":`Частный входящий трафик порталов`},help:{"v1-20w4gq-69":`Необязательный частный обратный HTTPS-прокси с поддержкой wildcard, управляемый оператором. Перенаправляйте исходный Host, пути и запросы переключения на WebSocket на выделенный слушатель loopback. Аутентификация портала с помощью токена Bearer остаётся обязательной. Требуется перезапуск Gateway.`}},"gateway%2Eportals%2Eingress%2Edomain":{label:{"v1-iitxfx-m":`Wildcard-домен порталов`},help:{"v1-1ipbfad-53":`DNS-домен без дополнительных компонентов для случайных поддоменов порталов (например, previews.example.net). Настройте wildcard DNS и HTTPS для частного доступа; не используйте общее пространство имён хостов с Gateway или Control UI.`}},"gateway%2Eportals%2Eingress%2Eport":{label:{"v1-1o3yr58-s":`Порт loopback для входящего трафика порталов`},help:{"v1-1mb98cv-4g":`Выделенный HTTP-порт на интерфейсе обратной петли, принимающий запросы от частного HTTPS-прокси с поддержкой поддоменов по маске. Должен отличаться от порта Gateway. Это порт бэкенда, а не публичный порт HTTPS.`}},"gateway%2EpublicOrigin":{label:{"v1-b3jhw4-l":`Публичный базовый адрес Gateway`},help:{"v1-17vekvx-87":`Доступный извне базовый HTTPS-адрес Gateway. HTTP разрешён только для localhost, 127.0.0.1 или [::1]. MCP OAuth для каждого инициатора запроса использует его для формирования URL обратного вызова по пути /oauth/mcp/callback; ссылки на сеансы каналов и ссылки для просмотра, создаваемые плагинами, используют его для доступа к Control UI и маршрутам Gateway.`}},"gateway%2Epush":{label:{"v1-1o9y10t-l":`Доставка push-уведомлений Gateway`},help:{"v1-h23oz7-5s":`Настройки доставки push-уведомлений, которые Gateway использует для пробуждения сопряжённых устройств или отправки им уведомлений. Здесь можно настроить APNs через ретранслятор для официальных сборок iOS; прямая аутентификация APNs для локальных и ручных сборок по-прежнему настраивается через переменные окружения.`}},"gateway%2Epush%2Eapns":{label:{"v1-gd06d3-l":`Доставка через APNs в Gateway`},help:{"v1-4bbafr-4e":`Настройки доставки через APNs для устройств iOS, сопряжённых с этим Gateway. Используйте настройки ретранслятора для официальных сборок из App Store, которые регистрируются через внешний ретранслятор push-уведомлений.`}},"gateway%2Epush%2Eapns%2Erelay":{label:{"v1-4sjqkk-i":`Ретранслятор APNs Gateway`},help:{"v1-7glbel-6x":`Настройки внешнего ретранслятора для отправки через APNs с использованием ретранслятора. По умолчанию Gateway использует размещённый ретранслятор OpenClaw или этот пользовательский ретранслятор для push.test, сигналов пробуждения и пробуждения для повторного подключения после того, как сопряжённая официальная сборка iOS опубликует регистрацию с использованием ретранслятора.`}},"gateway%2Epush%2Eapns%2Erelay%2EbaseUrl":{label:{"v1-m977u4-r":`Базовый URL ретранслятора APNs для Gateway`},help:{"v1-1o8mgnq-69":`Необязательный пользовательский базовый HTTPS URL внешней службы ретрансляции APNs, используемой официальными сборками iOS из App Store. Он должен совпадать с URL ретранслятора, встроенным в сборку iOS, чтобы регистрация и отправка направлялись в один и тот же развёрнутый экземпляр службы.`}},"gateway%2Epush%2Eapns%2Erelay%2EtimeoutMs":{label:{"v1-1s3crai-v":`Тайм-аут ретранслятора APNs для Gateway (мс)`},help:{"v1-a0jkb1-4z":`Тайм-аут в миллисекундах для запросов отправки от Gateway к ретранслятору APNs (по умолчанию: 10000). Увеличьте его для медленных ретрансляторов или сетей либо уменьшите, чтобы быстрее завершать неудачные попытки пробуждения.`}},"gateway%2Ereload":{label:{"v1-vobbcc-d":`Перезагрузка конфигурации`},help:{"v1-d02mvq-4w":`Политика перезагрузки конфигурации на лету: определяет, как применяются изменения и когда выполняется полный перезапуск. Для наиболее безопасного применения обновлений сохраняйте гибридный режим, если не отлаживаете внутренние механизмы перезагрузки.`}},"gateway%2Ereload%2Emode":{label:{"v1-1qw6ix3-i":`Режим перезагрузки конфигурации`},help:{"v1-1q1etcf-3m":`Определяет, как применяются изменения конфигурации: "off" игнорирует изменения на лету, а "hybrid" применяет изменения, безопасные без перезапуска, и при необходимости выполняет перезапуск.`}},"gateway%2Eremote":{label:{"v1-aaj9cl-e":`Удалённый Gateway`},help:{"v1-6xv7gd-5a":`Настройки подключения к удалённому Gateway напрямую или через SSH, когда этот экземпляр проксирует запросы на другой узел выполнения. Используйте удалённый режим, только если работа на разных узлах настроена намеренно.`}},"gateway%2Eremote%2EedgeAuth":{label:{"v1-5c8ezy-w":`Заголовки аутентификации на периметре удалённого Gateway`},help:{"v1-jg9p7d-5o":`HTTP-заголовки со значениями из хранилища секретов, передаваемые прокси с проверкой удостоверений перед настроенным удалённым Gateway. Заголовки отправляются по WSS только на источник, точно соответствующий gateway.remote.url, и никогда не передаются при перенаправлениях.`}},"gateway%2Eremote%2Epassword":{label:{"v1-xfnwjq-n":`Пароль удалённого Gateway`},help:{"v1-16jc0yx-7y":`Общий секрет, отправляемый в поле password для аутентификации этого клиента на удалённом Gateway. Параметр gateway.auth.mode сервера определяет используемый секрет; принимается как поле token, так и поле password клиента. Управляйте этим секретом вне конфигурации и не сохраняйте его открытым текстом в конфигурации, добавляемой в репозиторий.`}},"gateway%2Eremote%2EsshHostKeyPolicy":{label:{"v1-3hl9l5-y":`Политика проверки ключа SSH-хоста удалённого Gateway`},help:{"v1-7qoxtb-49":`Политика проверки ключа SSH-хоста в macOS. "strict" требует уже доверенного ключа хоста; "openssh" явно передаёт управление действующей конфигурации OpenSSH.`}},"gateway%2Eremote%2EsshIdentity":{label:{"v1-1rgof8r-r":`Ключ идентификации SSH удалённого Gateway`},help:{"v1-hz2hsm-1f":`Необязательный путь к файлу ключа идентификации SSH (передаётся в ssh -i).`}},"gateway%2Eremote%2EsshTarget":{label:{"v1-nvjmc8-p":`Адрес SSH удалённого Gateway`},help:{"v1-85w39w-2t":`Удалённый Gateway через SSH (туннелирует порт Gateway на localhost). Формат: user@host или user@host:port.`}},"gateway%2Eremote%2EtlsFingerprint":{label:{"v1-akxcgg-u":`Отпечаток TLS удалённого Gateway`},help:{"v1-1ri16lk-23":`Ожидаемый отпечаток TLS sha256 удалённого Gateway (закрепите его для защиты от MITM-атак).`}},"gateway%2Eremote%2Etoken":{label:{"v1-kw3r38-k":`Токен удалённого Gateway`},help:{"v1-1pb9q8w-7v":`Общий секрет, передаваемый в поле token для аутентификации этого клиента на удалённом Gateway. Параметр gateway.auth.mode на сервере определяет, какой из настроенных секретов используется; на стороне клиента принимается как поле token, так и поле password. Храните значение с помощью подстановки секрета или переменной окружения и обновляйте его при изменении настроек аутентификации удалённого Gateway.`}},"gateway%2Eremote%2Etransport":{label:{"v1-hn4r18-o":`Транспорт удалённого Gateway`},help:{"v1-1acfs7m-54":`Транспорт удалённого подключения: "direct" использует подключение по настроенному URL, а "ssh" — туннель через SSH. Используйте SSH, если нужен зашифрованный туннель без открытия удалённых портов для внешнего доступа.`}},"gateway%2Eremote%2Eurl":{label:{"v1-1i53o94-i":`URL удалённого Gateway`},help:{"v1-va7exe-1b":`URL WebSocket удалённого Gateway (ws:// или wss://).`}},"gateway%2Eroles":{label:{"v1-189p1ru-m":`Роли операторов Gateway`},help:{"v1-b59sc5-6w":`Необязательные роли операторов, привязанные к профилям, для командных Gateway. Каждая именованная роль управляет доступом к сеансам других пользователей, изоляцией песочницы, агентами сеансов и запусков, а также предоставленными полномочиями оператора. Если этот раздел отсутствует, существующее поведение операторов сохраняется.`}},"gateway%2Eroles%2Edefault":{label:{"v1-1ykt1qe-l":`Роль оператора по умолчанию`},help:{"v1-1v8add8-4u":`Обязательная роль, назначаемая аутентифицированным профилям без допустимого явного назначения, если настроены роли операторов. Её имя должно совпадать с именем одного из настроенных определений ролей.`}},"gateway%2Eroles%2Edefinitions":{label:{"v1-sw4idp-p":`Определения ролей операторов`},help:{"v1-uv91an-53":`Непустой набор определений ролей с именами, заданными администратором. Они объединяют политики совместного доступа к сеансам, изоляции песочницы, доступа к агентам и полномочий оператора с фиксированным набором допустимых значений, применяемые к аутентифицированным профилям пользователей.`}},"gateway%2Eroles%2Edefinitions%2E*":{label:{"v1-irzm3w-o":`Определение роли оператора`},help:{"v1-p8tfws-6q":`Одна именованная роль оператора. В каждом определении необходимо явно указать политику совместного доступа к сеансам, разрешённых агентов для сеансов и запусков, а также верхнюю границу полномочий оператора. Также можно задать обязательную изоляцию в песочнице для новых сеансов и политику доступа плагина.`}},"gateway%2Eroles%2Edefinitions%2E*%2EaccessPolicyPlugin":{label:{"v1-yhsyhu-y":`Плагин политики доступа для роли оператора`},help:{"v1-1gq4q08-9n":`Необязательный точный идентификатор плагина, политика доступа которого к Gateway должна разрешать доступ для этой роли. Доступ запрещён, если плагин отсутствует, отключён, не загружается или не предоставляет действующего разрешения. Идентификаторы недоступных плагинов остаются допустимыми в конфигурации, чтобы сотрудники с независимыми ролями и владелец Gateway могли восстановить доступ. Если это поле не задано, зависимость от плагина не добавляется.`}},"gateway%2Eroles%2Edefinitions%2E*%2Eagents":{label:{"v1-1u0v1av-s":`Разрешённые агенты для роли оператора`},help:{"v1-fvun18-4v":`Агенты, доступные при создании сеансов или выполнении запусков с этой ролью: укажите "*", чтобы разрешить всех агентов, перечислите идентификаторы агентов, чтобы разрешить только их, или используйте пустой список, чтобы запретить оба действия.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esandbox":{label:{"v1-1h433k8-v":`Изоляция в песочнице для роли оператора`},help:{"v1-sknx21-66":`Изоляция выполнения для вновь создаваемых сеансов: "inherit" (по умолчанию) использует политику агента; "required" делает песочницу обязательной на постоянной основе, даже если режим песочницы у агента отключён, и блокирует выполнение при недоступности бэкенда.`}},"gateway%2Eroles%2Edefinitions%2E*%2Escopes":{label:{"v1-1qejq9c-r":`Предельный набор прав роли оператора`},help:{"v1-1selr2i-4s":`Закрытый список прав оператора, определяющий максимальные полномочия подключения для этой роли. Запрашиваемые права, права, полученные при сопряжении, предоставленные на основе удостоверения личности и полученные при повышении полномочий, ограничиваются пересечением с этим списком.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esessions":{label:{"v1-1t2w5en-s":`Доступ роли оператора к сеансам`},help:{"v1-hsoiop-45":`Разрешения на совместный доступ, предоставляемые этой роли для сеансов, созданных другими аутентифицированными пользователями; собственные сеансы пользователя остаются доступны ему как владельцу.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esessions%2Eothers":{label:{"v1-lcjhtz-12":`Доступ роли оператора к чужим сеансам`},help:{"v1-vf8umx-5r":`Доступ к сеансам других пользователей: "none" скрывает их, "view" разрешает чтение, "suggest" разрешает отправку предложений, а "write" — участие. Явное включение в состав участников сеанса может предоставить дополнительный доступ.`}},"gateway%2Etailscale":{label:{"v1-1gi7nvp-h":`Tailscale для Gateway`},help:{"v1-6ar9o-4x":`Настройки интеграции с Tailscale для предоставления доступа через Serve/Funnel и управления жизненным циклом при запуске и завершении работы Gateway. Оставьте выключенной, если ваше развёртывание не предполагает входящий доступ через Tailscale.`}},"gateway%2Etailscale%2Emode":{label:{"v1-n7wv5k-m":`Режим Tailscale для Gateway`},help:{"v1-6l2099-5a":`Режим публикации Tailscale: "off", "serve" или "funnel" для частного или публичного доступа. Используйте "serve" для доступа только из tailnet, а "funnel" — только если требуется доступ из публичного интернета.`}},"gateway%2Etailscale%2EpreserveFunnel":{label:{"v1-h174rt-1d":`Защита при миграции внешнего Funnel в Tailscale для Gateway`},help:{"v1-1mntkor-7q":`Устаревший механизм защиты при миграции для mode='serve'. Если внешний Funnel по-прежнему направляет трафик на обычный прослушивающий интерфейс Gateway, OpenClaw оставляет доступ без изменений и предупреждает, что до настройки аутентификации по паролю и перехода на режим 'funnel' будут доступны только вебхуки с аутентификацией через плагины.`}},"gateway%2Eterminal":{label:{"v1-11obn6j-h":`Терминал оператора`},help:{"v1-18f5rgm-8b":`Терминал оператора для Control UI и мобильных клиентов: оболочка на базе PTY на хосте Gateway, доступная только сеансам оператора с административными правами. Она запускается в рабочей области целевого агента. Для полностью изолированных агентов (sandbox.mode 'all') доступ запрещён, чтобы не предоставлять оболочку хоста без ограничений.`}},"gateway%2Eterminal%2EdetachedSessionTimeoutSeconds":{label:{"v1-g247t4-16":`Время ожидания отключённого сеанса терминала оператора`},help:{"v1-k6qbgr-9e":`Время в секундах, в течение которого сеанс терминала сохраняется после разрыва соединения (перехода ноутбука в спящий режим, перезагрузки страницы). В этот период можно повторно подключиться через terminal.attach и просмотреть недавний вывод. Установите 0, чтобы завершать сеансы сразу при разрыве соединения. По умолчанию: 300 (5 минут). Отключённые сеансы продолжают выполнять команды, поэтому на общих или доступных извне хостах рекомендуется уменьшить это значение.`}},"gateway%2Eterminal%2Eenabled":{label:{"v1-6xiiwa-p":`Терминал оператора включён`},help:{"v1-1nez06v-7p":`Включает терминал оператора для клиентов с административными полномочиями (по умолчанию: true). Это предоставляет доступ через браузер или мобильное устройство к командной оболочке с окружением процесса Gateway; задайте false в развёртываниях, где операторам с административными полномочиями не следует предоставлять доступ к командной оболочке хоста. Изменения применяются без перезапуска Gateway.`}},"gateway%2Eterminal%2Eshell":{label:{"v1-1qte0r1-n":`Оболочка терминала оператора`},help:{"v1-19mfe6t-5i":`Исполняемый файл оболочки, которую запускает терминал оператора. Оставьте параметр незаданным, чтобы использовать оболочку входа хоста ($SHELL в Unix, %ComSpec% в Windows), или явно укажите интерпретатор для единообразного окружения оператора.`}},"gateway%2Etls":{label:{"v1-103eqog-b":`TLS для Gateway`},help:{"v1-1dx77dq-4z":`Настройки сертификата и ключа TLS для завершения HTTPS-соединений непосредственно в процессе Gateway. В рабочей среде используйте явно заданные сертификаты и не допускайте передачи данных в открытом виде в недоверенных сетях.`}},"gateway%2Etls%2EautoGenerate":{label:{"v1-17g0gmx-u":`Автоматическое создание сертификата TLS для Gateway`},help:{"v1-1ld6uiu-4w":`Автоматически создаёт локальную пару сертификата и ключа TLS, если файлы не заданы явно. Используйте только локально или в среде разработки; для рабочего трафика замените их полноценными сертификатами.`}},"gateway%2Etls%2EcaPath":{label:{"v1-h9qtpb-j":`Путь к набору сертификатов CA для TLS в Gateway`},help:{"v1-andqlu-52":`Необязательный путь к набору сертификатов CA для проверки клиентов или выполнения особых требований к цепочке доверия на внешнем интерфейсе Gateway. Используйте, если в развёртывании применяется частная PKI или нестандартные цепочки сертификатов.`}},"gateway%2Etls%2EcertPath":{label:{"v1-160lhdi-s":`Путь к сертификату TLS для Gateway`},help:{"v1-1wznaof-4q":`Путь в файловой системе к файлу сертификата TLS, который использует Gateway при включённом TLS. Используйте управляемые пути к сертификатам и настройте автоматическое продление с учётом этого расположения.`}},"gateway%2Etls%2Eenabled":{label:{"v1-1hdsowh-j":`TLS в Gateway включён`},help:{"v1-ykhwp0-4o":`Включает терминацию TLS на прослушивающем интерфейсе Gateway, чтобы клиенты подключались напрямую по HTTPS/WSS. Оставляйте включённым при прямом доступе из интернета или на любой границе с недоверенной сетью.`}},"gateway%2Etls%2EkeyPath":{label:{"v1-1a645em-k":`Путь к ключу TLS для Gateway`},help:{"v1-15knri0-4i":`Путь в файловой системе к файлу закрытого ключа TLS, который использует Gateway при включённом TLS. Ограничьте права доступа к этому файлу ключа и регулярно заменяйте ключ согласно вашей политике безопасности.`}},"gateway%2Etools":{label:{"v1-1b7s1vg-s":`Политика доступа к инструментам в Gateway`},help:{"v1-1ffol26-5a":`Политика разрешения и запрета доступа к инструментам на уровне Gateway, которая может ограничивать доступность инструментов во время выполнения независимо от профилей агентов и инструментов. Используйте для общих экстренных ограничений и усиления защиты в рабочей среде.`}},"gateway%2Etools%2Eallow":{label:{"v1-tfn15c-m":`Список разрешённых инструментов в Gateway`},help:{"v1-163khb1-4y":`Явный список разрешённых инструментов на уровне Gateway для случаев, когда во время выполнения должен быть доступен только ограниченный набор инструментов. Используйте в средах со строгими ограничениями, где набор инструментов необходимо жёстко контролировать.`}},"gateway%2Etools%2Edeny":{label:{"v1-1a8nr3t-l":`Список запрещённых инструментов в Gateway`},help:{"v1-1lhssnf-4o":`Явный список запрещённых инструментов на уровне Gateway для блокировки потенциально опасных инструментов, даже если политики нижних уровней разрешают их. Используйте правила запрета для экстренного реагирования и усиления многоуровневой защиты.`}},"gateway%2EtrustedProxies":{label:{"v1-8g5i45-r":`CIDR доверенных прокси Gateway`},help:{"v1-n5zcvf-4f":`Список разрешённых CIDR/IP вышестоящих прокси, которым разрешено передавать заголовки с данными о личности клиента. Ограничьте этот список, чтобы недоверенные промежуточные узлы не могли выдавать себя за пользователей.`}},hooks:{label:{"v1-j9ywl7-5":`Хуки`},help:{"v1-1mzh0ry-5v":`Интерфейс автоматизации через входящие вебхуки для преобразования внешних событий в пробуждение или действия агента в OpenClaw. Прежде чем открывать доступ за пределами доверенных сетей, настройте строгие ограничения для токенов, сеансов и агентов.`}},"hooks%2EallowedAgentIds":{label:{"v1-1dan5ok-n":`Разрешённые ID агентов для хуков`},help:{"v1-hree88-7c":`Список разрешённых итоговых ID агентов, на которые могут быть направлены запросы хуков и настроенные сопоставления, включая маршрутизацию к агенту по умолчанию, когда agentId не указан. Используйте его, чтобы направлять события автоматизации только выделенным служебным агентам и ограничить масштаб последствий при утечке токена хука.`}},"hooks%2EallowedSessionKeyPrefixes":{label:{"v1-4rmaac-y":`Разрешённые префиксы ключей сеансов для хуков`},help:{"v1-b346oh-4r":`Список разрешённых префиксов ключей сеансов для входящих запросов хуков, когда разрешено передавать ключи со стороны вызывающего. Используйте узко заданные префиксы, чтобы предотвратить внедрение произвольных ключей сеансов.`}},"hooks%2EallowRequestSessionKey":{label:{"v1-u7mvac-v":`Разрешить ключ сеанса в запросах хуков`},help:{"v1-11n9ps-52":`При значении true разрешает вызывающей стороне передавать ключ сеанса в запросах хуков и тем самым управлять маршрутизацией. Оставьте false, если доверенным интеграторам явно не требуется особая привязка запросов к сеансам.`}},"hooks%2EdefaultSessionKey":{label:{"v1-bn0nb9-p":`Ключ сеанса по умолчанию для хуков`},help:{"v1-bzdgkn-57":`Резервный ключ сеанса для доставки через хуки, если запрос не передаёт его через разрешённые каналы. Используйте постоянный ключ с ограниченной областью действия, чтобы не смешивать несвязанные диалоги автоматизации.`}},"hooks%2Eenabled":{label:{"v1-1gty8ga-d":`Хуки включены`},help:{"v1-1mixmjf-4n":`Включает конечную точку хуков и конвейер выполнения сопоставлений для входящих вебхук-запросов. Оставьте выключенным, если вы не направляете внешние события в Gateway.`}},"hooks%2Egmail":{label:{"v1-o8tl94-a":`Хук Gmail`},help:{"v1-4cibmt-4r":`Настройки push-интеграции Gmail для уведомлений Pub/Sub и необязательного локального приёма обратных вызовов. По возможности используйте эту интеграцию только с выделенными аккаунтами Gmail для автоматизации.`}},"hooks%2Egmail%2Eaccount":{label:{"v1-11iw2zb-i":`Аккаунт хука Gmail`},help:{"v1-12l1h96-4v":`Идентификатор аккаунта Google для операций отслеживания и подписки Gmail в этой интеграции хуков. Используйте выделенный почтовый аккаунт для автоматизации, чтобы изолировать разрешения на выполнение операций.`}},"hooks%2Egmail%2EallowUnsafeExternalContent":{label:{"v1-6617w5-14":`Разрешить небезопасное внешнее содержимое в хуке Gmail`},help:{"v1-1w3gdvs-55":`При включении допускает к обработке внешнее содержимое Gmail с менее строгой очисткой. Для большей безопасности оставьте выключенным и включайте только для доверенных почтовых потоков с контролируемыми преобразованиями.`}},"hooks%2Egmail%2EhookUrl":{label:{"v1-1xypore-n":`URL обратного вызова хука Gmail`},help:{"v1-19fhn6q-4z":`Общедоступный URL обратного вызова, к которому Gmail или посредники обращаются для доставки уведомлений в этот конвейер хуков. Защитите этот URL проверкой токена и ограничьте сетевой доступ к нему.`}},"hooks%2Egmail%2EincludeBody":{label:{"v1-x6h6eo-n":`Включать тело письма в хук Gmail`},help:{"v1-14cf1c3-52":`Если задано true, загружать и включать содержимое писем для последующего сопоставления данных и обработки агентом. Оставьте false, если текст письма не нужен, поскольку это увеличивает объём и конфиденциальность передаваемых данных.`}},"hooks%2Egmail%2Elabel":{label:{"v1-75v7g6-g":`Ярлык хука Gmail`},help:{"v1-9zpdg8-4g":`Необязательный фильтр по ярлыку Gmail, ограничивающий набор писем, вызывающих события хука. Используйте узкие фильтры, чтобы не перегружать автоматизацию посторонними входящими письмами.`}},"hooks%2Egmail%2EmaxBytes":{label:{"v1-nk9y9t-p":`Максимальный размер содержимого письма для хука Gmail (байты)`},help:{"v1-2aaxx1-4b":`Максимальный объём данных Gmail в байтах, обрабатываемый за одно событие при включённом includeBody. Устанавливайте умеренные ограничения, чтобы снизить затраты и риски обработки слишком больших сообщений.`}},"hooks%2Egmail%2Emodel":{label:{"v1-15jx1vj-p":`Переопределение модели для хука Gmail`},help:{"v1-1var65t-59":`Необязательное переопределение модели для запусков, инициированных Gmail, когда автоматизации почтового ящика требуется особое поведение модели. Оставьте незаданным, чтобы наследовать настройки агента по умолчанию, если почтовые задачи не требуют специализации.`}},"hooks%2Egmail%2EpushToken":{label:{"v1-1u1u1rl-l":`Токен push-уведомлений хука Gmail`},help:{"v1-h1vx01-4o":`Общий секретный токен, обязательный для обратных вызовов хука push-уведомлений Gmail перед обработкой уведомлений. Используйте подстановку переменных окружения и регулярно меняйте токен, если конечные точки обратного вызова доступны извне.`}},"hooks%2Egmail%2ErenewEveryMinutes":{label:{"v1-bcw0nt-v":`Интервал продления хука Gmail (мин)`},help:{"v1-pr1z9-49":`Периодичность продления подписок на отслеживание Gmail в минутах, предотвращающая истечение их срока действия. Задайте интервал короче срока действия, установленного провайдером, и отслеживайте ошибки продления в журналах.`}},"hooks%2Egmail%2Eserve":{label:{"v1-djm9vi-n":`Локальный сервер хука Gmail`},help:{"v1-hom4wq-54":`Блок настроек локального сервера обратных вызовов для прямого получения уведомлений Gmail без отдельного уровня обработки входящего трафика. Включайте только в том случае, если этот процесс должен сам принимать и обрабатывать трафик вебхуков.`}},"hooks%2Egmail%2Eserve%2Ebind":{label:{"v1-1f9dlu6-u":`Адрес привязки сервера хуков Gmail`},help:{"v1-55bieu-4d":`Адрес привязки локального HTTP-сервера обратных вызовов Gmail при прямом обслуживании хуков. Используйте только адрес loopback, если внешний доступ не требуется намеренно.`}},"hooks%2Egmail%2Eserve%2Epath":{label:{"v1-1fmz9ci-m":`Путь сервера хуков Gmail`},help:{"v1-1jqhcw4-4h":`HTTP-путь на локальном сервере обратных вызовов Gmail, по которому принимаются push-уведомления. Он должен соответствовать настройкам подписки, чтобы избежать потери событий.`}},"hooks%2Egmail%2Eserve%2Eport":{label:{"v1-hvr7cq-m":`Порт сервера хуков Gmail`},help:{"v1-1yku7dz-43":`Порт локального HTTP-сервера обратных вызовов Gmail при включённом режиме обслуживания. Используйте отдельный порт, чтобы избежать конфликтов с интерфейсами Gateway и управления.`}},"hooks%2Egmail%2Esubscription":{label:{"v1-19s0hm9-n":`Подписка хуков Gmail`},help:{"v1-127h8vg-5b":`Подписка Pub/Sub, используемая Gateway для получения уведомлений об изменениях Gmail из настроенной темы. Явно определите владельца подписки, чтобы избежать непреднамеренной конкуренции между несколькими потребителями.`}},"hooks%2Egmail%2Etailscale":{label:{"v1-gxsxe8-k":`Tailscale для хуков Gmail`},help:{"v1-7jzidp-4l":`Блок настроек доступа через Tailscale для публикации обратных вызовов Gmail через маршруты Serve/Funnel. Прежде чем включать какой-либо публичный входящий доступ, используйте закрытые режимы tailnet.`}},"hooks%2Egmail%2Etailscale%2Emode":{label:{"v1-1jsc22r-p":`Режим Tailscale для хуков Gmail`},help:{"v1-vhm395-4u":`Режим доступа через Tailscale для обратных вызовов Gmail: "off", "serve" или "funnel". Используйте "serve" для доставки внутри частной сети tailnet, а "funnel" — только если требуется входящий доступ из интернета.`}},"hooks%2Egmail%2Etailscale%2Epath":{label:{"v1-1nkowt3-p":`Путь Tailscale для хука Gmail`},help:{"v1-fr8qi-4m":`Путь, публикуемый Tailscale Serve/Funnel для перенаправления обратных вызовов Gmail, когда эта функция включена. Согласуйте его с конфигурацией вебхука Gmail, чтобы запросы поступали нужному обработчику.`}},"hooks%2Egmail%2Etailscale%2Etarget":{label:{"v1-1u75uvt-r":`Целевой адрес Tailscale для хука Gmail`},help:{"v1-1twwxge-47":`Адрес локального сервиса, на который Tailscale Serve/Funnel перенаправляет запросы (например, http://127.0.0.1:8787). Явно указывайте адреса петлевого интерфейса, чтобы избежать неоднозначной маршрутизации.`}},"hooks%2Egmail%2Ethinking":{label:{"v1-rxxhgo-s":`Переопределение уровня рассуждений для хука Gmail`},help:{"v1-17owk9q-4z":`Переопределение уровня рассуждений для запусков агента, инициированных Gmail: "off", "minimal", "low", "medium" или "high". Для повседневной автоматизации работы с почтой задавайте умеренный уровень по умолчанию, чтобы контролировать затраты и задержки.`}},"hooks%2Egmail%2Etopic":{label:{"v1-1n1wncx-o":`Тема Pub/Sub для хука Gmail`},help:{"v1-iled0e-4p":`Имя темы Google Pub/Sub, которую механизм отслеживания Gmail использует для публикации уведомлений об изменениях в этом аккаунте. Прежде чем включать отслеживание, убедитесь, что настройки IAM темы предоставляют Gmail право на публикацию.`}},"hooks%2Einternal":{label:{"v1-1hsfqas-e":`Внутренние хуки`},help:{"v1-piq9k-4v":`Параметры выполнения внутренних хуков для встроенных и пользовательских обработчиков событий, загружаемых по путям модулей. Используйте их для доверенных автоматизаций внутри процесса и строго ограничивайте набор загружаемых обработчиков.`}},"hooks%2Einternal%2Eenabled":{label:{"v1-1kouv99-m":`Внутренние хуки включены`},help:{"v1-1wv0289-4c":`Включает обработку внутренних хуков и настроенных записей в среде выполнения внутренних хуков. Оставьте отключённым, если внутренние хуки не настроены намеренно.`}},"hooks%2Einternal%2Eentries":{label:{"v1-1coawdn-l":`Записи внутренних хуков`},help:{"v1-1ovi38l-4o":`Настроенные записи внутренних хуков, используемые для регистрации конкретных обработчиков среды выполнения и метаданных. Задавайте записи явно и храните их версии, чтобы поведение в рабочей среде можно было проверить.`}},"hooks%2Einternal%2Eload":{label:{"v1-e71kzu-k":`Загрузчик внутренних хуков`},help:{"v1-11re5ph-4p":`Настройки загрузчика внутренних хуков, определяющие, где искать модули обработчиков при запуске. Ограничивайте корневые каталоги загрузки, чтобы снизить риск случайных конфликтов или перекрытия модулей.`}},"hooks%2Einternal%2Eload%2EextraDirs":{label:{"v1-1oj9uqa-v":`Дополнительные каталоги внутренних хуков`},help:{"v1-1xfdqxg-4c":`Дополнительные каталоги для поиска модулей внутренних хуков помимо стандартных путей загрузки. Сводите их количество к минимуму и контролируйте их, чтобы снизить риск случайного перекрытия модулей.`}},"hooks%2Emappings":{label:{"v1-16wwkft-d":`Правила сопоставления хуков`},help:{"v1-frhp3v-5i":`Упорядоченные правила, которые сопоставляют входящие запросы хуков и выбирают действия wake или agent с необязательной маршрутизацией доставки. Размещайте более конкретные правила первыми, чтобы правила с широкими шаблонами не перехватывали все запросы.`}},"hooks%2Emappings%5B%5D%2Eaction":{label:{"v1-bvm5m2-j":`Действие правила сопоставления хуков`},help:{"v1-1r5zt5f-5f":`Тип действия правила сопоставления: "wake" запускает процесс пробуждения агента, а "agent" передаёт запрос непосредственно агенту для обработки. Используйте "agent" для немедленного выполнения, а "wake" — когда предпочтительна обработка по периодическому сигналу активности.`}},"hooks%2Emappings%5B%5D%2EagentId":{label:{"v1-r93mi6-l":`ID агента в правиле сопоставления хуков`},help:{"v1-l0uioz-4y":`ID целевого агента для выполнения правила сопоставления, когда маршрутизация действий не должна использовать значения по умолчанию. Используйте выделенных агентов автоматизации, чтобы изолировать работу вебхуков от интерактивных сеансов оператора.`}},"hooks%2Emappings%5B%5D%2EallowUnsafeExternalContent":{label:{"v1-1nlag5p-16":`Разрешить небезопасное внешнее содержимое в правиле сопоставления хука`},help:{"v1-1np9426-57":`При значении true содержимое правила сопоставления может включать в создаваемые сообщения внешние данные с менее строгой очисткой. По умолчанию оставляйте false и включайте только для доверенных источников с проверенной логикой преобразования.`}},"hooks%2Emappings%5B%5D%2Echannel":{label:{"v1-f719ab-t":`Канал доставки для правила сопоставления хука`},help:{"v1-oz7pu5-5s":`Переопределение канала доставки результатов правила сопоставления (например, "last", "telegram", "discord", "slack", "signal", "imessage" или "msteams"). Задавайте переопределения канала явно, чтобы избежать случайной отправки в другой канал.`}},"hooks%2Emappings%5B%5D%2Edeliver":{label:{"v1-2h4axx-q":`Доставка ответа для правила сопоставления хука`},help:{"v1-12tbbam-5o":`Определяет, будут ли результаты выполнения правила сопоставления доставляться получателю в канале или обрабатываться без отправки. Отключайте доставку для фоновых автоматизаций, которые не должны публиковать результаты для пользователей.`}},"hooks%2Emappings%5B%5D%2EforEach":{label:{"v1-fzd0ar-o":`Ключ поэлементной обработки для правила сопоставления хука`},help:{"v1-1d593op-7e":`Ключ массива верхнего уровня во входных данных, по которому правило сопоставления выполняет поэлементную обработку: каждый элемент запускает отдельное действие, а шаблоны и преобразования получают данные, в массиве которых содержится только текущий элемент. Предустановка Gmail использует forEach: messages, поэтому пакетные push-уведомления запускают отдельное выполнение для каждого письма.`}},"hooks%2Emappings%5B%5D%2Eid":{label:{"v1-1nctnx-f":`ID правила сопоставления хука`},help:{"v1-q1t4zw-57":`Необязательный постоянный идентификатор правила хука, используемый для аудита, диагностики и адресных обновлений. Используйте уникальные идентификаторы, чтобы в журналах и сравнениях конфигураций можно было однозначно ссылаться на правила.`}},"hooks%2Emappings%5B%5D%2Ematch":{label:{"v1-rbsioh-i":`Условия сопоставления правила хука`},help:{"v1-6u73k2-5a":`Объект, объединяющий условия сопоставления правила, например путь и источник, которые проверяются перед маршрутизацией действий. Задавайте конкретные критерии сопоставления, чтобы посторонний трафик вебхуков не запускал автоматизацию.`}},"hooks%2Emappings%5B%5D%2Ematch%2Epath":{label:{"v1-mc6fc4-n":`Путь для сопоставления правила хука`},help:{"v1-1d7dc5j-4k":`Условие сопоставления по пути для правила хука; обычно сравнивается с путём входящего запроса. Используйте его, чтобы разделять сценарии автоматизации по группам путей конечных точек вебхуков.`}},"hooks%2Emappings%5B%5D%2Ematch%2Esource":{label:{"v1-1mx72t2-p":`Источник для сопоставления правила хука`},help:{"v1-177zgy7-52":`Условие сопоставления по источнику для правила хука; обычно задаётся доверенными метаданными вышестоящей системы или логикой адаптера. Используйте постоянные идентификаторы источников, чтобы маршрутизация оставалась детерминированной при повторных попытках.`}},"hooks%2Emappings%5B%5D%2EmessageTemplate":{label:{"v1-1h1bgln-t":`Шаблон сообщения правила хука`},help:{"v1-ggqszl-5c":`Шаблон для преобразования структурированных входных данных правила в итоговое содержимое сообщения, отправляемого по целевому маршруту действия. Используйте детерминированные шаблоны, чтобы последующий разбор и поведение оставались стабильными.`}},"hooks%2Emappings%5B%5D%2Emodel":{label:{"v1-17bx393-r":`Переопределение модели для правила хука`},help:{"v1-10qyo4j-5e":`Необязательное переопределение модели для запусков по правилу сопоставления, когда автоматизация должна использовать модель, отличную от модели агента по умолчанию. Используйте эту настройку лишь при необходимости, чтобы поведение оставалось предсказуемым при выполнении правил.`}},"hooks%2Emappings%5B%5D%2Ename":{label:{"v1-gos70z-h":`Название правила сопоставления хука`},help:{"v1-zrd9tn-4v":`Понятное отображаемое название правила сопоставления, используемое в диагностике и интерфейсах настройки для операторов. Выбирайте краткие и описательные названия, чтобы назначение маршрутизации было очевидным при разборе инцидентов.`}},"hooks%2Emappings%5B%5D%2EsessionKey":{label:{"v1-1g7byfn-o":`Ключ сеанса правила сопоставления хука`},help:{"v1-lfnt1n-58":`Явное переопределение ключа сеанса для сообщений, доставляемых по правилу сопоставления, позволяющее управлять непрерывностью ветки обсуждения. Используйте стабильные ключи с ограниченной областью действия, чтобы повторные события связывались между собой, не затрагивая посторонние разговоры.`}},"hooks%2Emappings%5B%5D%2EsessionMode":{label:{"v1-p4nrxz-p":`Режим сеанса правила сопоставления хука`},help:{"v1-1ggtdze-5k":`Управляет непрерывностью сеанса правила сопоставления: "isolated" создаёт новый сеанс запуска, а "persistent" повторно использует определённый sessionKey. Оставьте isolated, если интеграции не требуется длительное сохранение контекста.`}},"hooks%2Emappings%5B%5D%2EtextTemplate":{label:{"v1-1jch0ob-q":`Текстовый шаблон правила сопоставления хука`},help:{"v1-1rg732b-4y":`Резервный шаблон обычного текста, используемый, когда расширенное отображение содержимого нежелательно или не поддерживается. Используйте его для создания краткой сводки в едином формате при доставке сообщений в чаты.`}},"hooks%2Emappings%5B%5D%2Ethinking":{label:{"v1-omlp34-u":`Переопределение режима рассуждения для правила сопоставления хука`},help:{"v1-17hq8me-57":`Необязательное переопределение уровня усилий на рассуждение для запусков по правилу сопоставления, позволяющее настроить баланс между задержкой и глубиной рассуждений. Для хуков с большим объёмом вызовов используйте низкий или минимальный уровень, если более глубокие рассуждения явно не требуются.`}},"hooks%2Emappings%5B%5D%2EtimeoutSeconds":{label:{"v1-9tp4s7-q":`Тайм-аут правила сопоставления хука (сек)`},help:{"v1-1r44ox2-4i":`Максимальное время выполнения действия по правилу сопоставления до срабатывания обработки тайм-аута. Для источников вебхуков с большим объёмом вызовов задавайте более строгие ограничения, чтобы избежать накопления очереди.`}},"hooks%2Emappings%5B%5D%2Eto":{label:{"v1-hpcs3s-x":`Адресат доставки по правилу сопоставления хука`},help:{"v1-1p7928e-55":`Идентификатор адресата в выбранном канале, если ответы по правилу сопоставления должны направляться фиксированному получателю. Перед включением правил сопоставления в рабочей среде проверьте форматы адресатов, принятые у провайдера.`}},"hooks%2Emappings%5B%5D%2Etransform":{label:{"v1-yiku9o-m":`Преобразование правила сопоставления хука`},help:{"v1-14igxpm-5m":`Блок конфигурации преобразования, задающий модуль и экспортируемую функцию для предварительной обработки перед выполнением действия по правилу сопоставления. Используйте преобразования только из проверенного кода и обеспечивайте детерминированное поведение для воспроизводимой автоматизации.`}},"hooks%2Emappings%5B%5D%2Etransform%2Eexport":{label:{"v1-10vpr1c-l":`Экспортируемая функция преобразования хука`},help:{"v1-atn8v-4b":`Именованная экспортируемая функция для вызова из модуля преобразования; если не указана, используется экспорт модуля по умолчанию. Задайте её, если один файл содержит несколько обработчиков преобразования.`}},"hooks%2Emappings%5B%5D%2Etransform%2Emodule":{label:{"v1-qukz8e-l":`Модуль преобразования хука`},help:{"v1-56futq-4v":`Относительный путь к модулю преобразования, загружаемому из hooks.transformsDir для изменения входящих данных перед доставкой. Используйте только локальные проверенные модули и не допускайте в путях конструкций для выхода за пределы каталога.`}},"hooks%2Emappings%5B%5D%2EwakeMode":{label:{"v1-vk3gk3-m":`Режим пробуждения для правила хука`},help:{"v1-1dzqfnw-59":`Режим планирования пробуждения: "now" запускает пробуждение немедленно, а "next-heartbeat" откладывает его до следующего цикла пульса. Используйте отложенный режим для автоматизаций с низким приоритетом, допускающих небольшую задержку.`}},"hooks%2Epath":{label:{"v1-1uhbsf3-j":`Путь конечной точки хуков`},help:{"v1-1l9ijzv-4u":"HTTP-путь конечной точки хуков (например, `/hooks`) на сервере управления Gateway. Для многоуровневой защиты используйте путь, который сложно угадать, в сочетании с проверкой токена."}},"hooks%2Epresets":{label:{"v1-4shxcz-d":`Предустановки хуков`},help:{"v1-dp8m0l-4v":`Именованные наборы предустановок хуков, применяемые при загрузке для задания стандартных правил сопоставления и поведения по умолчанию. Указывайте используемые предустановки явно, чтобы операторы могли проверить, какие автоматизации активны.`}},"hooks%2Etoken":{label:{"v1-1uqdexy-g":`Токен аутентификации хуков`},help:{"v1-1ihf6mv-82":`Общий токен предъявителя, проверяемый на входе хуков для аутентификации запросов перед выполнением правил сопоставления. Считайте владельцев токена полностью доверенными отправителями запросов к входным точкам хуков, а не отдельной ролью с правами ниже прав владельца. Используйте подстановку из переменных окружения и регулярно меняйте токен, если конечные точки вебхуков доступны из интернета.`}},"hooks%2EtransformsDir":{label:{"v1-1sc7ulb-q":`Каталог преобразований хуков`},help:{"v1-1ayj9p0-4t":`Базовый каталог модулей преобразования хуков, на которые ссылаются пути transform.module в правилах сопоставления. Используйте контролируемый каталог репозитория, чтобы динамические импорты оставались проверяемыми и предсказуемыми.`}},logging:{label:{"v1-rq08xq-7":`Журналирование`},help:{"v1-11an9pb-5e":`Настройки журналирования: уровень важности, места вывода, форматирование и сокрытие конфиденциальных данных. Для рабочей среды задавайте достаточно строгие уровни и правила сокрытия, сохраняя при этом полезную диагностическую информацию.`}},"logging%2Eaudit":{label:{"v1-7v96zt-c":`Журнал аудита`},help:{"v1-1lauvy2-6w":`Ограниченная история аудита, содержащая только метаданные, для проверки оператором. Записи о запусках и инструментах включены по умолчанию; сбор метаданных жизненного цикла сообщений включается отдельно, поскольку затрагивает конфиденциальность. Фоновая запись выполняется без гарантии сохранения всех событий и не заменяет архив без потерь для соблюдения нормативных требований.`}},"logging%2Eaudit%2Eenabled":{label:{"v1-pxk7dc-k":`Журнал аудита включён`},help:{"v1-snknxb-4v":`Записывает новые события аудита запусков, инструментов и сообщений, для которых включён аудит. По умолчанию: true. Изменения применяются немедленно; принятые операции записи завершаются, а сохранённые строки остаются доступными для запросов до истечения срока хранения.`}},"logging%2Eaudit%2EexecutionIdentity":{label:{"v1-163ujga-o":`Аудит идентификационных данных выполнения`},help:{"v1-1ucirwv-5b":`Сохраняет ограниченный объём данных об идентичности выполнения для проверки конкретного запуска. По умолчанию: false. Требует включения logging.audit.enabled и применяется к новым запускам, допущенным к выполнению; существующие контексты остаются без изменений.`}},"logging%2Eaudit%2Emessages":{label:{"v1-1bguzvj-j":`Область аудита сообщений`},help:{"v1-1yg4lc3-76":`Управляет записью событий жизненного цикла сообщений без сохранения их содержимого: "off" (по умолчанию), "direct" — только для заведомо личных бесед, "all" — для личных и групповых бесед, каналов и бесед неизвестного типа. Требует включения logging.audit.enabled. Изменения применяются к последующим событиям жизненного цикла.`}},"logging%2EconsoleLevel":{label:{"v1-1mambfm-h":`Уровень журналирования в консоли`},help:{"v1-16badbd-5u":`Пороговый уровень логирования для консоли: "silent", "fatal", "error", "warn", "info", "debug" или "trace". Позволяет сократить вывод в локальной консоли, при необходимости сохранив более подробные логи в файле.`}},"logging%2EconsoleStyle":{label:{"v1-1buy3td-h":`Стиль логов в консоли`},help:{"v1-d7u0iq-3q":`Формат вывода в консоль: "pretty" или "json". Используйте json для автоматического разбора в конвейерах обработки, а pretty — для удобного чтения в терминале.`}},"logging%2Efile":{label:{"v1-1o25uj4-d":`Путь к файлу логов`},help:{"v1-16gaitv-4w":`Необязательный путь к файлу для сохранения логов в дополнение к выводу в консоль или вместо него. Используйте контролируемый путь с доступом на запись и настройте хранение и ротацию в соответствии с вашей эксплуатационной политикой.`}},"logging%2Elevel":{label:{"v1-1vskr8z-9":`Уровень логирования`},help:{"v1-1r5yku0-5o":`Основной пороговый уровень логирования во время выполнения: "silent", "fatal", "error", "warn", "info", "debug" или "trace". В рабочей среде оставляйте "info" или "warn", а debug/trace используйте только при диагностике.`}},"logging%2EredactPatterns":{label:{"v1-17ykioa-p":`Пользовательские шаблоны маскирования`},help:{"v1-1esa6eg-7k":`Пользовательские строки регулярных выражений заменяют стандартный список строк для вывода в журналы и расшифровки и дополняют защитные правила для интерфейса, инструментов и диагностики. Встроенная защита тел форм, структурированных данных аутентификации и ключей AWS без обрамления применяется всегда. Используйте эту настройку для маскирования токенов и идентификаторов, специфичных для вашего развёртывания.`}},mcp:{label:{"v1-4jhiv7-3":`MCP`},help:{"v1-cyzwkt-51":`Глобальные определения серверов MCP, управляемые OpenClaw. Встроенный OpenClaw и другие адаптеры среды выполнения могут использовать эти серверы без сохранения их определений в настройках проекта, принадлежащих среде выполнения.`}},"mcp%2Eapps":{label:{"v1-1p7rgdd-8":`Приложения MCP`},help:{"v1-amyd91-38":`Поддержка интерфейса MCP Apps. Если включена, настроенные MCP-серверы могут предоставлять интерактивные HTML-представления результатов работы своих инструментов.`}},"mcp%2Eapps%2Eenabled":{label:{"v1-15iqtvs-g":`MCP Apps включены`},help:{"v1-ghqy98-3w":`Включение отображения MCP Apps и моста между приложением и сервером. Оставьте выключенным, если не доверяете настроенным MCP-серверам, предоставляющим ресурсы интерфейса приложений.`}},"mcp%2Eapps%2EsandboxOrigin":{label:{"v1-es3gf8-n":`Источник песочницы MCP Apps`},help:{"v1-1sxv3mf-6v":`Необязательный выделенный публичный источник HTTP(S) для MCP Apps. Используйте его за обратным прокси или терминатором TLS и направляйте запросы с него только на настроенный порт песочницы MCP Apps. Он должен отличаться от источника Control UI и не должен предоставлять содержимое, требующее аутентификации.`}},"mcp%2Eapps%2EsandboxPort":{label:{"v1-15qo425-l":`Порт песочницы MCP Apps`},help:{"v1-1b8n71l-4p":`Выделенный порт прослушивания песочницы MCP Apps. По умолчанию используется порт Gateway плюс один. Укажите свободный порт, если этот порт уже занят другой локальной службой или профилем Gateway.`}},"mcp%2Eservers":{label:{"v1-1mnexav-b":`MCP-серверы`},help:{"v1-157ozoz-42":`Именованные определения MCP-серверов. OpenClaw хранит их в собственной конфигурации, а адаптеры среды выполнения определяют поддерживаемые транспорты во время выполнения.`}},"mcp%2Eservers%2E*%2Eauth":{label:{"v1-4i7ar4-f":`Аутентификация MCP-сервера`}},"mcp%2Eservers%2E*%2Eclient_cert":{label:{"v1-8xj19d-m":`Сертификат клиента MCP`}},"mcp%2Eservers%2E*%2Eclient_key":{label:{"v1-14y3g3x-e":`Ключ клиента MCP`}},"mcp%2Eservers%2E*%2EclientCert":{label:{"v1-8xj19d-m":`Сертификат клиента MCP`}},"mcp%2Eservers%2E*%2EclientKey":{label:{"v1-14y3g3x-e":`Ключ клиента MCP`}},"mcp%2Eservers%2E*%2Ecodex":{label:{"v1-1abejxp-k":`Проекция MCP для Codex`},help:{"v1-slcmq1-6x":`Метаданные OpenClaw для передачи настроек только в потоки Codex app-server. Они не влияют на сеансы ACP или общую конфигурацию среды выполнения Codex. Не указывайте этот блок, чтобы сервер оставался доступным для всех агентов Codex app-server со стандартным поведением Codex при подтверждении MCP.`}},"mcp%2Eservers%2E*%2Ecodex%2Eagents":{label:{"v1-tu0z1y-g":`Агенты MCP в Codex`},help:{"v1-8q98n8-67":`Необязательный список непустых идентификаторов агентов OpenClaw, которым следует передать этот сервер MCP в конфигурации потоков Codex app-server. Пустые списки, списки с пустыми значениями или некорректные списки блокируют доступ; если список не указан, сервер передаётся в конфигурацию всех агентов Codex app-server.`}},"mcp%2Eservers%2E*%2Ecodex%2Edefault_tools_approval_mode":{label:{"v1-uwmd-n":`Подтверждение инструментов MCP в Codex`},help:{"v1-1xql0qr-3d":`Имя параметра в формате Codex для того же режима подтверждения инструментов MCP на уровне сервера. В конфигурации OpenClaw предпочтительно использовать defaultToolsApprovalMode.`}},"mcp%2Eservers%2E*%2Ecodex%2EdefaultToolsApprovalMode":{label:{"v1-uwmd-n":`Подтверждение инструментов MCP в Codex`},help:{"v1-y5vsqq-3s":`Необязательный режим подтверждения инструментов MCP в Codex для этого сервера: "auto", "prompt" или "approve". Используйте только для серверов MCP, которым вы осознанно доверяете.`}},"mcp%2Eservers%2E*%2EconnectionTimeoutMs":{label:{"v1-1ofxxy1-o":`Тайм-аут подключения MCP (мс)`}},"mcp%2Eservers%2E*%2Eenabled":{label:{"v1-hkfmxj-i":`Сервер MCP включён`}},"mcp%2Eservers%2E*%2Eoauth":{label:{"v1-j06h60-9":`OAuth для MCP`}},"mcp%2Eservers%2E*%2Eoauth%2EauthProfileId":{label:{"v1-1xxlhb-m":`Профиль аутентификации OAuth для MCP`},help:{"v1-fcrb4u-5z":`Идентификатор профиля аутентификации с поддержкой обновления токена, используемого для передачи текущего bearer-токена этому удалённому серверу MCP. Если задан, OpenClaw находит профиль и обновляет его во время выполнения, не передавая данные для обновления токена далее.`}},"mcp%2Eservers%2E*%2Eoauth%2EclientMetadataUrl":{label:{"v1-1d7wndt-t":`URL метаданных клиента OAuth для MCP`}},"mcp%2Eservers%2E*%2Eoauth%2Eidentity":{label:{"v1-1l48ph6-i":`Идентификация OAuth для MCP`},help:{"v1-1ie6ys7-59":`Принадлежность учётных данных OAuth для этого сервера. Не указывайте это поле или используйте "shared" для учётных данных, которыми управляет оператор; используйте "per-requester", чтобы каждый аутентифицированный отправитель мог подключить собственную учётную запись.`}},"mcp%2Eservers%2E*%2Eoauth%2EredirectUrl":{label:{"v1-1yf3yu9-m":`URL перенаправления OAuth для MCP`}},"mcp%2Eservers%2E*%2Eoauth%2Escope":{label:{"v1-xvnbwc-f":`Область доступа OAuth для MCP`}},"mcp%2Eservers%2E*%2ErequestTimeoutMs":{label:{"v1-7skvfk-o":`Тайм-аут запроса MCP (мс)`}},"mcp%2Eservers%2E*%2Essl_verify":{label:{"v1-16l2l8l-k":`Проверка TLS для MCP`}},"mcp%2Eservers%2E*%2EsslVerify":{label:{"v1-16l2l8l-k":`Проверка TLS для MCP`}},"mcp%2Eservers%2E*%2Esupports_parallel_tool_calls":{label:{"v1-14b32qt-n":`Параллельные вызовы инструментов MCP`}},"mcp%2Eservers%2E*%2EsupportsParallelToolCalls":{label:{"v1-14b32qt-n":`Параллельные вызовы инструментов MCP`}},"mcp%2Eservers%2E*%2EtoolFilter":{label:{"v1-m19ao9-i":`Выбор инструментов MCP`},help:{"v1-10poyzb-4v":`Выбор инструментов MCP для отдельного сервера. Используйте include, чтобы сделать доступными только инструменты MCP с выбранными именами, или exclude, чтобы скрыть их. Можно указывать точные имена и простые шаблоны с '*'.`}},"mcp%2Eservers%2E*%2EtoolFilter%2Eexclude":{label:{"v1-bikffc-i":`Исключённые инструменты MCP`},help:{"v1-ijrc5y-1u":`Точные имена инструментов MCP или простые шаблоны с '*' для скрытия инструментов этого сервера.`}},"mcp%2Eservers%2E*%2EtoolFilter%2Einclude":{label:{"v1-qa5hua-i":`Включённые инструменты MCP`},help:{"v1-89fdfq-3o":`Точные имена инструментов MCP или простые шаблоны с '*' для предоставления доступа к инструментам этого сервера. Если не указаны, все инструменты сервера остаются доступными, кроме явно исключённых.`}},"mcp%2EsessionIdleTtlMs":{label:{"v1-1teh0v2-p":`TTL бездействия сессии MCP (мс)`},help:{"v1-j9si74-87":`Необязательный срок бездействия в миллисекундах, после которого среды выполнения MCP сессий OpenClaw удаляются. Если значение не задано или равно 0, среды остаются активными до очистки сессии или завершения работы Gateway. Положительные значения округляются вниз; активные аренды и ожидающие запросы на получение ресурса предотвращают удаление. Среды, принадлежащие отдельному запуску, в любом случае завершают работу по окончании этого разового запуска.`}},memory:{label:{"v1-oopaku-6":`Память`},help:{"v1-1wlx40m-13":`Настройки встроенной памяти (глобальные).`}},"memory%2Ecitations":{label:{"v1-1cdo86v-l":`Режим ссылок на источники в памяти`},help:{"v1-1q6dxr5-4u":`Управляет отображением ссылок на источники в ответах: "auto" показывает ссылки, когда они полезны, "on" — всегда, а "off" скрывает их. Оставьте "auto" для оптимального соотношения полезной информации и шума по умолчанию.`}},"memory%2Esearch":{label:{"v1-dvkpxe-d":`Поиск в памяти`},help:{"v1-1ukbud1-25":`Векторный поиск по MEMORY.md и memory/*.md (поддерживается переопределение настроек для отдельных агентов).`}},"memory%2Esearch%2Ecache%2Eenabled":{label:{"v1-kv1t3d-t":`Кэш эмбеддингов для поиска в памяти`},help:{"v1-d8h2e4-5b":`Кэширует вычисленные эмбеддинги фрагментов в SQLite для ускорения повторной индексации и инкрементальных обновлений (по умолчанию: true). Оставьте включённым, если не проверяете корректность кэша и не стремитесь минимизировать использование диска.`}},"memory%2Esearch%2EdocumentInputType":{label:{"v1-mmpk8t-x":`Тип входных документов для поиска в памяти`},help:{"v1-1ui33sv-5f":"Необязательное значение `input_type`, зависящее от провайдера, для эмбеддингов документов и индексации памяти. Используйте его с OpenAI-совместимыми эндпоинтами асимметричных эмбеддингов, которым требуется метка фрагмента или документа."}},"memory%2Esearch%2Eenabled":{label:{"v1-ed34tb-k":`Включить поиск по памяти`},help:{"v1-14f11b9-4t":`Главный переключатель индексации и поиска по памяти для этого профиля агента. Оставьте включённым для семантического поиска в памяти; отключите, если нужны ответы без сохранения состояния.`}},"memory%2Esearch%2Eexperimental%2EsessionMemory":{label:{"v1-1jhaosz-16":`Индекс сессий для поиска по памяти (экспериментально)`},help:{"v1-qvhv8z-3i":`Индексирует записи сессий для поиска по памяти. Сохраняйте это расширенное переопределение, если наследование настроек поиска в памяти различается на корневом уровне и на уровне отдельных агентов.`}},"memory%2Esearch%2EextraPaths":{label:{"v1-1ommwo8-i":`Дополнительные пути памяти`},help:{"v1-ojqokq-7i":`Добавляет дополнительные каталоги или файлы .md в индекс памяти помимо файлов памяти по умолчанию. Элементы могут быть строками с путями или объектами с glob-шаблоном относительно корня. Если включена мультимодальная память, подходящие изображения и аудиофайлы по этим путям также могут индексироваться.`}},"memory%2Esearch%2EextraPaths%2E*%2Epath":{label:{"v1-1htq423-h":`Дополнительный путь памяти`},help:{"v1-b9mbq8-3m":`Задаёт дополнительный каталог или файл памяти. Относительные пути отсчитываются от рабочего пространства агента; при прямом указании файла индексируется именно этот файл.`}},"memory%2Esearch%2EextraPaths%2E*%2Epattern":{label:{"v1-eunp4t-p":`Шаблон дополнительного пути памяти`},help:{"v1-j8br1v-4e":`Ограничивает содержимое указанного каталога поддерживаемыми файлами, соответствующими этому glob-шаблону относительно корня, например "runbooks/**/*.md". Не задавайте шаблон, чтобы рекурсивно сканировать все поддерживаемые файлы.`}},"memory%2Esearch%2Efallback":{label:{"v1-nj3gc-m":`Резервный провайдер поиска в памяти`},help:{"v1-1r6368w-6p":`Резервный провайдер на случай сбоя основного провайдера эмбеддингов: "openai", "gemini", "voyage", "mistral", "bedrock", "lmstudio", "ollama", "local" или "none". Для надёжной работы в производственной среде укажите действующего резервного провайдера; используйте "none", только если предпочитаете получать явные ошибки.`}},"memory%2Esearch%2EinputType":{label:{"v1-aslwem-o":`Тип входных данных для поиска в памяти`},help:{"v1-26vbwe-5u":"Используйте это необязательное значение `input_type`, зависящее от провайдера, только если одна и та же метка должна применяться к запросам на создание эмбеддингов и для поисковых запросов, и для документов. Для асимметричных провайдеров лучше использовать queryInputType и documentInputType."}},"memory%2Esearch%2Elocal%2EmodelPath":{label:{"v1-1jkif8j-q":`Путь к локальной модели эмбеддингов`},help:{"v1-13ymbnt-5q":"Указывает источник локальной модели эмбеддингов для локального поиска в памяти, например путь к файлу GGUF или URI с префиксом `hf:`. Используйте только при значении `local` у provider и проверяйте совместимость модели перед масштабным перестроением индекса."}},"memory%2Esearch%2Emodel":{label:{"v1-1sfre8j-j":`Модель поиска в памяти`},help:{"v1-11pohrl-59":`Модель эмбеддингов, которую выбранный провайдер памяти использует вместо модели по умолчанию. Задавайте её, только если требуется явно настроить соотношение полноты поиска и стоимости за пределами настроек провайдера по умолчанию.`}},"memory%2Esearch%2Emultimodal":{label:{"v1-1lnhiq0-o":`Мультимодальный поиск в памяти`},help:{"v1-1jn02s-9e":'Необязательные настройки мультимодальной памяти для индексации изображений и аудиофайлов из настроенных дополнительных путей. Не включайте эту функцию, если ваша модель эмбеддингов явно не поддерживает кросс-модальные эмбеддинги. Пока функция включена, для `memory.search.fallback` должно быть задано значение "none". При индексации подходящие файлы загружаются настроенному удалённому провайдеру эмбеддингов.'}},"memory%2Esearch%2Emultimodal%2Eenabled":{label:{"v1-vp9cgj-v":`Включить мультимодальный поиск по памяти`},help:{"v1-1dk5d7o-7e":`Включает индексацию изображений и аудио из extraPaths для поиска по памяти. В настоящее время требует Gemini embedding-2, сохраняет поддержку только Markdown в стандартных корневых каталогах памяти, отключает резервных провайдеров поиска по памяти и загружает подходящие двоичные данные настроенному удалённому провайдеру эмбеддингов.`}},"memory%2Esearch%2Emultimodal%2EmaxFileBytes":{label:{"v1-ewn32n-13":`Максимальный размер файла для мультимодального поиска по памяти в байтах`},help:{"v1-1mmdrvk-5d":`Задаёт максимальный размер мультимодального файла в байтах, при превышении которого файл пропускается при индексации памяти. Используйте этот параметр, чтобы ограничить стоимость загрузки и время индексации, или увеличьте значение для коротких аудиозаписей высокого качества.`}},"memory%2Esearch%2Emultimodal%2Emodalities":{label:{"v1-ako4xr-z":`Модальности мультимодального поиска по памяти`},help:{"v1-alp4vh-4l":`Определяет, какие типы мультимодальных файлов индексируются из extraPaths: "image", "audio" или "all". Ограничьте выбор необходимыми типами, чтобы случайно не проиндексировать большие наборы двоичных данных.`}},"memory%2Esearch%2EoutputDimensionality":{label:{"v1-9cim9y-z":`Размерность выходных векторов поиска по памяти`},help:{"v1-1f7zu53-93":`Переопределяет размерность выходных векторов эмбеддингов памяти с учётом особенностей провайдера. Модели Gemini поддерживают размерности от 128 до 3072; рекомендуемые значения — 768, 1536 или 3072. Семейства моделей Bedrock, такие как Titan V2, Cohere V4 и Nova, имеют собственные допустимые значения. При изменении этого параметра потребуется полная переиндексация, поскольку размерность всех сохранённых векторов должна быть одинаковой.`}},"memory%2Esearch%2Eprovider":{label:{"v1-1i03ysj-m":`Провайдер поиска по памяти`},help:{"v1-5evseb-71":`Выбирает бэкенд эмбеддингов для создания векторов памяти и поиска по ним. По умолчанию — "openai"; для другого бэкенда укажите "openai-compatible", "gemini", "voyage", "mistral", "bedrock", "deepinfra", "github-copilot", "lmstudio", "ollama" или "local".`}},"memory%2Esearch%2Equery%2EmaxResults":{label:{"v1-5g82o6-p":`Максимальное число результатов поиска в памяти`},help:{"v1-13ekath-4x":`Максимальное число результатов поиска в памяти до последующего переранжирования и добавления в промпт. Увеличьте значение для более полного поиска или уменьшите для более компактных промптов и быстрых ответов.`}},"memory%2Esearch%2Equery%2EminScore":{label:{"v1-1hsndok-n":`Минимальная оценка для поиска в памяти`},help:{"v1-1ww231l-4v":`Минимальная оценка релевантности для включения результатов из памяти в итоговую выборку. Увеличьте значение, чтобы уменьшить число слабых совпадений и шум, или уменьшите, чтобы сделать отбор менее строгим.`}},"memory%2Esearch%2EqueryInputType":{label:{"v1-ita7p2-u":`Тип входных данных запроса поиска в памяти`},help:{"v1-831yrv-4q":"Необязательное значение `input_type`, зависящее от провайдера, для эмбеддингов запросов поиска в памяти. Используйте с OpenAI-совместимыми эндпоинтами асимметричных эмбеддингов, которым требуется метка запроса."}},"memory%2Esearch%2ErememberAcrossConversations":{label:{"v1-1iqw2nv-t":`Запоминать контекст между беседами`},help:{"v1-k1itm8-7y":`Использует релевантный контекст из других личных бесед этого агента через защищённый поиск по истории переписки. По умолчанию включено, только если глобальный параметр session.dmScope не задан или равен "main" и ни одна привязка не переопределяет область личных сообщений; при любой настроенной изоляции личных сообщений по умолчанию выключено. Явно заданное значение true или false всегда имеет приоритет.`}},"memory%2Esearch%2Eremote%2EapiKey":{label:{"v1-3ejsqh-o":`API-ключ удалённого сервиса эмбеддингов`},help:{"v1-nfuuu-62":`Задаёт отдельный ключ API для удалённых вызовов создания эмбеддингов при индексации памяти и обработке запросов. Используйте, если для эмбеддингов памяти нужны учётные данные, отличные от глобальных значений по умолчанию или переменных окружения.`}},"memory%2Esearch%2Eremote%2EbaseUrl":{label:{"v1-pd1jie-p":`Базовый URL удалённого сервиса эмбеддингов`},help:{"v1-1ugvqgt-5p":`Переопределяет адрес API эмбеддингов, например для прокси, совместимого с OpenAI, или собственного базового URL Gemini. Используйте только при маршрутизации через собственный шлюз или адрес поставщика; в остальных случаях оставьте значения провайдера по умолчанию.`}},"memory%2Esearch%2Eremote%2Ebatch%2Eenabled":{label:{"v1-av398b-u":`Удалённое пакетное создание эмбеддингов включено`},help:{"v1-1fehqi-5x":`Включает API пакетной обработки провайдера для задач создания эмбеддингов, если они поддерживаются (OpenAI/Gemini), повышая пропускную способность при масштабной индексации. Оставьте включённым, кроме случаев отладки сбоев пакетной обработки у провайдера или обработки очень небольших объёмов данных.`}},"memory%2Esearch%2Eremote%2Eheaders":{label:{"v1-13jt5eg-o":`Заголовки запросов к удалённому сервису эмбеддингов`},help:{"v1-1uic0kd-5i":`Добавляет пользовательские HTTP-заголовки к удалённым запросам создания эмбеддингов, объединяя их с заголовками провайдера по умолчанию. Используйте для аутентификации на прокси и маршрутизации по арендаторам. Указывайте минимум данных, чтобы избежать утечки конфиденциальных метаданных.`}},"memory%2Esearch%2Esources":{label:{"v1-po677s-l":`Источники поиска по памяти`},help:{"v1-btxtzg-57":`Выбирает источники для индексации: "memory" считывает MEMORY.md и файлы памяти, а "sessions" включает историю переписки. Оставьте ["memory"], если поиск по прошлым перепискам не нужен.`}},"memory%2Esearch%2Estore%2Evector%2Eenabled":{label:{"v1-17q1dz1-q":`Векторный индекс поиска по памяти`},help:{"v1-fbybkj-37":`Управляет семантическим индексом sqlite-vec. Сохраняйте это расширенное переопределение, если корневые политики векторного поиска отличаются от политик отдельных агентов.`}},"memory%2Esearch%2Estore%2Evector%2EextensionPath":{label:{"v1-1w275c7-z":`Путь к расширению векторного поиска по памяти`},help:{"v1-1hysv5q-58":"Переопределяет автоматически найденный путь к библиотеке расширения sqlite-vec (`.dylib`, `.so` или `.dll`). Используйте эту настройку, если среда выполнения не может автоматически найти sqlite-vec или если нужно закрепить проверенную сборку."}},messages:{label:{"v1-1wwzqad-8":`Сообщения`},help:{"v1-i5k0iw-5k":`Инфраструктура сообщений и общие настройки по умолчанию для агентов. Соседние разделы корневого уровня задают инфраструктуру и общие настройки по умолчанию для агентов; agents.defaults задаёт поведение цикла агента; записи отдельных агентов могут переопределять и те и другие настройки, где это поддерживается.`}},"messages%2EackReaction":{label:{"v1-qhntnj-i":`Эмодзи реакции подтверждения`},help:{"v1-1iip0zs-1x":`Эмодзи реакции для подтверждения получения входящих сообщений (пустое значение отключает реакцию).`}},"messages%2EackReactionScope":{label:{"v1-7m6k7l-i":`Область применения реакций подтверждения`},help:{"v1-1jvdg5n-7s":`Когда отправлять реакции подтверждения ("group-mentions", "group-all", "direct", "all", "off", "none"). "group-mentions" подтверждает сообщения в группах, в которых упоминается агент, независимо от того, обязательны ли упоминания в группе; "group-all" подтверждает каждое сообщение в группе. "off"/"none" полностью отключает реакции подтверждения.`}},"messages%2EgroupChat":{label:{"v1-aqzwi1-g":`Правила группового чата`},help:{"v1-chqsvh-4l":`Настройки обработки групповых сообщений, включая срабатывание по упоминаниям и размер окна истории. Используйте узкие шаблоны упоминаний, чтобы в групповых каналах агент не реагировал на каждое сообщение.`}},"messages%2EgroupChat%2EhistoryLimit":{label:{"v1-i0bob3-j":`Лимит истории группы`},help:{"v1-1mkbpw-9k":`Максимальное количество предыдущих сообщений группы, загружаемых в контекст на каждом шаге группового сеанса. Увеличьте значение для лучшего сохранения контекста или уменьшите для более быстрых и дешёвых ответов. История, автоматически добавляемая в промпт, ограничена 200 сообщениями. Максимальное целочисленное значение JSON выбирает размер окна по умолчанию для канала (50 для общей истории группы), а не неограниченное окно.`}},"messages%2EgroupChat%2EmentionPatterns":{label:{"v1-1367gbd-m":`Шаблоны упоминаний в группах`},help:{"v1-i7h7qc-6f":`Безопасные регулярные выражения без учёта регистра для обнаружения явных упоминаний и фраз-триггеров в групповых чатах. Используйте точные шаблоны, чтобы уменьшить число ложных срабатываний в каналах с большим потоком сообщений; некорректные или небезопасные шаблоны с вложенными повторениями игнорируются.`}},"messages%2EgroupChat%2EunmentionedInbound":{label:{"v1-1hc12l7-p":`Входящие сообщения без упоминаний в группах`},help:{"v1-17wef8h-5f":`Определяет, как передаются сообщения без упоминаний из групп с постоянно включённой обработкой. "user_request" обрабатывает их как запрос пользователя; "room_event" передаёт их как фоновый контекст, для видимого ответа на который требуется инструмент message.`}},"messages%2EgroupChat%2EvisibleReplies":{label:{"v1-1hqf9qu-l":`Видимые ответы в группах`},help:{"v1-qa4z1s-aa":`Переопределяет порядок отправки ответов модели в исходные беседы в группах и каналах. Если глобальная политика видимых ответов не задана, по умолчанию используется "automatic". Режим "message_tool" требует message(action=send) для обычных ответов ассистента и стандартных медиафайлов от инструментов; вывод среды выполнения, явно принадлежащий хосту, по-прежнему может доставляться, кроме случаев фоновых событий чата. Режим "automatic" публикует обычные ответы как прежде.`}},"messages%2Einbound":{label:{"v1-10n88z1-g":`Задержка объединения входящих сообщений`},help:{"v1-ebyu5x-4a":`Настройки задержки объединения входящих сообщений, применяемые до начала обработки очереди или шага диалога. Настройте их с учётом особенностей провайдера для серий сообщений, быстро поступающих от одного отправителя.`}},"messages%2Einbound%2EbyChannel":{label:{"v1-bsp0no-w":`Задержка объединения входящих сообщений по каналам (мс)`},help:{"v1-wbz54j-4g":`Переопределения задержки объединения входящих сообщений по каналам в миллисекундах, с идентификатором провайдера в качестве ключа. Используйте, если некоторые провайдеры отправляют фрагменты сообщений чаще других.`}},"messages%2Einbound%2EdebounceMs":{label:{"v1-1dqihif-t":`Задержка объединения входящих сообщений (мс)`},help:{"v1-1616yo2-7w":`Период ожидания без новых сообщений (мс) для объединения быстро поступающих сообщений от одного отправителя. В Telegram по умолчанию используется 300 мс, если значение не переопределено ни глобально, ни для канала; в других каналах — 0. Нулевое значение отключает обычное объединение серий сообщений, но Telegram по-прежнему собирает длинные сообщения из фрагментов, размер которых близок к лимиту.`}},"messages%2Equeue":{label:{"v1-yvcqg5-d":`Очередь входящих сообщений`},help:{"v1-hm2o31-48":`Стратегия очереди для входящих сообщений, поступающих во время активного выполнения в сеансе. Используйте для настройки корректировки текущего выполнения, отложенных продолжений, объединения сообщений или прерывания.`}},"messages%2Equeue%2EbyChannel":{label:{"v1-15qfdgr-l":`Режим очереди по каналам`},help:{"v1-4rf8z8-54":`Переопределения режима очереди по каналам, с идентификатором провайдера в качестве ключа (например, telegram, discord, slack). Используйте, если характер потока сообщений в одном из каналов требует поведения, отличного от глобальных настроек по умолчанию.`}},"messages%2Equeue%2Ecap":{label:{"v1-1dxqjbg-e":`Вместимость очереди`},help:{"v1-16ql8c7-4j":`Максимальное количество входящих элементов, сохраняемых в очереди до применения политики удаления. По умолчанию — 20; ограничивайте размер очереди в каналах с большим потоком сообщений, чтобы использование памяти оставалось предсказуемым.`}},"messages%2Equeue%2EdebounceMsByChannel":{label:{"v1-yp9b0s-13":`Резервная задержка объединения в очереди по каналам (мс)`},help:{"v1-4tpyt7-4e":`Переопределения задержки объединения сообщений в очереди по каналам, с идентификатором провайдера в качестве ключа. Используйте для независимой настройки обработки всплесков сообщений в чатах с разным темпом общения.`}},"messages%2Equeue%2Edrop":{label:{"v1-ywb1ky-j":`Стратегия удаления из очереди`},help:{"v1-ydb2rw-6m":`Стратегия удаления при превышении лимита очереди. "summarize" удаляет самые старые записи, но сохраняет краткие сводки; "old" удаляет самые старые записи без сводок; "new" отклоняет самый новый элемент. Используйте "summarize" для длительных чатов, где важен контекст.`}},"messages%2Equeue%2Emode":{label:{"v1-x1nejf-a":`Режим очереди`},help:{"v1-19k7gy1-67":`Режим очереди для активных запусков. Используйте "steer", чтобы добавлять запросы в активный запуск, "followup" — чтобы выполнять их позже, "collect" — чтобы позже обрабатывать совместимые сообщения пакетом, или "interrupt" — чтобы прерывать активный запуск перед выполнением самого нового запроса.`}},"messages%2EresponsePrefix":{label:{"v1-1cwunbc-o":`Префикс исходящего ответа`}},"messages%2EresponseUsage":{label:{"v1-nh6iuv-p":`Режим сводки использования под ответом по умолчанию`},help:{"v1-l3shsx-dv":`Режим сводки использования под каждым ответом по умолчанию ("off"|"tokens"|"full"), применяемый к сеансам, в которых режим не был выбран через /usage. Также принимает "on" как устаревший псевдоним для "tokens". Можно указать отдельный режим или набор настроек по каналам с резервным значением "default". Приоритет: значение сеанса -> настройка канала -> default -> off; явный выбор через /usage (включая off) сохраняется и переопределяет значение по умолчанию. Используйте /usage reset (псевдонимы: inherit, clear, default), чтобы сбросить переопределение сеанса и снова наследовать настроенное здесь значение по умолчанию.`}},"messages%2EstatusReactions":{label:{"v1-17ysjar-g":`Реакции состояния`},help:{"v1-193764l-3s":`Реакции, отражающие этапы работы агента: эмодзи на сообщении, вызвавшем запуск, обновляется по мере выполнения (в очереди → размышление → инструмент → завершено/ошибка).`}},"messages%2EstatusReactions%2Eenabled":{label:{"v1-rqjrr0-n":`Включить реакции состояния`},help:{"v1-1qnmmnc-7x":`Включает реакции, отражающие этапы обработки, в поддерживаемых каналах. В Discord отсутствие значения считается включением, если активны реакции подтверждения; Slack, Signal, Telegram и WhatsApp используют реакции этапов обработки только при значении true. По умолчанию Slack отображает ход выполнения с помощью встроенного статуса ассистента в ветке.`}},"messages%2EusageTemplate":{label:{"v1-1pj1fhz-l":`Шаблон нижнего колонтитула статистики использования`},help:{"v1-1xibc23-47":`Пользовательский шаблон нижнего колонтитула для /usage full: встроенный объект или путь к JSON-файлу. Если шаблон некорректен или недоступен, используется встроенная строка статистики использования.`}},"messages%2EvisibleReplies":{label:{"v1-awhafd-f":`Видимые ответы`},help:{"v1-7yfwc2-8t":`Управляет исходными ответами модели в личных и групповых беседах, а также в каналах. Режим "message_tool" требует message(action=send) для обычных ответов ассистента и стандартных медиафайлов от инструментов; вывод среды выполнения, явно принадлежащий хосту, по-прежнему может доставляться, за исключением фоновых событий комнаты. Режим "automatic" публикует обычные ответы, как прежде.`}},meta:{label:{"v1-1xpfxac-m":`Метаданные совместимости`},help:{"v1-1owqhgn-2w":`Метаданные совместимости, доступные для чтения старыми версиями программы, чтобы они могли отклонять небезопасный перевод конфигурации на более старую версию.`}},"meta%2ElastTouchedVersion":{label:{"v1-m6hgn7-r":`Версия последнего изменения конфигурации`},help:{"v1-qykpv1-1i":`Версия OpenClaw, которая последней записала эту конфигурацию.`}},"meta%2Emigrations":{label:{"v1-1yu19k0-o":`Маркеры миграции конфигурации`},help:{"v1-burt8q-1q":`Ограниченный набор маркеров совместимости для завершённых миграций конфигурации.`}},"meta%2Emigrations%2EmodelPolicyAllowlist":{label:{"v1-1yjkbc1-w":`Миграция списка разрешённых моделей в политике`},help:{"v1-5psop1-1z":`Фиксирует, что ограничения устаревшей карты моделей были сохранены или проверены.`}},"meta%2Emigrations%2EutilityModelSeparation":{label:{"v1-qvzwo6-y":`Миграция для раздельного выбора вспомогательной модели`},help:{"v1-vzdfqx-2t":`Фиксирует, что прежние неявно заданные основные модели были сохранены перед выделением выбора вспомогательной модели в отдельную настройку.`}},models:{label:{"v1-hzmwb-6":`Модели`},help:{"v1-1h1niol-5q":`Корневой раздел каталога моделей для определений провайдеров, настройки объединения или замены и необязательной интеграции обнаружения моделей Bedrock. Прежде чем полагаться на резервные маршруты в рабочей среде, убедитесь, что определения провайдеров заданы явно и проверены.`}},"models%2EcatalogRefresh":{label:{"v1-1v6rbia-l":`Обновление каталога моделей`},help:{"v1-1hess4t-40":`Управляет фоновыми обновлениями встроенного каталога моделей. Записи из удалённого источника могут обновлять метаданные моделей, но не могут изменять адреса конечных точек или заголовки провайдеров.`}},"models%2EcatalogRefresh%2Eenabled":{label:{"v1-1a5yfw3-t":`Обновление каталога моделей включено`},help:{"v1-1fogpjj-3j":`Получать обновления каталога моделей с сервера в фоновом режиме (по умолчанию: true). Установите false, чтобы отключить весь сетевой обмен с удалённым каталогом моделей.`}},"models%2EcatalogRefresh%2Eurl":{label:{"v1-1piibdj-p":`URL обновления каталога моделей`},help:{"v1-e02ai2-44":`Заменяет URL каталога моделей на адрес собственного HTTPS-зеркала (для тестирования разрешён HTTP на localhost). Изменения вступают в силу после перезапуска Gateway.`}},"models%2Emode":{label:{"v1-wl6vg8-i":`Режим каталога моделей`},help:{"v1-1ofrnsp-es":`Управляет поведением каталога провайдеров: "merge" сохраняет встроенных провайдеров и накладывает поверх них ваши пользовательские настройки, а "replace" использует только настроенных вами провайдеров. В режиме "merge" для совпадающих идентификаторов провайдеров сохраняются непустые значения baseUrl из файла models.json агента, а значения apiKey сохраняются только в том случае, если провайдер не управляется через SecretRef в текущем контексте конфигурации и профиля аутентификации; для провайдеров, управляемых через SecretRef, apiKey обновляется на основе текущих маркеров источника, а для contextWindow/maxTokens совпадающих моделей используется большее из значений в явных и неявных записях.`}},"models%2Eproviders":{label:{"v1-1y3b8o-f":`Провайдеры моделей`},help:{"v1-1y5jg0v-8p":`Словарь провайдеров с идентификаторами провайдеров в качестве ключей, содержащий настройки подключения и аутентификации, а также определения конкретных моделей. Встроенные провайдеры можно настраивать с помощью переопределений на уровне провайдера; для пользовательских провайдеров обязательны baseUrl и models. Используйте стабильные ключи провайдеров, чтобы ссылки из агентов и инструментов оставались переносимыми между средами.`}},"models%2Eproviders%2E*%2EagentRuntime":{label:{"v1-3c30on-m":`Среда выполнения провайдера моделей`},help:{"v1-1luy4fb-5o":`Необязательная низкоуровневая политика среды выполнения агента для этого провайдера. Используйте политику среды выполнения на уровне провайдера или модели вместо фиксированной среды для всего агента; если параметр не задан или имеет значение по умолчанию, OpenClaw сам выбирает среду выполнения для выбранного провайдера.`}},"models%2Eproviders%2E*%2EagentRuntime%2Eid":{label:{"v1-1myzd5c-p":`Идентификатор среды выполнения провайдера моделей`},help:{"v1-1gusd9s-69":`Идентификатор среды выполнения агента провайдера: "openclaw", "auto", зарегистрированный идентификатор среды плагина, например "codex", или поддерживаемый псевдоним бэкенда CLI, например "claude-cli". Для OpenAI с официальной конечной точкой по умолчанию используется среда Codex, если параметр не задан.`}},"models%2Eproviders%2E*%2Eapi":{label:{"v1-13lvq34-q":`Адаптер API провайдера моделей`},help:{"v1-16c28rb-57":`Выбор адаптера API провайдера, определяющего обработку совместимости запросов и ответов при вызовах моделей. Используйте адаптер, соответствующий протоколу вышестоящего провайдера, чтобы избежать несоответствия возможностей.`}},"models%2Eproviders%2E*%2EapiKey":{label:{"v1-461pfc-m":`Ключ API провайдера моделей`},help:{"v1-1p84k96-54":`Учётные данные провайдера для аутентификации по ключу API, если провайдер требует прямую аутентификацию по ключу. Используйте подстановку секретов или переменных окружения и не храните настоящие ключи в файлах конфигурации, включённых в коммиты.`}},"models%2Eproviders%2E*%2Eauth":{label:{"v1-5tjzpa-o":`Режим аутентификации провайдера моделей`},help:{"v1-1l1lwxr-5p":`Выбирает способ аутентификации у провайдера: "api-key" — по API-ключу, "token" — по токену Bearer, "oauth" — с учётными данными OAuth, "aws-sdk" — с определением учётных данных AWS. Выберите вариант в соответствии с требованиями провайдера.`}},"models%2Eproviders%2E*%2EauthHeader":{label:{"v1-1d6ejif-z":`Заголовок Authorization провайдера моделей`},help:{"v1-1gn3lt3-59":`При значении true учётные данные передаются через HTTP-заголовок Authorization, даже если возможен другой способ аутентификации. Используйте этот параметр, только если провайдер или прокси явно требует передачи Authorization.`}},"models%2Eproviders%2E*%2EbaseUrl":{label:{"v1-169qlbh-n":`Базовый URL провайдера моделей`},help:{"v1-1ku88v8-53":`Базовый URL конечной точки провайдера, используемой для обработки запросов к моделям в этой записи провайдера. Используйте конечные точки HTTPS и при необходимости задавайте URL для конкретных сред с помощью шаблонов конфигурации.`}},"models%2Eproviders%2E*%2Eheaders":{label:{"v1-6e7t45-m":`Заголовки провайдера моделей`},help:{"v1-chg59u-4x":`Статические HTTP-заголовки, добавляемые в запросы к провайдеру для маршрутизации по арендаторам, аутентификации на прокси или выполнения особых требований шлюза. Используйте их только при необходимости и храните конфиденциальные значения заголовков в секретах.`}},"models%2Eproviders%2E*%2EinjectNumCtxForOpenAICompat":{label:{"v1-3u41lp-19":`Добавление num_ctx для провайдера моделей (совместимость с OpenAI)`},help:{"v1-53rmcr-6n":"Определяет, добавляет ли OpenClaw `options.num_ctx` для провайдеров Ollama, настроенных с адаптером, совместимым с OpenAI (`openai-completions`). По умолчанию — true. Устанавливайте false, только если ваш прокси или вышестоящий сервер отклоняет неизвестные поля `options` в теле запроса."}},"models%2Eproviders%2E*%2ElocalService":{label:{"v1-gokf3z-s":`Локальная служба провайдера моделей`},help:{"v1-19zkcow-4y":`Необязательный процесс локального сервера моделей для этого провайдера, запускаемый по требованию. OpenClaw проверяет healthUrl, при необходимости запускает команду, дожидается готовности и затем отправляет запрос к модели.`}},"models%2Eproviders%2E*%2ElocalService%2Eargs":{label:{"v1-18ua8bb-12":`Аргументы локальной службы провайдера моделей`},help:{"v1-t12wib-27":`Список аргументов, передаваемых команде локального сервера моделей без подстановок командной оболочки.`}},"models%2Eproviders%2E*%2ElocalService%2Ecommand":{label:{"v1-1i9zwui-10":`Команда локальной службы провайдера моделей`},help:{"v1-1x6hz64-4j":`Абсолютный путь к исполняемому файлу процесса локального сервера моделей. Указывайте этот путь явно, чтобы запуск провайдера был предсказуемым и не зависел от поиска по PATH в командной оболочке.`}},"models%2Eproviders%2E*%2ElocalService%2Ecwd":{label:{"v1-1p16qmb-1a":`Рабочий каталог локальной службы провайдера моделей`},help:{"v1-fi3xlx-1h":`Рабочий каталог процесса локального сервера моделей.`}},"models%2Eproviders%2E*%2ElocalService%2Eenv":{label:{"v1-txm98y-14":`Окружение локальной службы провайдера моделей`},help:{"v1-1lwb9k1-3k":`Дополнительные переменные окружения для процесса локального сервера моделей. Значения, похожие на секретные данные, скрываются в снимках конфигурации.`}},"models%2Eproviders%2E*%2ElocalService%2EhealthUrl":{label:{"v1-2w1iqm-13":`URL проверки работоспособности локальной службы провайдера моделей`},help:{"v1-jv7aw-35":`URL для проверки готовности перед запросами к модели. Если не указан, OpenClaw использует baseUrl провайдера с добавлением /models.`}},"models%2Eproviders%2E*%2ElocalService%2EidleStopMs":{label:{"v1-1ktyg8x-12":`Остановка локальной службы провайдера моделей при простое`},help:{"v1-1efg054-3z":`Время в миллисекундах, в течение которого локальный сервер моделей, запущенный OpenClaw, продолжает работать после завершения последнего запроса. Установите 0, чтобы он работал до выхода из OpenClaw.`}},"models%2Eproviders%2E*%2ElocalService%2EreadyTimeoutMs":{label:{"v1-1hj089b-16":`Тайм-аут ожидания готовности локальной службы поставщика моделей`},help:{"v1-4gp0f0-2r":`Максимальное время ожидания успешной проверки готовности локального сервера моделей после запуска процесса, в миллисекундах.`}},"models%2Eproviders%2E*%2EmaxTokens":{label:{"v1-662xo5-p":`Максимальное количество токенов поставщика моделей`},help:{"v1-fnj50y-38":`Максимальное количество выходных токенов по умолчанию для моделей этого поставщика, если в записи модели не задан параметр maxTokens.`}},"models%2Eproviders%2E*%2Emodels":{label:{"v1-19fsoem-p":`Список моделей поставщика`},help:{"v1-1vbm0gt-63":`Объявленный список моделей поставщика, включающий идентификаторы, метаданные, параметры конкретного поставщика и необязательные сведения о совместимости и стоимости. Идентификаторы должны точно совпадать со значениями в каталоге поставщика, чтобы выбор модели и переключение на резервную модель работали корректно.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EagentRuntime":{label:{"v1-17rzml2-d":`Среда выполнения модели`},help:{"v1-1k70g2n-3g":`Необязательная низкоуровневая политика среды выполнения агента для этой модели. Политика среды выполнения модели имеет приоритет над политикой среды выполнения поставщика.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EagentRuntime%2Eid":{label:{"v1-1035lu7-g":`Идентификатор среды выполнения модели`},help:{"v1-1llzv33-42":`Идентификатор среды выполнения агента модели: "openclaw", "auto", идентификатор зарегистрированной среды исполнения плагина, например "codex", или поддерживаемый псевдоним бэкенда CLI, например "claude-cli".`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput":{label:{"v1-x3fby6-h":`Медиавход модели`},help:{"v1-wxtj8e-2x":`Необязательные метаданные о возможностях модели по обработке медиа, используемые инструментами для выбора щадящих настроек сжатия изображений по умолчанию.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage":{label:{"v1-5448tb-h":`Входные изображения модели`},help:{"v1-1nviirq-3c":`Необязательные ограничения для входных изображений этой модели, такие как максимальная длина стороны, максимальное число пикселей и предпочтительная длина стороны при сжатии.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxBytes":{label:{"v1-4chdj6-l":`Максимальный размер изображения модели в байтах`},help:{"v1-c2469j-23":`Максимальный размер закодированных данных изображения, принимаемый провайдером для этой модели.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxPixels":{label:{"v1-4hbb56-m":`Максимальное число пикселей изображения модели`},help:{"v1-9d6yqp-1u":`Максимальное число пикселей изображения, принимаемое провайдером для этой модели.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxSidePx":{label:{"v1-1otuj2k-k":`Максимальная длина стороны изображения модели`},help:{"v1-1gbci08-1y":`Максимальная ширина или высота изображения, принимаемая провайдером для этой модели.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EpreferredSidePx":{label:{"v1-1d35u85-q":`Предпочтительная длина стороны изображения модели`},help:{"v1-1u1mpcg-2x":`Предпочтительная длина стороны при изменении размера изображения для сбалансированного сжатия. Оставьте незаданной, чтобы использовать щадящее значение OpenClaw по умолчанию.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EtokenMode":{label:{"v1-1oh830x-m":`Режим учёта токенов изображений модели`},help:{"v1-1oy6z7v-1z":`Способ учёта токенов изображений у провайдера: "tile", "detail" или "provider".`}},"models%2Eproviders%2E*%2Eparams":{label:{"v1-tv1h1l-x":`Параметры выполнения провайдера моделей`},help:{"v1-464sgu-4t":`Параметры выполнения, специфичные для провайдера и обрабатываемые его плагинами. Используйте ключи, описанные в документации провайдера, и руководствуйтесь явными указаниями в ней, а не произвольными общими предположениями.`}},"models%2Eproviders%2E*%2Eregion":{label:{"v1-9wgoh5-l":`Регион провайдера моделей`},help:{"v1-yq7rxk-5h":`Необязательный регион развёртывания/API провайдера, учитываемый провайдерами с региональными конечными точками. Поддерживаемые значения см. в документации провайдера; если также задан baseUrl, он обычно имеет приоритет.`}},"models%2Eproviders%2E*%2Erequest":{label:{"v1-1yv8vnf-w":`Переопределение параметров запросов к провайдеру моделей`},help:{"v1-1lkxryk-87":`Необязательные переопределения параметров запросов к провайдеру моделей: дополнительные заголовки, переопределения аутентификации, маршрутизация через прокси, настройки клиента TLS и необязательный параметр allowPrivateNetwork для доверенных конечных точек на собственных серверах. Используйте их только в том случае, если вышестоящий сервис или маршрут через корпоративную сеть требует настройки транспортного уровня.`}},"models%2Eproviders%2E*%2Erequest%2EallowPrivateNetwork":{label:{"v1-1etevm-18":`Разрешить запросы к провайдеру моделей в частной сети`},help:{"v1-1nbtcjk-fo":`При значении true разрешает HTTP-запросы к поставщику моделей по адресам из частных, CGNAT и аналогичных диапазонов через механизм защиты HTTP-запросов поставщика (fetchWithSsrFGuard). Для пользовательских и локальных базовых URL поставщиков уже действует доверие к точно заданному источнику, кроме источников метаданных, link-local и NAT64 для локального использования (64:ff9b:1::/48); установите false, чтобы отключить это доверие. OpenAI Responses WebSocket использует request для заголовков и TLS, но не использует этот механизм защиты запросов от SSRF. Используйте true только для самостоятельно размещённых конечных точек под контролем оператора, которым требуется доступ к частным источникам за пределами источника, заданного в baseUrl.`}},"models%2Eproviders%2E*%2Erequest%2Eauth":{label:{"v1-uw1fmg-10":`Переопределение аутентификации запросов к поставщику моделей`},help:{"v1-ucdgnf-1w":`Переопределяет параметры аутентификации запросов для этого поставщика.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2EheaderName":{label:{"v1-1jwzygk-13":`Имя заголовка аутентификации запросов к поставщику моделей`},help:{"v1-1881nqr-1i":`Пользовательское имя заголовка аутентификации, используемое в режиме header.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Emode":{label:{"v1-1prff17-w":`Режим аутентификации запросов к поставщику моделей`},help:{"v1-1lhv8hs-24":`Режим переопределения аутентификации: "provider-default", "authorization-bearer" или "header".`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Eprefix":{label:{"v1-1fxbu5n-15":`Префикс заголовка аутентификации запросов к поставщику моделей`},help:{"v1-1rbm9lz-21":`Необязательный префикс, добавляемый перед request.auth.value в режиме аутентификации header.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Etoken":{label:{"v1-31rmhm-z":`Bearer-токен запросов к поставщику моделей`},help:{"v1-6rcasw-1l":`Токен Bearer, используемый в режиме аутентификации authorization-bearer.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Evalue":{label:{"v1-gx2woc-14":`Значение заголовка аутентификации запросов к поставщику моделей`},help:{"v1-1v69ej-1j":`Пользовательское значение заголовка аутентификации, используемое в режиме аутентификации header.`}},"models%2Eproviders%2E*%2Erequest%2Eheaders":{label:{"v1-72ia6g-u":`Заголовки запросов к поставщику моделей`},help:{"v1-zj3orj-2i":`Дополнительные заголовки, добавляемые в запросы к поставщику после определения стандартных данных атрибуции и аутентификации.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy":{label:{"v1-1drhe6m-s":`Прокси для запросов к поставщику моделей`},help:{"v1-md5uj8-4j":`Необязательное переопределение прокси для запросов к поставщику моделей. Используйте "env-proxy", чтобы учитывать настройки прокси из окружения, или "explicit-proxy", чтобы направлять запросы через прокси с указанным URL.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Emode":{label:{"v1-2ea1ht-x":`Режим прокси для запросов к поставщику моделей`},help:{"v1-1dx0ozg-29":`Режим переопределения прокси для запросов к поставщику моделей: "env-proxy" или "explicit-proxy".`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls":{label:{"v1-y7ygtf-w":`TLS прокси для запросов к поставщику моделей`},help:{"v1-rdx62w-1v":`Необязательные настройки TLS, используемые при подключении к настроенному прокси.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Eca":{label:{"v1-xp5zz1-z":`Центр сертификации TLS прокси для запросов к поставщику моделей`},help:{"v1-11pg2fd-1s":`Пользовательский набор сертификатов центров сертификации для проверки цепочки TLS-сертификатов прокси.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Ecert":{label:{"v1-1p0kbsn-11":`TLS-сертификат прокси для запросов к поставщику моделей`},help:{"v1-x8nk2q-22":`Клиентский TLS-сертификат, предъявляемый прокси при необходимости взаимной TLS-аутентификации.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2EinsecureSkipVerify":{label:{"v1-1gmlhnv-18":`Пропуск проверки TLS-сертификата прокси для запросов к поставщику моделей`},help:{"v1-12vjdm9-2j":`Отключает проверку TLS-сертификата прокси. Используйте только в контролируемых средах разработки.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Ekey":{label:{"v1-1rjms34-10":`TLS-ключ прокси для запросов к поставщику моделей`},help:{"v1-1skyr56-1w":`Закрытый ключ, соответствующий request.proxy.tls.cert, для взаимной TLS-аутентификации с прокси.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Epassphrase":{label:{"v1-xwzjbl-17":`Парольная фраза TLS-ключа прокси для запросов к поставщику моделей`},help:{"v1-wjvoxd-1m":`Необязательная парольная фраза для расшифровки request.proxy.tls.key.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2EserverName":{label:{"v1-9wzzxd-18":`Имя TLS-сервера прокси для запросов к поставщику моделей`},help:{"v1-b4oabu-22":`Необязательное переопределение SNI/имени сервера при установлении TLS-соединения с прокси.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Eurl":{label:{"v1-1r3x1tf-w":`URL прокси для запросов к поставщику моделей`},help:{"v1-kvbgou-48":`Явно заданный URL прокси, используемый, когда request.proxy.mode имеет значение explicit-proxy. Учётные данные в URL считаются конфиденциальными и скрываются в снимках.`}},"models%2Eproviders%2E*%2Erequest%2Etls":{label:{"v1-1xtk31n-q":`TLS для запросов к поставщику моделей`},help:{"v1-16u7v7h-2b":`Необязательные настройки TLS для прямого подключения к конечной точке модели у провайдера.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Eca":{label:{"v1-oselmd-t":`Центры сертификации TLS для запросов к провайдеру моделей`},help:{"v1-ny8y3e-1v":`Пользовательский набор сертификатов центров сертификации для проверки цепочки TLS-сертификатов сервера провайдера.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Ecert":{label:{"v1-trr9e7-v":`TLS-сертификат для запросов к провайдеру моделей`},help:{"v1-1lltmhw-2e":`Клиентский TLS-сертификат, предъявляемый конечной точке провайдера, когда требуется взаимная TLS-аутентификация.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2EinsecureSkipVerify":{label:{"v1-1dmxiab-12":`Пропуск проверки TLS для запросов к провайдеру моделей`},help:{"v1-1006cuy-2m":`Отключает проверку TLS-сертификата сервера провайдера. Используйте только в контролируемых средах разработки.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Ekey":{label:{"v1-13sjm0o-u":`Ключ TLS для запросов к провайдеру моделей`},help:{"v1-w2agir-1t":`Закрытый ключ, соответствующий request.tls.cert, для взаимной TLS-аутентификации с сервером провайдера.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Epassphrase":{label:{"v1-19c5oux-11":`Парольная фраза TLS для запросов к провайдеру моделей`},help:{"v1-10ds42f-1g":`Необязательная парольная фраза для расшифровки request.tls.key.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2EserverName":{label:{"v1-oe4b49-12":`Имя сервера TLS для запросов к провайдеру моделей`},help:{"v1-18yt7x9-1y":`Необязательное переопределение SNI/имени сервера при установлении TLS-соединения с сервером провайдера.`}},"models%2Eproviders%2E*%2EtimeoutSeconds":{label:{"v1-itszd1-u":`Время ожидания запроса к провайдеру моделей`},help:{"v1-t3yn8l-ih":`Необязательный тайм-аут запросов к моделям конкретного провайдера в секундах. Настройки запросов на уровне провайдера влияют на явно заданные записи моделей этого провайдера; они не создают неявных моделей. Для пользовательских провайдеров задавайте этот параметр вместе с baseUrl и models провайдера. Применяется к HTTP-запросам провайдера, включая подключение, получение заголовков и тела ответа, а также прерывание запроса по общему тайм-ауту. Кроме того, повышает для этого провайдера предельное время ожидания при отсутствии активности или потоковых данных LLM сверх неявного значения по умолчанию (~120 с). Используйте этот параметр для медленных локальных серверов моделей или серверов на собственной инфраструктуре, а также для облачных провайдеров, которые буферизуют токены рассуждений, не передавая данные по сети (Gemini preview, Claude/Opus с большими объёмами данных инструментов), вместо изменения глобальных тайм-аутов агента.`}},nodeHost:{label:{"v1-nb8lk1-9":`Хост узла`},help:{"v1-8recuz-4z":`Настройки хоста узла для функций, предоставляемых этим узлом Gateway другим узлам или клиентам. Сохраняйте значения по умолчанию, если не планируете проксировать локальные возможности в своей сети узлов.`}},"nodeHost%2EagentRuns":{label:{"v1-s71x8m-f":`Запуски агента на узле`},help:{"v1-4uz5ur-2k":`Разрешает выполнение нативных ходов агента с обязательным одобрением на этом хосте узла без графического интерфейса. По умолчанию отключено.`}},"nodeHost%2EagentRuns%2Eclaude":{label:{"v1-10xgkda-m":`Запуски агента Claude на узле`},help:{"v1-g8az5y-2l":`Определяет, может ли этот хост узла без графического интерфейса сообщать Gateway о возможности выполнения ходов агента через Claude CLI.`}},"nodeHost%2EagentRuns%2Eclaude%2Eenabled":{label:{"v1-15o3u53-u":`Запуски агента Claude на узле включены`},help:{"v1-1ke804l-44":`Сообщать о возможности продолжения сеанса Claude на сопряжённом узле, если доступен локальный исполняемый файл claude (по умолчанию: false). Для запусков по-прежнему требуется одобрение выполнения команд на узле.`}},"nodeHost%2EautoUpdate":{label:{"v1-fmh4qs-m":`Автоматические обновления узла`},help:{"v1-16xjk4e-5n":`Управляет автоматическими обновлениями отдельной среды выполнения для хостов узлов, поставляемых в виде пакетов и работающих без графического интерфейса. Проверяет обновления каждый час и перед перезапуском ожидает завершения всей работы узла; интервал между автоматическими перезапусками составляет не менее 12 часов.`}},"nodeHost%2EautoUpdate%2Eenabled":{label:{"v1-89maql-u":`Автоматические обновления узла включены`},help:{"v1-1sa0yeg-7w":`Включает автоматические обновления из каналов stable или beta для длительно работающих узлов, поставляемых в виде пакетов и работающих без графического интерфейса (по умолчанию: true). Чтобы отключить, установите false. Также отключается при update.checkOnStart=false или OPENCLAW_NO_AUTO_UPDATE=1; для рабочих копий исходного кода, нативных приложений, частных рабочих процессов и каналов dev и extended-stable обновления автоматически не применяются.`}},"nodeHost%2EbrowserProxy":{label:{"v1-1bm9i0h-i":`Браузерный прокси узла`},help:{"v1-2xrew7-4f":`Группирует настройки браузерного прокси для предоставления доступа к управлению локальным браузером через маршрутизацию узла. Включайте только тогда, когда удалённым рабочим процессам узла нужны ваши локальные профили браузера.`}},"nodeHost%2EbrowserProxy%2EallowProfiles":{label:{"v1-cq2v55-z":`Разрешённые профили браузерного прокси узла`},help:{"v1-1ew5dkm-8b":`Необязательный список разрешённых имён профилей браузера, доступных через прокси-маршрутизацию узла. Оставьте пустым, чтобы сохранить полный доступ к профилям по умолчанию, включая маршруты создания и удаления профилей. Если список задан, OpenClaw ограничивает доступ к профилям по принципу минимальных привилегий и блокирует создание и удаление постоянных профилей через прокси.`}},"nodeHost%2EbrowserProxy%2Eenabled":{label:{"v1-1dlbo60-q":`Браузерный прокси узла включён`},help:{"v1-pa04pd-5b":`Предоставляет доступ к локальному серверу управления браузером через прокси-маршрутизацию узла, чтобы удалённые клиенты могли использовать возможности браузера этого хоста. Оставьте отключённым, если удалённая автоматизация явно этого не требует.`}},"nodeHost%2Emcp":{label:{"v1-4hkwkx-d":`MCP хоста узла`},help:{"v1-1mdhrwl-48":`Используйте серверы MCP, запущенные хостом узла без графического интерфейса и опубликованные в связанном с ним Gateway, как инструменты агента. После изменения этого раздела перезапустите хост узла.`}},"nodeHost%2Emcp%2Eservers":{label:{"v1-6lpscp-l":`Серверы MCP хоста узла`},help:{"v1-19m002f-3x":`Именованные определения серверов MCP, локальных для этого узла. Используется та же структура сервера, что и в mcp.servers; хост узла не поддерживает серверы OAuth.`}},"nodeHost%2Eskills":{label:{"v1-1n58xs9-g":`Skills хоста узла`},help:{"v1-v8txza-41":`Используйте этот раздел для публикации навыков, установленных в ~/.openclaw/skills, с хоста узла без графического интерфейса. После изменения файлов навыков перезапустите хост узла.`}},"nodeHost%2Eskills%2Eenabled":{label:{"v1-uf23u8-o":`Skills хоста узла включены`},help:{"v1-1ggpkqb-36":`Обнаруживать и публиковать навыки, размещённые на узле, после подключения (по умолчанию: true). Установите false, чтобы отключить публикацию навыков узла.`}},"nodeHost%2EworkerRuns":{label:{"v1-1aab8yp-g":`Запуски рабочих процессов на узле`},help:{"v1-1w83rox-2p":`Включить полноценное размещение рабочих сеансов OpenClaw из пакетов, управляемых Gateway. По умолчанию отключено.`}},"nodeHost%2EworkerRuns%2Ecapacity":{label:{"v1-1tquo3g-o":`Лимит рабочих сеансов узла`},help:{"v1-10nvk8f-3w":`Максимальное число одновременных рабочих сеансов, размещаемых на этом узле (по умолчанию: число доступных ядер CPU). Допустимо целое число от 1 до 1024.`}},"nodeHost%2EworkerRuns%2EcontainerImage":{label:{"v1-1fujssi-v":`Образ контейнера для рабочих процессов узла`},help:{"v1-1oqx50o-5t":`Необязательный образ Node 24.16+ или 26.1+ для рабочих процессов, изолированных в контейнерах (по умолчанию: "node:24.19.0-slim"). При необходимости используйте образ, закреплённый по дайджесту, образ из частного реестра или предварительно загруженный образ; отсутствующие образы загружаются при первом использовании.`}},"nodeHost%2EworkerRuns%2Eenabled":{label:{"v1-t3la2w-o":`Рабочие процессы на узле включены`},help:{"v1-b3t0xp-2t":`Разрешить этому сопряжённому узлу размещать сеансы только из тех самых пакетов, которые установлены его Gateway (по умолчанию: false).`}},"nodeHost%2EworkerRuns%2Eisolation":{label:{"v1-1qqd8iw-p":`Изоляция рабочих процессов узла`},help:{"v1-19i6swo-58":`Выберите границу изоляции процессов рабочих сеансов: "none" — выполнение непосредственно на хосте узла (по умолчанию); "container" — требуется работающий движок, совместимый с Docker, без возможности перехода к выполнению на хосте.`}},plugins:{label:{"v1-10renyj-7":`Плагины`},help:{"v1-1qbev2k-5c":`Настройки системы плагинов для включения расширений, ограничения области загрузки, настройки записей и отслеживания установок. В производственных средах явно задавайте политику плагинов и соблюдайте принцип минимальных привилегий.`}},"plugins%2Eallow":{label:{"v1-19jw4yj-g":`Список разрешённых плагинов`},help:{"v1-pupwbe-7z":`Необязательный список идентификаторов разрешённых плагинов. Если он задан, загружаться могут только плагины из списка. Настроенные встроенные каналы чата по-прежнему могут активировать свой встроенный плагин, если канал явно включён в конфигурации. Используйте этот список, чтобы разрешить только утверждённый набор расширений в контролируемых средах.`}},"plugins%2Edeny":{label:{"v1-arkuus-f":`Список запрещённых плагинов`},help:{"v1-4gyt4z-4i":`Необязательный список идентификаторов плагинов, которые блокируются, даже если они включены в списки разрешённых или указаны в путях. Используйте правила запрета для экстренного отката и безусловной блокировки потенциально опасных плагинов.`}},"plugins%2Eenabled":{label:{"v1-461fte-e":`Включить плагины`},help:{"v1-pnygd7-50":`Глобальное включение или отключение загрузки плагинов и расширений при запуске и перезагрузке конфигурации (по умолчанию: true). Оставляйте включённым, только если в вашем развёртывании нужны возможности расширений.`}},"plugins%2Eentries":{label:{"v1-1q3x0gu-e":`Записи плагинов`},help:{"v1-cn74rf-54":`Настройки отдельных плагинов, сгруппированные по идентификатору плагина, включая состояние включения и конфигурацию выполнения, специфичную для плагина. Используйте их для точечной настройки плагинов без изменения глобальной политики загрузки.`}},"plugins%2Eentries%2E*%2EapiKey":{label:{"v1-1c5cpg5-e":`Ключ API плагина`},help:{"v1-ctytg2-53":`Необязательное поле ключа API для плагинов, поддерживающих прямое указание ключа в настройках записи. Используйте подстановку секретов или переменных окружения и не сохраняйте реальные учётные данные в файлах конфигурации.`}},"plugins%2Eentries%2E*%2Econfig":{label:{"v1-1i42kk8-d":`Конфигурация плагина`},help:{"v1-1he672p-51":`Конфигурационные данные, определяемые плагином и обрабатываемые по его собственной схеме и правилам проверки. Используйте только поля, указанные в документации плагина, чтобы избежать игнорируемых или недопустимых настроек.`}},"plugins%2Eentries%2E*%2Eenabled":{label:{"v1-87au17-e":`Плагин включён`},help:{"v1-12soc0h-9a":`Переопределение состояния включения для отдельного плагина, применяемое поверх глобальной политики плагинов. В стандартном гибридном режиме перезагрузки изменения обновляют среду выполнения плагина для новых ходов агента без перезапуска Gateway, если только плагин не требует перезапуска при изменении этого параметра. Используйте это для постепенного внедрения плагина в разных средах.`}},"plugins%2Eentries%2E*%2Eenv":{label:{"v1-1vsubm6-s":`Переменные окружения плагина`},help:{"v1-p39pu4-52":`Набор переменных окружения для отдельного плагина, добавляемых только в его среду выполнения. Используйте это, чтобы ограничить доступ к учётным данным провайдера одним плагином, а не передавать их через глобальное окружение процесса.`}},"plugins%2Eentries%2E*%2Ehooks":{label:{"v1-1miceel-i":`Политика хуков плагина`},help:{"v1-1oslnrf-4c":`Настройки политики типизированных хуков отдельного плагина для ограничений безопасности, обеспечиваемых ядром. Используйте их, чтобы ограничить категории хуков с существенным влиянием на работу системы, не отключая плагин целиком.`}},"plugins%2Eentries%2E*%2Ehooks%2EallowConversationAccess":{label:{"v1-ckd9n5-v":`Разрешить хуки доступа к переписке`},help:{"v1-xqz31z-7e":"Определяет, может ли этот плагин читать исходное содержимое переписки через типизированные хуки, такие как `before_agent_run`, `before_model_resolve`, `before_agent_reply`, `llm_input`, `llm_output`, `before_agent_finalize` и `agent_end`. Для плагинов, не входящих в комплект поставки, требуется явное разрешение."}},"plugins%2Eentries%2E*%2Ehooks%2EallowPromptInjection":{label:{"v1-1p7f9k9-s":`Разрешить хуки внедрения в промпт`},help:{"v1-7y6cny-32":"Определяет, может ли этот плагин изменять промпты через типизированные хуки. Установите false, чтобы заблокировать `before_prompt_build`."}},"plugins%2Eentries%2E*%2Ehooks%2EtimeoutMs":{label:{"v1-zg658l-o":`Тайм-аут хуков плагина (мс)`},help:{"v1-4ra6b7-74":`Тайм-аут по умолчанию в миллисекундах для типизированных хуков этого плагина, не более 600000. Если значение не задано, каждый хук использует тайм-аут, объявленный плагином, или политику Gateway для этого хука; единого фиксированного значения по умолчанию нет. Значения для отдельных хуков в hooks.timeouts имеют приоритет.`}},"plugins%2Eentries%2E*%2Ehooks%2Etimeouts":{label:{"v1-1k80g2z-t":`Индивидуальные тайм-ауты хуков плагина`},help:{"v1-yphl9b-5s":`Индивидуальные тайм-ауты в миллисекундах для отдельных хуков, указанные по имени типизированного хука, не более 600000. Задавайте отдельные значения для заведомо медленных хуков, таких как before_prompt_build или agent_end, вместо увеличения тайм-аутов всех хуков.`}},"plugins%2Eentries%2E*%2Ellm":{label:{"v1-tnwzbh-h":`Политика LLM плагина`},help:{"v1-dlca6c-4j":`Настройки api.runtime.llm.complete для отдельного плагина, определяющие разрешения на переопределение модели и агента. Не задавайте их, если плагину не требуется явно управлять вызовами генерации, выполняемыми хостом.`}},"plugins%2Eentries%2E*%2Ellm%2EallowAgentIdOverride":{label:{"v1-14o9l6p-v":`Разрешить плагину переопределять агента LLM`},help:{"v1-k8c08b-4n":`Явно разрешает этому плагину вызывать api.runtime.llm.complete с идентификатором агента, отличным от заданного по умолчанию. Оставьте false, если плагину не доверен доступ к моделям других агентов.`}},"plugins%2Eentries%2E*%2Ellm%2EallowAuthProfileOverride":{label:{"v1-8zsq4z-12":`Разрешить плагину переопределять профиль аутентификации LLM`},help:{"v1-9ityw9-4x":`Разрешает этому плагину выбирать профиль аутентификации, отличный от заданного по умолчанию, для генерации в изолированной среде выполнения агента. Оставьте false, если плагину не доверена явная маршрутизация изолированных учётных данных.`}},"plugins%2Eentries%2E*%2Ellm%2EallowedCompletionModels":{label:{"v1-13e4e1t-10":`Разрешённые модели генерации LLM для плагина`},help:{"v1-1ul08he-54":`Разрешённые модели для каждого запроса плагина к LLM в виде канонических ссылок "provider/model", включая значения по умолчанию, определяемые хостом, и переопределения. Используйте "*", только если намеренно разрешаете любую модель.`}},"plugins%2Eentries%2E*%2Ellm%2EallowedModels":{label:{"v1-1vuyyz9-p":`Разрешённые модели LLM для плагина`},help:{"v1-154sk45-47":`Разрешённые модели для переопределения в доверенных вызовах LLM из плагина в виде канонических ссылок "provider/model". Используйте "*", только если намеренно разрешаете переопределение на любую модель.`}},"plugins%2Eentries%2E*%2Ellm%2EallowModelOverride":{label:{"v1-1wtocu9-v":`Разрешить плагину переопределять модель LLM`},help:{"v1-uw4jmc-47":`Явно разрешает этому плагину запрашивать переопределение модели в api.runtime.llm.complete. Оставьте false, если плагину не доверено управлять выбором модели.`}},"plugins%2Eentries%2E*%2Esubagent":{label:{"v1-1dea8kh-m":`Политика субагентов плагина`},help:{"v1-wbf4m1-4d":`Настройки среды выполнения субагентов для отдельного плагина: доверие к переопределению модели и списки разрешённых моделей. Оставьте параметр незаданным, если плагину не требуется явно управлять выбором модели субагента.`}},"plugins%2Eentries%2E*%2Esubagent%2EallowedModels":{label:{"v1-1axw70h-u":`Разрешённые модели субагентов плагина`},help:{"v1-2pvkow-42":`Разрешённые модели для переопределения при доверенных запусках субагентов плагина в виде канонических ссылок "provider/model". Используйте "*", только если намеренно разрешаете любую модель.`}},"plugins%2Eentries%2E*%2Esubagent%2EallowModelOverride":{label:{"v1-1wes28b-10":`Разрешить плагину переопределять модель субагента`},help:{"v1-1r5tzm1-4g":`Явно разрешает этому плагину запрашивать переопределение провайдера и модели при фоновых запусках субагентов. Оставьте false, если плагину не доверено управлять выбором модели.`}},"plugins%2Eload":{label:{"v1-9stn89-d":`Загрузчик плагинов`},help:{"v1-1myjwbi-52":`Группа настроек загрузчика плагинов для указания путей файловой системы, в которых выполняется поиск плагинов. Указывайте пути загрузки явно и проверяйте их, чтобы избежать случайной загрузки недоверенных расширений.`}},"plugins%2Eload%2Epaths":{label:{"v1-nk4cri-h":`Пути загрузки плагинов`},help:{"v1-o689p1-4z":`Дополнительные файлы или каталоги плагинов, которые загрузчик сканирует помимо стандартных встроенных расположений. Используйте отдельные каталоги для расширений и избегайте слишком общих путей с посторонним исполняемым содержимым.`}},"plugins%2Eslots":{label:{"v1-oamycb-c":`Слоты плагинов`},help:{"v1-zx6crl-5f":`Определяет, какие плагины занимают эксклюзивные слоты среды выполнения, например слот памяти, чтобы каждую такую функцию предоставлял только один плагин. Явно назначайте плагины слотам, чтобы избежать пересечения поставщиков функций с конфликтующим поведением.`}},"plugins%2Eslots%2EcontextEngine":{label:{"v1-1371nb9-l":`Плагин движка контекста`},help:{"v1-4v13iw-2t":`Выбирает активный плагин движка контекста по идентификатору, чтобы оркестрацию контекста обеспечивал один плагин.`}},"plugins%2Eslots%2Ememory":{label:{"v1-1948lbp-d":`Плагин памяти`},help:{"v1-80ngcl-23":`Выберите активный плагин памяти по идентификатору или укажите "none", чтобы отключить плагины памяти.`}},presence:{label:{"v1-10fdwo4-8":`Присутствие`}},proxy:{label:{"v1-ji57pa-d":`Управляемый прокси`},help:{"v1-vui6bx-58":`Маршрутизация исходящего трафика среды выполнения OpenClaw через прямой прокси, управляемый оператором: HTTP, HTTPS, WebSocket и поддерживаемые низкоуровневые исходящие соединения. Используйте, если централизованный контроль исходящего трафика входит в периметр развёртывания.`}},"proxy%2Eenabled":{label:{"v1-8i199z-l":`Управляемый прокси включён`},help:{"v1-1456xdw-49":`Явное переопределение режима управляемого прокси. Наличие URL по умолчанию включает маршрутизацию; установите false, чтобы игнорировать URL прокси из конфигурации или переменных окружения, не удаляя их.`}},"proxy%2EloopbackMode":{label:{"v1-1y356w6-r":`Режим loopback для управляемого прокси`},help:{"v1-1kaiuh0-3c":`Управляет маршрутизацией трафика контура управления Gateway через loopback, когда активен режим управляемого прокси: "gateway-only", "proxy" или "block".`}},"proxy%2EproxyUrl":{label:{"v1-b5s3c3-h":`URL управляемого прокси`},help:{"v1-p36b5l-3v":`URL управляемого прямого прокси. Используйте http:// для обычного CONNECT-прокси или https://, если само соединение с прокси должно использовать TLS.`}},"proxy%2Etls":{label:{"v1-qr3npv-h":`TLS управляемого прокси`},help:{"v1-6i0vu-3q":`Настройки TLS для подключения к управляемому прокси. Эти настройки применяются к TLS-соединению с прокси, а не к TLS-соединению с целевым сервером после CONNECT.`}},"proxy%2Etls%2EcaFile":{label:{"v1-1mel3ux-p":`Файл CA для TLS управляемого прокси`},help:{"v1-1ntzjia-2p":`Путь в файловой системе к пользовательскому набору сертификатов CA для проверки сертификата управляемого HTTPS-прокси.`}},secrets:{label:{"v1-1sihgpy-7":`Секреты`},help:{"v1-jgn0o9-2l":`Провайдеры ссылок на секреты, поведение общего хранилища и необязательная защита исходящего трафика подпроцессов.`}},"secrets%2EegressProxy":{label:{"v1-ni0kq4-j":`Прокси исходящего трафика для секретов`},help:{"v1-1qfgid-4n":`Loopback-прокси под управлением Gateway, который заменяет маркеры секретов из общего хранилища только в момент отправки исходящего запроса. После изменения этого раздела перезапустите Gateway: его настройки применяются при запуске.`}},"secrets%2EegressProxy%2EallowedHosts":{label:{"v1-1jt4jwf-x":`Разрешённые хосты прокси исходящего трафика для секретов`},help:{"v1-9ypodl-6t":`Необязательный список разрешённых адресатов для запросов и туннелей CONNECT. Если он задан, адресаты должны быть указаны в этом списке, в привязке хоста для отдельного секрета или в bypassHosts. Пустой список разрешает только привязанные хосты или хосты из bypassHosts. После изменения перезапустите Gateway.`}},"secrets%2EegressProxy%2EbypassHosts":{label:{"v1-1keo1yv-w":`Хосты обхода исходящего прокси для секретов`},help:{"v1-1oiiomv-57":`Точные имена хостов, использующих туннели CONNECT с аутентификацией без расшифровки трафика для клиентов с закреплением сертификатов. Маркеры-заглушки остаются зашифрованными и приводят к отказу аутентификации у поставщика, а не к раскрытию открытого текста.`}},"secrets%2EegressProxy%2Eenabled":{label:{"v1-ugzvlx-r":`Исходящий прокси для секретов включён`},help:{"v1-u99b1i-2h":`Включает подстановку секретов в исходящий трафик для подпроцессов агента, запущенных в Gateway. По умолчанию: false.`}},session:{label:{"v1-8yh9jr-7":`Сеанс`},help:{"v1-j86s32-5d":`Глобальные настройки маршрутизации и сброса сессий, политики доставки и обслуживания истории переписки. Сохраняйте значения по умолчанию, если вам не нужны более строгие ограничения изоляции, хранения или доставки.`}},"session%2EdmScope":{label:{"v1-ukjin6-g":`Область сессий личных сообщений`},help:{"v1-ql362c-5l":`Область сессий личных сообщений: "main" сохраняет непрерывность, а "per-peer", "per-channel-peer" и "per-account-channel-peer" усиливают изоляцию. Используйте изолированные режимы для общих входящих сообщений или развёртываний с несколькими учётными записями.`}},"session%2EgroupScope":{label:{"v1-7kncqs-j":`Область групповых сессий`},help:{"v1-1fdezx2-6i":`Область сессий групп и каналов: "per-group" разделяет комнаты, а основная сессия агента наблюдает за ними в фоновом режиме независимо от dmScope; "main" объединяет контекст комнат в основной сессии и не требует наблюдения. Используйте "main" только для доверенных комнат.`}},"session%2EidentityLinks":{label:{"v1-b28nnm-m":`Связи идентификаторов в сессиях`},help:{"v1-1y5jnsm-5n":`Сопоставляет канонические идентификаторы с идентификаторами собеседников с префиксом провайдера, чтобы один и тот же пользователь определялся как участник одной переписки (пример: telegram:123456). Используйте, когда один человек взаимодействует через несколько каналов или учётных записей.`}},"session%2EmainKey":{label:{"v1-r57g0n-g":`Ключ основной сессии`},help:{"v1-18p638h-3q":`Принимается, но игнорируется: суффикс основной сессии каждого агента всегда равен "main". Не указывайте это поле; для глобальной области сессий вместо него используется "global".`}},"session%2Emaintenance":{label:{"v1-p1iywg-j":`Обслуживание сессий`},help:{"v1-imr441-66":`Настройки автоматического обслуживания хранилища сессий: архивирование сессий панели управления, удаление по сроку давности, ограничение числа записей, срок хранения архивов после сброса и очистка по лимиту дискового пространства. Начните с режима warn, чтобы оценить влияние, а после настройки порогов перейдите в режим enforce.`}},"session%2Emaintenance%2EarchiveDashboardAfter":{label:{"v1-1ok5zsl-15":`Срок неактивности до архивирования сессий панели управления`},help:{"v1-1frdtub-5n":"Архивирует неактивные сессии панели управления по истечении указанного срока (например, `7d`), чтобы они оставались доступными, не перегружая список активных сессий. Установите `false` или `0`, чтобы отключить автоматическое архивирование сессий панели управления."}},"session%2Emaintenance%2EcoldStorage":{label:{"v1-353bpe-n":`Холодное хранилище расшифровок`},help:{"v1-1kp9s9h-5s":`Перемещает неактивные расшифровки в сжатые архивы JSONL, сохраняя метаданные сеансов. Файлы архивов становятся обязательной частью истории и должны включаться в резервные копии. Изменения применяются без перезапуска Gateway.`}},"session%2Emaintenance%2EcoldStorage%2EafterDays":{label:{"v1-1ay0en7-r":`Архивировать после указанного числа дней неактивности`},help:{"v1-zay1q3-5b":`Архивировать расшифровки после указанного числа дней неактивности (положительное целое число, по умолчанию 30). Активная работа защищена; изменение порога вступает в силу при следующем проходе фонового обработчика без перезапуска Gateway.`}},"session%2Emaintenance%2EcoldStorage%2Eenabled":{label:{"v1-85gcoy-11":`Автоматически архивировать старые расшифровки`},help:{"v1-6p6vmb-5a":`Включает фоновое архивирование записей диалогов (по умолчанию false). Фоновый обработчик каждую минуту проверяет наличие записей, подходящих для архивирования. Эта явно заданная политика архивирования не связана с удалением и очисткой для соблюдения лимита дискового пространства.`}},"session%2Emaintenance%2EhighWaterBytes":{label:{"v1-1t9qv0z-u":`Целевой объём сессий на диске после очистки`},help:{"v1-143vh09-7z":`Целевой объём после очистки по лимиту дискового пространства (верхний порог). По умолчанию составляет 80% от maxDiskBytes; задайте явно для более строгого освобождения места на дисках с ограниченным объёмом. Если значение вычисляется как ноль, используется значение по умолчанию; отрицательные значения недопустимы. Для отключения лимита используйте maxDiskBytes.`}},"session%2Emaintenance%2EmaxDiskBytes":{label:{"v1-14omfzj-n":`Максимальный объём дискового пространства для сессий`},help:{"v1-147lxk3-cj":'Лимит фактического использования диска для каждого агента, включающий основной файл SQLite, WAL и учитываемые артефакты каталога сессий (например, `500mb`). По умолчанию — `10gb`; из-за защищённых данных использование диска может оставаться выше целевого уровня. При превышении лимита режим warn сообщает о нехватке места, а режим enforce удаляет сначала старые артефакты сброса и удаления, затем историю без ссылок на неё, а потом архивы, созданные при достижении лимита. Архивы, созданные вручную, по сроку хранения, через панель управления, при восстановлении или прежними версиями, остаются защищёнными. Укажите `false`, `0` или `"0"`, чтобы отключить.'}},"session%2Emaintenance%2EmaxEntries":{label:{"v1-1n4txc9-j":`Максимальное число записей сессий`},help:{"v1-1w2egrh-7u":`Ограничивает число неархивированных записей сессий (по умолчанию — 5000). Подходящие для архивации сохраняемые диалоги сверх лимита архивируются вместе с историей; одноразовые записи автоматизации удаляются. Существующие архивы не учитываются в лимите. Защищённые активные записи по-прежнему учитываются, поэтому число записей в хранилище может оставаться выше лимита.`}},"session%2Emaintenance%2Emode":{label:{"v1-fudr6r-o":`Режим обслуживания сессий`},help:{"v1-bq39hk-6v":`Определяет, будут ли политики удаления старых данных и ограничения дискового пространства только выдавать предупреждения ("warn") или применяться на практике ("enforce"). На этапе внедрения оставьте "warn" и переключитесь на "enforce" после проверки безопасности пороговых значений. Для холодного хранилища предусмотрен отдельный явный параметр enabled.`}},"session%2Emaintenance%2EpreserveRecent":{label:{"v1-i6rkx1-o":`Сохранять недавние сессии`},help:{"v1-138q5wx-89":"Защищает интерактивные сессии, активные в течение указанного периода (например, `7d`), от автоматического удаления истории по возрасту, количеству записей и лимиту использования диска. Если значение не задано или равно `false`, сохраняется обычный порядок удаления: сначала самые старые записи. Синтетические записи запусков моделей, cron, hook, heartbeat, ACP и субагентов по-прежнему подлежат очистке в заданных пределах."}},"session%2Emaintenance%2EpruneAfter":{label:{"v1-1hxlne1-j":`Срок до очистки сессий`},help:{"v1-1xn50w7-76":"Архивирует подходящие для архивации постоянные беседы и удаляет временные записи автоматизации старше указанного срока (по умолчанию `30d`; например, `12h`). Архивированные беседы сохраняют историю и могут быть восстановлены; защищённые беседы и беседы, доступные для маршрутизации, остаются активными."}},"session%2Emaintenance%2EresetArchiveRetention":{label:{"v1-1k23ggw-v":`Срок хранения архивов сброшенных сеансов`},help:{"v1-16amrs1-7r":"Срок хранения архивированных записей переписки (`*.reset.<timestamp>` и `*.deleted.<timestamp>`). По умолчанию архивы хранятся до достижения лимита дискового пространства, после чего удаляются начиная с самых старых. Укажите срок (например, `30d`), чтобы включить удаление по истечении фактического времени, или `false`, чтобы явно отключить его."}},"session%2EnotifyOnCreate":{label:{"v1-19qwl5t-v":`Уведомлять Home о создании сессии`},help:{"v1-c4prn5-8b":`Добавлять системное уведомление в очередь сессии Home агента-владельца при создании сессии (по умолчанию: true). Уведомления содержат доступные метаданные о названии и создателе и считываются при следующем ходе в Home или периодическом сигнале активности. Установите false, чтобы отключить; черновики, сессии инкогнито, внутренние сессии и запуски по расписанию cron исключены.`}},"session%2Ereset":{label:{"v1-oh2sxm-k":`Политика сброса сеансов`},help:{"v1-1hmt7n3-6r":`Определяет объект политики сброса по умолчанию, используемый, когда нет переопределений для конкретного типа или канала. По умолчанию сеансы не сбрасываются автоматически; для включения автоматического сброса задайте ежедневное расписание или сброс по неактивности. Команды /new и /reset доступны в любое время.`}},"session%2Ereset%2EatHour":{label:{"v1-3sjhvl-o":`Час ежедневного сброса сеансов`},help:{"v1-wry8cv-59":`Задаёт час по местному времени (0–23) для режима ежедневного сброса, чтобы сеансы сменялись в предсказуемое время. Используйте с mode=daily и учитывайте часовой пояс оператора, чтобы поведение было понятным.`}},"session%2Ereset%2EidleMinutes":{label:{"v1-yoxr77-q":`Время неактивности до сброса сеанса в минутах`},help:{"v1-1kzj0id-5e":`Задаёт период неактивности до сброса в режиме сброса по неактивности, а также может служить дополнительным условием в режиме ежедневного сброса. Используйте большие значения для сохранения непрерывности беседы или меньшие — для более частого обновления кратковременных обсуждений.`}},"session%2Ereset%2Emode":{label:{"v1-ern6ub-i":`Режим сброса сеансов`},help:{"v1-e5ie4w-5b":`Выбирает стратегию сброса: "none" отключает автоматический сброс (по умолчанию), "daily" выполняет сброс в заданный час, а "idle" — после периода бездействия. /new и /reset доступны во всех режимах.`}},"session%2EresetByChannel":{label:{"v1-xmfipi-o":`Сброс сеанса по каналам`},help:{"v1-1uxsulx-5h":`Задаёт отдельные настройки сброса для каналов по идентификатору провайдера/канала для точного управления поведением. Используйте только тогда, когда для одного канала требуется особое поведение сброса, выходящее за рамки политик по типу чата.`}},"session%2EresetByType":{label:{"v1-1pqdf9f-q":`Сброс сеанса по типу чата`},help:{"v1-ypdr7u-52":`Переопределяет поведение сброса по типу чата (direct, group, thread), если настроек по умолчанию недостаточно. Используйте, когда для групп и веток нужна иная частота сброса, чем для личных сообщений.`}},"session%2EresetByType%2Edirect":{label:{"v1-ysq32o-m":`Сброс сеанса (личный чат)`},help:{"v1-fjnlp5-56":`Определяет политику сброса для личных чатов и заменяет базовую конфигурацию session.reset для этого типа. Используйте как основной способ переопределения настроек для личных сообщений вместо устаревшего псевдонима dm.`}},"session%2EresetByType%2Egroup":{label:{"v1-kpfypy-l":`Сброс сеанса (группа)`},help:{"v1-hl1200-4u":`Определяет политику сброса для сеансов групповых чатов, где непрерывность общения и характер шума отличаются от личных сообщений. Для активных групп задавайте более короткие периоды бездействия, если потеря фокуса контекста становится проблемой.`}},"session%2EresetByType%2Ethread":{label:{"v1-1jznvzn-m":`Сброс сеанса (ветка)`},help:{"v1-1hgpeke-4w":`Определяет политику сброса для сеансов отдельных веток, включая работу над конкретными задачами в ветках каналов. Используйте, когда сеансы веток должны завершаться раньше или позже, чем сеансы других типов чатов.`}},"session%2EresetTriggers":{label:{"v1-k9d2el-m":`Триггеры сброса сессии`},help:{"v1-rcabsw-5a":`Список триггеров сообщений, которые принудительно сбрасывают сессию при совпадении с входящим содержимым. Используйте их только для явных фраз сброса, чтобы контекст не терялся неожиданно во время обычного разговора.`}},"session%2Escope":{label:{"v1-1j9i0l7-d":`Область действия сессии`},help:{"v1-axt4ds-5z":`Задаёт базовую стратегию группировки сессий: "per-sender" изолирует сессии по отправителю, а "global" использует одну общую сессию в контексте канала. Для более безопасной работы с несколькими пользователями оставьте "per-sender", если общий контекст не требуется намеренно.`}},"session%2EsendPolicy":{label:{"v1-1nxtvjb-j":`Политика отправки сообщений между сессиями`},help:{"v1-17qpipb-5l":`Управляет разрешениями на отправку сообщений между сессиями с помощью разрешающих и запрещающих правил, проверяемых по channel, chatType и префиксам ключей. Используйте эту настройку, чтобы ограничить места доставки сообщений инструментами сессий в сложных средах.`}},"session%2EsendPolicy%2Edefault":{label:{"v1-17hik48-y":`Действие по умолчанию для политики отправки между сессиями`},help:{"v1-15plhut-53":`Задаёт действие на случай, если ни одно правило sendPolicy не совпало: "allow" или "deny". Оставьте "allow" для простых конфигураций или выберите "deny", если для каждого получателя требуется явное разрешающее правило.`}},"session%2EsendPolicy%2Erules":{label:{"v1-uomm0w-p":`Правила политики отправки между сессиями`},help:{"v1-o217za-5h":'Упорядоченные разрешающие и запрещающие правила, проверяемые до применения действия по умолчанию, например `{ action: "deny", match: { channel: "discord" } }`. Размещайте наиболее конкретные правила первыми, чтобы общие правила не перекрывали исключения.'}},"session%2EsendPolicy%2Erules%5B%5D%2Eaction":{label:{"v1-sk8rxf-o":`Действие правила отправки между сессиями`},help:{"v1-178vm80-54":`Задаёт решение правила как "allow" или "deny", если выполнены соответствующие условия. При строгом ограничении отправки с явными разрешающими исключениями размещайте запрещающие правила первыми.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch":{label:{"v1-i5lkne-n":`Условия правила отправки в сеансе`},help:{"v1-18qh5qg-5d":`Задаёт необязательные условия применения правила, которые могут сочетать ограничения по channel, chatType и префиксу ключа. Задавайте узкие условия, чтобы назначение политики оставалось понятным, а отладка — простой.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2Echannel":{label:{"v1-dti9lk-p":`Канал правила отправки в сеансе`},help:{"v1-u5erwx-50":`Ограничивает применение правила конкретным идентификатором канала или провайдера (например, discord, telegram, slack). Используйте, когда нужно разрешить или запретить доставку в одном канале независимо от остальных.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2EchatType":{label:{"v1-dod3v9-r":`Тип чата правила отправки в сеансе`},help:{"v1-7cv4f9-4z":`Ограничивает применение правила типом чата (direct, group, thread), чтобы поведение зависело от формы общения. Используйте, когда для личных и групповых чатов нужны разные ограничения безопасности.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2EkeyPrefix":{label:{"v1-145jj50-s":`Префикс ключа правила отправки в сеансе`},help:{"v1-ac4dee-5n":`Сопоставляет нормализованный префикс ключа сеанса после внутренних этапов нормализации ключа в компонентах, применяющих политику. Используйте для общих ограничений по префиксу; если требуется точное сопоставление полного ключа, предпочтительнее rawKeyPrefix.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2ErawKeyPrefix":{label:{"v1-9eqaoe-w":`Префикс исходного ключа правила отправки в сеансе`},help:{"v1-1g9w044-5e":`Сопоставляет исходный, ненормализованный префикс ключа сессии для точного применения политики по полному ключу. Используйте, когда нормализованный keyPrefix охватывает слишком много сессий и требуется точность с учётом префикса агента или конкретного транспорта.`}},"session%2Esharing":{label:{"v1-ua4axr-l":`Режимы совместного доступа к сессиям`},help:{"v1-xbh52d-5a":`Определяет, какие режимы совместной работы могут выбирать владельцы сессий и администраторы. Неуказанные логические параметры по умолчанию включены; установите для режима false, чтобы убрать его из списка выбора и запретить его выбор в дальнейшем.`}},"session%2Esharing%2Edrafts":{label:{"v1-egpd9a-k":`Разрешить черновые сессии`},help:{"v1-1lzap27-2p":`Разрешает черновой режим видимости, скрывающий сессии от операторов, которые не являются их владельцами или администраторами. По умолчанию: true.`}},"session%2Esharing%2EreadOnly":{label:{"v1-wl9bhk-o":`Разрешить сессии только для чтения`},help:{"v1-upl3nu-21":`Разрешает делать сессии доступными только для чтения тем, кто не является их участником. По умолчанию: true.`}},"session%2Esharing%2Esuggest":{label:{"v1-1a87tux-m":`Разрешить сессии с предложениями`},help:{"v1-4i8owu-4g":`Разрешает режим видимости с предложениями. На данном этапе применяется та же политика допуска, что и в режиме только для чтения; настройка очередей предложений будет доступна в рамках будущей функции. По умолчанию: true.`}},"session%2Estore":{label:{"v1-1udxgtl-i":`Путь к хранилищу сессий`},help:{"v1-hreznz-56":`Задаёт путь к файлу хранилища сессий, в котором записи сессий сохраняются между перезапусками. Указывайте путь явно, только если вам нужны особое размещение на диске, отдельный путь для резервного копирования или хранение на подключённом томе.`}},"session%2EthreadBindings":{label:{"v1-hldn3x-n":`Привязки сессий к веткам обсуждений`},help:{"v1-zbzihu-4s":`Общие настройки по умолчанию для создания и маршрутизации сессий, привязанных к веткам, во всех поддерживаемых каналах. Задавайте глобальные настройки здесь и переопределяйте их для отдельных каналов только при необходимости другого поведения.`}},"session%2EthreadBindings%2EdefaultSpawnContext":{label:{"v1-yj4mot-k":`Контекст создания сессии в ветке`},help:{"v1-1set6nw-4c":`Контекст встроенного субагента по умолчанию при создании сессий, привязанных к веткам. Используйте "fork", чтобы начать с истории диалога инициатора, или "isolated", чтобы создать дочернюю сессию с чистого листа. По умолчанию: "fork".`}},"session%2EthreadBindings%2Eenabled":{label:{"v1-15vicbp-m":`Привязка к веткам включена`},help:{"v1-foomtc-3f":`Глобальный переключатель создания, маршрутизации и доставки для сессий, привязанных к веткам. Выключите его, чтобы отключить привязку к веткам во всей системе.`}},"session%2EthreadBindings%2EidleHours":{label:{"v1-frd27j-z":`Тайм-аут бездействия привязки к ветке (часы)`},help:{"v1-gffnx3-3h":`Период бездействия по умолчанию в часах для сессий, привязанных к веткам, во всех провайдерах и каналах (0 отключает завершение по бездействию). По умолчанию: 24.`}},"session%2EthreadBindings%2EmaxAgeHours":{label:{"v1-1pyqt5n-u":`Максимальный срок действия привязки к ветке (часы)`},help:{"v1-1xfcyhw-39":`Необязательный строгий предел срока действия в часах для сессий, привязанных к веткам, во всех провайдерах и каналах (0 отключает ограничение). По умолчанию: 0.`}},"session%2EthreadBindings%2EspawnSessions":{label:{"v1-hsfsa4-r":`Создание сессий, привязанных к веткам`},help:{"v1-1lqwbdl-46":`Глобальное разрешение по умолчанию на создание рабочих сессий, привязанных к веткам, через sessions_spawn и механизмы создания веток ACP. По умолчанию: true, если привязки к веткам включены.`}},skills:{label:{"v1-1bk7xrz-6":`Skills`}},"skills%2Eload%2EallowSymlinkTargets":{label:{"v1-i5s6ov-t":`Разрешённые целевые пути символических ссылок навыков`},help:{"v1-xzybiq-4t":`Доверенные корневые каталоги реальных целей, на которые могут указывать символические ссылки навыков за пределами настроенного исходного корневого каталога. Ограничьте этот список, например каталогом навыков в соседнем репозитории.`}},"skills%2Eload%2EextraDirs":{label:{"v1-1ufjbnf-n":`Дополнительные каталоги навыков`},help:{"v1-11o7opu-53":`Дополнительные общие корневые каталоги навыков для сканирования с самым низким приоритетом. Используйте для соседних репозиториев или общих наборов навыков, которые должны быть доступны без копирования в рабочую область OpenClaw.`}},"skills%2Eload%2Ewatch":{label:{"v1-fhhyqq-c":`Отслеживать Skills`},help:{"v1-1ckr2l5-5d":`Включает отслеживание изменений определений навыков в файловой системе, чтобы применять обновления без полного перезапуска процесса. Оставляйте включённым при разработке и отключайте в неизменяемых образах для промышленной эксплуатации.`}},"skills%2Eworkshop%2Eautonomous%2Emode":{label:{"v1-1hrc7h4-u":`Автономный режим мастерской навыков`},help:{"v1-1s3kgit-6j":`Управляет фоновым обучением: "off" оставляет только напоминание с рекомендацией, "propose" создаёт предложения, ожидающие одобрения, а "auto" применяет зафиксированные предложения и еженедельно проверяет навыки под управлением мастерской, внося обычные правки в файлы. По умолчанию: "auto".`}},surfaces:{label:{"v1-exl2ye-g":`Политики интерфейсов доставки`},help:{"v1-vgtjbs-50":`Переопределения политики сообщений для отдельных интерфейсов доставки, заданные по определённому идентификатору интерфейса. Используйте только тогда, когда одному из развёрнутых интерфейсов требуется более строгая обработка ответов без вывода, чем предусмотрено настройками агента по умолчанию.`}},"surfaces%2E*%2EsilentReply":{label:{"v1-1n816d1-r":`Политика ответов без вывода для интерфейса доставки`},help:{"v1-12zgc3n-60":`Переопределяет политику ответов без вывода для одного определённого интерфейса доставки. Незаданные поля наследуют значения agents.defaults.silentReply; используйте узкоспециализированные идентификаторы интерфейсов, чтобы внутреннее или специфичное для группы поведение не распространялось на другие места назначения.`}},talk:{label:{"v1-15ukbjj-4":`Разговор`},help:{"v1-1gx10xa-5g":`Настройки синтеза речи в режиме Talk: характеристики голоса, выбор модели, формат вывода и поведение при прерывании. Используйте этот раздел, чтобы настроить голосовое взаимодействие с пользователем, контролируя задержку и затраты.`}},"talk%2EagentId":{label:{"v1-17bcfby-a":`Агент Talk`},help:{"v1-iee5l9-2b":`Агент, которому принадлежат сеансы Talk, созданные без явно указанного ключа сеанса с привязкой к агенту.`}},"talk%2EconsultFastMode":{label:{"v1-12natsq-m":`Быстрый режим консультаций Talk`},help:{"v1-syf3xk-2o":`Задайте true или false для быстрого режима обычного запуска агента, обеспечивающего консультации Talk в реальном времени.`}},"talk%2EconsultThinkingLevel":{label:{"v1-f04pev-r":`Уровень рассуждений для консультаций Talk`},help:{"v1-1ft5njw-2o":`Используйте эту настройку, чтобы переопределить уровень рассуждений для обычного запуска агента, обеспечивающего консультации Talk в реальном времени.`}},"talk%2EinterruptOnSpeech":{label:{"v1-12q9u31-o":`Прерывание при речи пользователя в Talk`},help:{"v1-8n9q4o-3l":`При значении true (по умолчанию) речь ассистента останавливается, когда пользователь начинает говорить в режиме Talk. Оставьте включённым для естественного чередования реплик.`}},"talk%2Eprovider":{label:{"v1-1y50zho-k":`Активный провайдер Talk`},help:{"v1-wgnxhg-1g":`Идентификатор активного провайдера Talk (например, "acme-speech").`}},"talk%2Eproviders":{label:{"v1-1ifkkv5-m":`Настройки провайдеров Talk`},help:{"v1-oh0yuv-30":`Настройки Talk для отдельных провайдеров с идентификаторами провайдеров в качестве ключей. При миграции используйте их вместо устаревших ключей talk.*.`}},"talk%2Eproviders%2E*":{label:{"v1-1bo3c2y-k":`Конфигурация провайдера Talk`},help:{"v1-36pblg-1r":`Поля конфигурации Talk, определяемые провайдером с соответствующим идентификатором.`}},"talk%2Eproviders%2E*%2EapiKey":{label:{"v1-ln76q3-l":`Ключ API провайдера Talk`},help:{"v1-1a1p9wp-v":`Ключ API провайдера для режима Talk.`}},"talk%2Erealtime":{label:{"v1-xsdfxg-d":`Talk в реальном времени`},help:{"v1-c2re7j-3z":`Провайдер, модель, голос, режим, транспорт и стратегия рассуждений для Talk в реальном времени. Храните настройки провайдера речи/TTS в talk.provider и talk.providers.`}},"talk%2Erealtime%2Ebrain":{label:{"v1-7nqi8o-j":`Стратегия рассуждений Talk в реальном времени`},help:{"v1-opsatw-37":`Стратегия рассуждений Talk: agent-consult для помощи агента через Gateway, direct-tools для локальных вызовов инструментов или none.`}},"talk%2Erealtime%2EconsultRouting":{label:{"v1-1nxl3sq-t":`Маршрутизация консультаций Talk в реальном времени`},help:{"v1-10qjcvk-5f":`Резервная передача итоговых расшифровок речи пользователя через Gateway, когда провайдер реального времени пропускает openclaw_agent_consult. provider-direct сохраняет ответы провайдера; force-agent-consult направляет запросы через OpenClaw.`}},"talk%2Erealtime%2Einstructions":{label:{"v1-1aogivp-q":`Инструкции Talk в реальном времени`},help:{"v1-1jaaj84-5p":`Дополнительные системные инструкции, добавляемые к встроенному промпту OpenClaw для Talk в реальном времени. Используйте их для настройки стиля голоса, тона и других аспектов поведения провайдера в реальном времени, сохраняя указания agent-consult без изменений.`}},"talk%2Erealtime%2Emode":{label:{"v1-1ulyfkf-i":`Режим Talk в реальном времени`},help:{"v1-1u2xui1-1l":`Режим выполнения Talk: realtime, stt-tts или transcription.`}},"talk%2Erealtime%2Emodel":{label:{"v1-3tgxll-j":`Модель Talk в реальном времени`},help:{"v1-amou5a-27":`Переопределение идентификатора модели провайдера реального времени для сеансов Talk в браузере или под управлением Gateway.`}},"talk%2Erealtime%2EprefixPaddingMs":{label:{"v1-1n2zx1c-x":`Предварительный аудиобуфер Talk в реальном времени (мс)`},help:{"v1-1cwg07n-22":`Длительность сохраняемого аудио перед обнаружением голосовой активности в реальном времени, в миллисекундах.`}},"talk%2Erealtime%2Eprovider":{label:{"v1-13pps61-m":`Провайдер Talk в реальном времени`},help:{"v1-wwsmpt-1o":`Идентификатор активного провайдера голосового общения в реальном времени, например openai или google.`}},"talk%2Erealtime%2Eproviders":{label:{"v1-zi8arq-v":`Настройки провайдеров Talk в реальном времени`},help:{"v1-ruagcu-1r":`Настройки голосового общения в реальном времени для отдельных провайдеров, сгруппированные по идентификатору провайдера.`}},"talk%2Erealtime%2Eproviders%2E*":{label:{"v1-n5oah5-t":`Конфигурация провайдера Talk в реальном времени`},help:{"v1-edfpxm-1u":`Конфигурация голосового общения в реальном времени, определяемая провайдером с соответствующим идентификатором.`}},"talk%2Erealtime%2Eproviders%2E*%2EapiKey":{label:{"v1-1kd7m42-u":`Ключ API провайдера Talk в реальном времени`},help:{"v1-1fbmgpx-z":`Ключ API провайдера для Talk в реальном времени.`}},"talk%2Erealtime%2EreasoningEffort":{label:{"v1-1cxnmcm-u":`Уровень усилий при рассуждении в Talk в реальном времени`},help:{"v1-157xd3e-2t":`Уровень усилий при рассуждении для сеансов Talk в реальном времени, зависящий от провайдера, например minimal, low, medium или high.`}},"talk%2Erealtime%2EsilenceDurationMs":{label:{"v1-190chw8-z":`Длительность тишины в Talk в реальном времени (мс)`},help:{"v1-1grnu06-1y":`Длительность тишины в миллисекундах, после которой реплика пользователя в Talk в реальном времени считается завершённой.`}},"talk%2Erealtime%2EspeakerVoice":{label:{"v1-hgae7v-r":`Голос озвучивания Talk в реальном времени`},help:{"v1-1kgb166-2h":`Переопределение имени голоса провайдера реального времени для сеансов Talk в браузере или под управлением Gateway.`}},"talk%2Erealtime%2EspeakerVoiceId":{label:{"v1-10l8f2s-u":`Идентификатор голоса озвучивания Talk в реальном времени`},help:{"v1-1k8w6vk-2f":`Переопределение идентификатора голоса провайдера реального времени для сеансов Talk в браузере или под управлением Gateway.`}},"talk%2Erealtime%2Etransport":{label:{"v1-1mlwsll-n":`Транспорт Talk в реальном времени`},help:{"v1-2otjgn-2g":`Транспорт байтов и сеансов Talk: webrtc, provider-websocket, gateway-relay или managed-room.`}},"talk%2Erealtime%2EvadThreshold":{label:{"v1-1plwtg4-r":`Порог VAD для Talk в реальном времени`},help:{"v1-nf5l2t-2j":`Порог обнаружения голосовой активности в реальном времени от 0 (максимальная чувствительность) до 1 (минимальная чувствительность).`}},"talk%2EsilenceTimeoutMs":{label:{"v1-q6e4ju-p":`Тайм-аут тишины в Talk (мс)`},help:{"v1-1kim32f-59":`Длительность молчания пользователя в миллисекундах, после которой режим Talk завершает и отправляет текущую расшифровку. Оставьте незаданным, чтобы использовать стандартную длительность паузы для платформы (700 мс на macOS и Android, 900 мс на iOS).`}},"talk%2EspeechLocale":{label:{"v1-gbwzpr-i":`Языковой стандарт речи Talk`},help:{"v1-1un3x4l-4c":`Идентификатор языкового стандарта BCP 47 для распознавания речи Talk на узлах устройств и резервного использования системного голоса iOS, например "ru-RU". Оставьте незаданным, чтобы использовать настройки по умолчанию каждого устройства.`}},telemetry:{label:{"v1-sqprmo-9":`Телеметрия`},help:{"v1-1o5tru3-55":`Явное согласие на отправку анонимной статистики использования функций вместе с ежедневной проверкой обновлений. Статистика использования функций отключена по умолчанию и никогда не включает сообщения, учётные данные или идентификаторы.`}},"telemetry%2EconsentedAt":{label:{"v1-1cb2euy-10":`Время согласия на сбор статистики использования функций`},help:{"v1-1t051az-3t":`Отметка времени в формате ISO, фиксирующая, когда оператор согласился на сбор анонимной статистики использования функций или отказался от него. Предотвращает повторный запрос в мастере настройки.`}},"telemetry%2Eenabled":{label:{"v1-166i16f-s":`Анонимная статистика использования функций`},help:{"v1-1ptrwuq-4r":`Передаёт названия включённых каналов и провайдеров, количество плагинов и недавних сеансов вместе с ежедневной проверкой обновлений. Отключена по умолчанию и всегда отключена при DO_NOT_TRACK=1.`}},tools:{label:{"v1-15cdqf0-5":`Инструменты`},help:{"v1-1el54kl-5h":`Инфраструктура инструментов и межагентные настройки по умолчанию. Соседние разделы корневого уровня отвечают за инфраструктуру и межагентные настройки по умолчанию; agents.defaults отвечает за поведение цикла агента; записи отдельных агентов могут переопределять и то и другое, если это поддерживается.`}},"tools%2EagentToAgent":{label:{"v1-19yyyqk-q":`Межагентный доступ к инструментам`},help:{"v1-1ynpa5f-cf":`Политика межагентных вызовов инструментов сеансов: отправка, получение списка, истории, поиск и чтение статуса (по умолчанию включено). Используйте allow для ограничения пар агентов; enabled=false блокирует обычный межагентный доступ. Сеансы нативных субагентов и дочерние сеансы ACP, принадлежащие запрашивающему агенту, остаются доступны при видимости tree или all. Для строгого разделения задайте tools.sessions.visibility значение agent или self (tree по-прежнему допускает доступ к принадлежащим запрашивающему агенту нативным дочерним сеансам и дочерним сеансам ACP) либо используйте отдельные Gateway.`}},"tools%2EagentToAgent%2Eallow":{label:{"v1-96jndk-v":`Список разрешённых целевых агентов для межагентного доступа`},help:{"v1-1jt2ari-76":`Идентификаторы агентов или шаблоны с *, которым разрешено участвовать в межагентных вызовах; и запрашивающий, и целевой агент должны соответствовать списку. Межагентный доступ включён по умолчанию; отсутствующий или пустой allow разрешает любую пару. Задайте явный список для ограничения доступа; пустые записи запрещают доступ.`}},"tools%2EagentToAgent%2Eenabled":{label:{"v1-1petv53-q":`Включить инструмент межагентного доступа`},help:{"v1-w950oq-ba":`Включает межагентный доступ к инструментам сеансов (по умолчанию true); отсутствующий или пустой allow разрешает любую пару агентов. Установите false, чтобы заблокировать обычный межагентный доступ; сеансы нативных субагентов и дочерние сеансы ACP, принадлежащие запрашивающему агенту, остаются доступны при видимости tree или all. Для строгого разделения задайте tools.sessions.visibility значение agent или self (tree по-прежнему допускает доступ к принадлежащим запрашивающему агенту нативным дочерним сеансам и дочерним сеансам ACP) либо используйте отдельные Gateway.`}},"tools%2Eallow":{label:{"v1-1hmvki6-e":`Список разрешённых инструментов`},help:{"v1-1is3eaq-4v":`Полный список разрешённых инструментов, заменяющий настройки профиля по умолчанию для сред со строгими ограничениями. Используйте его, только если намеренно ограничиваете возможности инструментов тщательно отобранным набором.`}},"tools%2EalsoAllow":{label:{"v1-x011gj-o":`Дополнения к списку разрешённых инструментов`},help:{"v1-1xw9zp8-57":`Дополнительные записи списка разрешённых инструментов, добавляемые к выбранному профилю инструментов и политике по умолчанию. Делайте этот список коротким и явным, чтобы при аудите можно было быстро выявить намеренные исключения из политики.`}},"tools%2EbyProvider":{label:{"v1-ca7c4x-n":`Политика инструментов по провайдерам`},help:{"v1-1ecljob-4y":`Переопределения разрешений и запретов инструментов для отдельных провайдеров, заданные по идентификатору канала или провайдера, для настройки возможностей в разных интерфейсах. Используйте их, если одному из провайдеров нужны более строгие ограничения, чем предусмотрены глобальной политикой инструментов.`}},"tools%2EcodeMode":{label:{"v1-194jdgf-9":`Режим кода`},help:{"v1-1ecc39k-6k":'Общий режим OpenClaw Code Mode. Если глобальная настройка не задана, по умолчанию используется `"auto"`; явно заданный объект без `enabled` оставляет режим выключенным. При запусках агента с включённым режимом модели доступны только `exec` и `wait`, а доступ к обычным инструментам осуществляется через мост каталога.'}},"tools%2EcodeMode%2Eenabled":{label:{"v1-162yoj6-g":`Включить режим кода`},help:{"v1-rgstxz-aj":'Глобальное включение OpenClaw Code Mode. Если глобальная настройка полностью отсутствует, по умолчанию используется `"auto"`; явно заданный объект без `enabled` оставляет режим выключенным. Значение `"auto"` включает режим для моделей, предпочитающих каталог, а `true` — для запусков с поддержкой инструментов. Переопределения включения режима на уровне агента и модели имеют приоритет. Если среда выполнения недоступна, запуск с включённым режимом блокируется, а не открывает доступ к полному списку инструментов.'}},"tools%2EcodeMode%2Eexecutor":{label:{"v1-lbpzic-i":`Исполнитель режима кода`},help:{"v1-l8nlk2-6x":`Исполнитель JavaScript: "node" (по умолчанию) использует Node vm для доверенного кода и не является защитной песочницей; "quickjs" использует встроенный плагин QuickJS WASM для выполнения гостевого кода с усиленной защитой. Разрешения инструментов применяются к обоим вариантам. Если выбранный исполнитель отсутствует, выполнение блокируется.`}},"tools%2EcodeMode%2EmaxOutputBytes":{label:{"v1-aewvtz-m":`Ограничение объёма вывода режима кода`},help:{"v1-1hmij9q-1n":`Максимальный объём сериализованных данных в байтах, возвращаемых через вывод режима кода.`}},"tools%2EcodeMode%2EmaxPendingToolCalls":{label:{"v1-1keh21t-s":`Лимит ожидающих вызовов инструментов в режиме кода`},help:{"v1-3b5tyd-2i":`Максимальное число одновременных вложенных вызовов инструментов, которые виртуальная машина режима кода может запустить, прежде чем ей потребуется приостановиться и возобновить работу позже.`}},"tools%2EcodeMode%2EmaxSearchLimit":{label:{"v1-1f02yk9-s":`Максимальное число результатов поиска в режиме кода`},help:{"v1-1gpue5r-28":`Максимальное число результатов поиска по скрытому каталогу, которое может запросить программа в режиме кода.`}},"tools%2EcodeMode%2EmaxSnapshotBytes":{label:{"v1-1tt9adm-o":`Лимит размера снимка в режиме кода`},help:{"v1-1mmgkqy-1x":`Максимальное число байтов, сохраняемых в сериализованном виде для одного снимка приостановленной виртуальной машины QuickJS.`}},"tools%2EcodeMode%2EmemoryLimitBytes":{label:{"v1-5bockh-m":`Лимит памяти в режиме кода`},help:{"v1-xetora-6n":`Лимит кучи гостевой среды QuickJS или приблизительный бюджет кучи V8 рабочего потока Node в байтах. Накладные расходы среды выполнения Node и минимальные объёмы памяти, выделяемые движком, влияют на фактический бюджет; внешние буферы и RSS процесса не учитываются. Это не является гарантией безопасности.`}},"tools%2EcodeMode%2Emode":{label:{"v1-1a1ijjo-h":`Интерфейс режима кода`},help:{"v1-dsp2b9-2x":'Интерфейс, доступный модели. Поддерживается только "only": предоставляет `exec` и `wait` режима кода и скрывает обычные инструменты.'}},"tools%2EcodeMode%2EsearchDefaultLimit":{label:{"v1-1xkxvss-w":`Число результатов поиска по умолчанию в режиме кода`},help:{"v1-1io42lu-2m":"Число результатов поиска по скрытому каталогу, возвращаемых по умолчанию функцией `catalog.search` в режиме кода."}},"tools%2EcodeMode%2EsnapshotTtlSeconds":{label:{"v1-xs8rwp-m":`Время жизни снимка в режиме кода`},help:{"v1-1nxfczz-28":"Как долго приостановленные запуски Code Mode можно возобновлять с помощью `wait` до истечения срока их действия."}},"tools%2EcodeMode%2EtimeoutMs":{label:{"v1-1rjrbio-h":`Тайм-аут режима кода`},help:{"v1-8csycm-1p":"Максимальное время в миллисекундах для одного вызова `exec` или `wait` в режиме кода."}},"tools%2Edeny":{label:{"v1-fwuia7-d":`Список запрещённых инструментов`},help:{"v1-wilr1b-4p":`Глобальный список запретов, блокирующий указанные инструменты, даже если правила профиля или провайдера разрешают их. Используйте правила запрета для экстренной блокировки и долгосрочной многоуровневой защиты.`}},"tools%2Eelevated":{label:{"v1-15z7aw7-k":`Доступ к инструментам с повышенными привилегиями`},help:{"v1-ehcm0r-5a":`Настройки доступа к инструментам для выполнения привилегированных команд, которые должны быть доступны только доверенным отправителям. Оставьте отключёнными, если рабочие процессы оператора явно не требуют действий с повышенными привилегиями.`}},"tools%2Eelevated%2EallowFrom":{label:{"v1-yx3m99-p":`Правила разрешения для инструментов с повышенными привилегиями`},help:{"v1-1u9bhih-54":`Правила, разрешающие отправителям использовать инструменты с повышенными привилегиями; обычно задаются с учётом форматов идентификаторов канала или провайдера. Указывайте только конкретные идентификаторы нужных отправителей, чтобы посторонние пользователи не могли запускать привилегированные команды.`}},"tools%2Eelevated%2Eenabled":{label:{"v1-15kpc2g-r":`Включить доступ к инструментам с повышенными привилегиями`},help:{"v1-1n8oyal-4l":`Включает выполнение инструментов с повышенными привилегиями после успешной проверки отправителя и политик. Оставьте отключённым в публичных и общих каналах и включайте только в доверенных средах под управлением владельца.`}},"tools%2Eexec":{label:{"v1-33cqoe-9":`Инструмент exec`},help:{"v1-p5piic-56":`Группа политик инструмента exec для хоста выполнения команд оболочки, режима безопасности, порядка подтверждения и привязок среды выполнения. В рабочей среде сохраняйте строгие настройки по умолчанию и усиливайте ограничения на выполнение с повышенными привилегиями.`}},"tools%2Eexec%2EapplyPatch%2EallowModels":{label:{"v1-1pc6erm-r":`Список разрешённых моделей для apply_patch`},help:{"v1-4q5ovf-1x":`Необязательный список разрешённых идентификаторов моделей (например, "gpt-5.4" или "openai/gpt-5.4").`}},"tools%2Eexec%2EapplyPatch%2Eenabled":{label:{"v1-c3mjij-i":`Включить apply_patch`},help:{"v1-1erkir4-31":`Включить или отключить apply_patch для моделей OpenAI и OpenAI Codex, если это разрешено политикой использования инструментов (по умолчанию: true).`}},"tools%2Eexec%2EapplyPatch%2EworkspaceOnly":{label:{"v1-1mlvoxc-q":`apply_patch только в рабочей области`},help:{"v1-x2z207-3o":`Ограничить пути apply_patch каталогом рабочей области (по умолчанию: true). Установите false, чтобы разрешить запись за пределами рабочей области (опасно).`}},"tools%2Eexec%2EapprovalRunningNoticeMs":{label:{"v1-s8uk67-x":`Задержка уведомления о выполнении exec после одобрения (мс)`},help:{"v1-1gwwann-4z":`Задержка в миллисекундах перед показом уведомления о ходе выполнения после одобрения exec. Увеличьте значение, чтобы уменьшить мерцание при выполнении быстрых команд, или уменьшите, чтобы быстрее информировать оператора.`}},"tools%2Eexec%2Eask":{label:{"v1-1kx7cwd-8":`Запрос подтверждения exec`}},"tools%2Eexec%2EcommandHighlighting":{label:{"v1-1n3ojuz-p":`Подсветка команд exec`},help:{"v1-kyxd4o-4n":`Показывать подсветку команд на основе синтаксического анализа в запросах на одобрение exec (по умолчанию: false). Включите, чтобы отображать текст команд с подсветкой, не меняя политику одобрения exec.`}},"tools%2Eexec%2EgrantExpiryDays":{label:{"v1-2d156s-s":`Срок действия постоянного разрешения (дни)`},help:{"v1-5uxe2j-6r":`Срок действия по умолчанию в днях (1–3650) для постоянных разрешений, создаваемых через allow-always при одобрении автоматизаций. Если значение не задано, разрешения действуют до отзыва или изменения автоматизации, которой они принадлежат. Условия фиксируются при создании, поэтому изменение этого значения влияет только на будущие разрешения.`}},"tools%2Eexec%2Ehost":{label:{"v1-6z76n1-b":`Целевая среда exec`},help:{"v1-rno1mf-5q":`Выбирает стратегию определения среды выполнения команд оболочки. Используйте "auto" для выбора с учётом среды выполнения (sandbox, если доступна, иначе gateway) или явно укажите sandbox/gateway/node, если нужна фиксированная среда.`}},"tools%2Eexec%2Emode":{label:{"v1-luiaev-9":`Режим выполнения`},help:{"v1-1wi6t4l-5q":`Унифицированный выбор политики выполнения. Используйте "auto", чтобы команды без одобрения проверял классификатор, "ask" — чтобы их проверял человек, "allowlist" — чтобы разрешить только заведомо безопасные команды, или "full" — для доверенной локальной работы.`}},"tools%2Eexec%2Enode":{label:{"v1-s03avl-h":`Привязка узла выполнения`},help:{"v1-rfnz54-4s":`Настройка привязки узла для инструментов выполнения, когда выполнение команд делегируется подключённым узлам. Используйте явную привязку узла только при необходимости маршрутизации между несколькими узлами.`}},"tools%2Eexec%2EnotifyOnExit":{label:{"v1-rwarum-j":`Уведомление о завершении выполнения`},help:{"v1-1ounlvx-3q":`При значении true (по умолчанию) завершение фоновых сеансов выполнения и события жизненного цикла выполнения на узлах добавляют системное событие в очередь и запрашивают проверку активности.`}},"tools%2Eexec%2EnotifyOnExitEmptySuccess":{label:{"v1-1hs7mlg-s":`Уведомление об успешном выполнении без вывода`},help:{"v1-1wx4xxd-3d":`При значении true успешное завершение фонового выполнения с пустым выводом также добавляет в очередь системное событие о завершении (по умолчанию: false).`}},"tools%2Eexec%2EpathPrepend":{label:{"v1-18ajzln-h":`Добавление в начало PATH для выполнения`},help:{"v1-s1aimc-1r":`Каталоги, добавляемые в начало PATH при выполнении команд (gateway/sandbox).`}},"tools%2Eexec%2Ereviewer":{label:{"v1-1dgtjz-d":`Проверяющий выполнение`},help:{"v1-12y548k-4x":`Проверка выполнения команд с помощью модели, используемая в автоматическом режиме перед запросом одобрения человеком. Укажите здесь отдельную модель, если хотите изолировать проверку выполнения команд от основной модели агента.`}},"tools%2Eexec%2Ereviewer%2EfastMode":{label:{"v1-hd75ia-n":`Быстрый режим проверки разрешений на выполнение`},help:{"v1-175bx14-8u":`Необязательный быстрый режим проверки запросов на одобрение в OpenClaw: true запрашивает приоритетную обработку на поддерживаемых маршрутах OpenAI Responses и ChatGPT/OAuth; false запрашивает стандартную обработку. Не задавайте значение, чтобы сохранить настройки провайдера по умолчанию. Быстрый режим может стоить дороже, а его доступность зависит от провайдера. Не настраивает встроенный Codex Guardian.`}},"tools%2Eexec%2Ereviewer%2Emodel":{label:{"v1-90ol5u-j":`Модель проверки выполнения команд`},help:{"v1-1lltiy5-3i":`Необязательное переопределение поставщика/модели для агента проверки выполнения команд. Не указывайте, чтобы использовать основную модель, настроенную для целевого агента.`}},"tools%2Eexec%2Ereviewer%2Ethinking":{label:{"v1-s17i85-m":`Уровень рассуждений при проверке разрешений на выполнение`},help:{"v1-yg2gby-6u":`Необязательный уровень усилий на рассуждение при проверке запросов на одобрение с помощью модели в OpenClaw: minimal, low, medium, high, xhigh или max. Не задавайте значение, чтобы сохранить настройки провайдера по умолчанию. Поддерживаемые уровни приводятся к значениям, допустимым для выбранной модели. Не настраивает встроенный Codex Guardian.`}},"tools%2Eexec%2Ereviewer%2EtimeoutMs":{label:{"v1-1shnxjr-q":`Тайм-аут проверки выполнения команд (мс)`},help:{"v1-1o30chi-3w":`Тайм-аут каждого этапа проверки выполнения команд в миллисекундах: подготовки модели и получения ответа. По истечении тайм-аута запрашивается одобрение человеком (по умолчанию: 30000).`}},"tools%2Eexec%2EsafeBinProfiles":{label:{"v1-ez9qvm-m":`Профили безопасных исполняемых файлов`},help:{"v1-4cdcwe-29":`Необязательные профили безопасности для отдельных исполняемых файлов (ограничения позиционных аргументов + разрешённые/запрещённые флаги).`}},"tools%2Eexec%2EsafeBins":{label:{"v1-21op89-e":`Безопасные исполняемые файлы`},help:{"v1-1of1m2s-21":`Разрешить запуск безопасных исполняемых файлов, работающих только со стандартным вводом, без явного добавления в список разрешённых.`}},"tools%2Eexec%2EsafeBinTrustedDirs":{label:{"v1-vpqq4p-q":`Доверенные каталоги безопасных исполняемых файлов`},help:{"v1-zljbcn-2v":`Дополнительные явно указанные каталоги, считающиеся доверенными при проверке путей к безопасным исполняемым файлам (каталоги из PATH никогда не считаются доверенными автоматически).`}},"tools%2Eexec%2Esecurity":{label:{"v1-om3dyq-d":`Безопасность выполнения команд`}},"tools%2Eexec%2EstrictInlineEval":{label:{"v1-pzx6o5-s":`Требовать одобрение выполнения встроенного кода`},help:{"v1-jkmgo7-5z":"Требовать явного одобрения вызовов интерпретатора со встроенным кодом, таких как `python -c`, `node -e`, `ruby -e` или `osascript -e`. Предотвращает повторное применение списка разрешённых без уведомления и заменяет постоянное разрешение запросом одобрения при каждом таком вызове."}},"tools%2Eexec%2EtimeoutSeconds":{label:{"v1-1d0xrlr-m":`Тайм-аут выполнения (секунды)`}},"tools%2Efs%2EworkspaceOnly":{label:{"v1-nx841l-n":`Инструменты файловой системы только в рабочем каталоге`},help:{"v1-1mhuvka-2s":`Ограничить доступ инструментов файловой системы (read/write/edit/apply_patch) рабочим каталогом (по умолчанию: false).`}},"tools%2Egithub":{label:{"v1-jfcpb6-y":`Учётная запись GitHub CLI и автор Git`},help:{"v1-1fl77im-5s":`Управляемый локальный профиль GitHub CLI и необязательные данные автора Git для инструментов агента. Не задавайте этот объект, чтобы сохранить исходную учётную запись и данные автора пользователя, от имени которого работает Gateway; учётные данные для удалённых репозиториев никогда не переопределяются.`}},"tools%2Egithub%2EgitAuthor%2Eemail":{label:{"v1-durd6y-g":`Электронная почта автора Git`},help:{"v1-kol5g6-1i":`Необязательный адрес электронной почты автора и коммитера Git, действующий только в текущем процессе.`}},"tools%2Egithub%2EgitAuthor%2Ename":{label:{"v1-pv12jh-f":`Имя автора Git`},help:{"v1-z5bl1f-1h":`Необязательное имя автора и коммитера Git, действующее только в текущем процессе.`}},"tools%2Egithub%2Ekind":{label:{"v1-1ubt2yv-m":`Тип учётных данных GitHub`},help:{"v1-qi3qun-3q":`Обозначает управляемый профиль OAuth, сменяемые учётные данные обновления которого находятся под управлением Gateway. Если параметр не задан, профиль использует персональный токен доступа.`}},"tools%2Egithub%2EprofileId":{label:{"v1-ssneaz-m":`Версия профиля GitHub`},help:{"v1-4lzl0-27":`Автоматически созданный непрозрачный идентификатор версии профиля для атомарного переключения управляемых учётных данных.`}},"tools%2Elinks%2Eenabled":{label:{"v1-yims6g-p":`Включить анализ ссылок`},help:{"v1-23t2io-59":`Включить автоматический предварительный анализ ссылок, чтобы краткое содержание страниц по URL было доступно до начала рассуждений агента. Оставьте включённым для более полного контекста или отключите, если требуется строго минимальная обработка.`}},"tools%2Elinks%2EmaxLinks":{label:{"v1-l7d76c-s":`Максимальное число ссылок для анализа`},help:{"v1-ksxmcv-52":`Максимальное число ссылок, содержимое которых раскрывается за один ход при анализе ссылок. Используйте меньшие значения для ограничения задержек и затрат в активных обсуждениях, а большие — когда важен контекст из нескольких ссылок.`}},"tools%2Elinks%2Emodels":{label:{"v1-t894bf-p":`Модели для анализа ссылок`},help:{"v1-6j3mnw-5a":`Список предпочтительных моделей для анализа ссылок. Если поддерживается резервное переключение, модели используются по порядку. Для обычного составления сводок ставьте первыми лёгкие модели, а более ресурсоёмкие используйте только при необходимости.`}},"tools%2Elinks%2Escope":{label:{"v1-x79nuj-o":`Область применения анализа ссылок`},help:{"v1-183cwpa-55":`Определяет, когда выполняется анализ ссылок, в зависимости от контекста беседы и типа сообщения. Ограничивайте область применения, чтобы избежать ненужной загрузки содержимого ссылок в сообщениях, где их обработка не требуется.`}},"tools%2Elinks%2EtimeoutSeconds":{label:{"v1-hh7o78-w":`Тайм-аут анализа ссылок (сек)`},help:{"v1-61v30o-4p":`Предельное время анализа каждой ссылки в секундах, по истечении которого необработанные ссылки пропускаются. Ограничивайте это время, чтобы избежать длительных задержек, когда внешние сайты работают медленно или недоступны.`}},"tools%2EloopDetection%2Eenabled":{label:{"v1-c9sqnr-j":`Обнаружение зацикливания вызовов инструментов`},help:{"v1-1e3rls8-5g":`Управляет обнаружением зацикленных вызовов инструментов по скользящему окну истории и защитой после сжатия контекста. Не задавайте этот параметр, чтобы обнаружение по истории оставалось выключенным, а защита после сжатия — включённой. Установите true, чтобы включить оба механизма, или false, чтобы отключить оба.`}},"tools%2Emedia%2Eaudio%2Eattachments":{label:{"v1-1r0kwy-11":`Правила обработки вложений при анализе аудио`},help:{"v1-1s3t9s5-3o":`Выберите, какие подходящие аудиовложения обрабатывать. Обрабатывайте только первое вложение, если расшифровка нескольких вложений не требуется.`}},"tools%2Emedia%2Eaudio%2EechoFormat":{label:{"v1-15fud4j-m":`Формат вывода расшифровки`},help:{"v1-glpdzh-3i":`Задайте формат отправляемой расшифровки с помощью плейсхолдера {transcript}. Сохраните плейсхолдер без изменений, чтобы сообщение содержало расшифровку.`}},"tools%2Emedia%2Eaudio%2EechoTranscript":{label:{"v1-1gi9x8r-n":`Отправлять расшифровку в чат`},help:{"v1-1dedp8c-3r":`Отправлять расшифровку аудио в исходный чат до обработки агентом. Включите, если пользователям нужно проверять, что услышала система.`}},"tools%2Emedia%2Eaudio%2Eenabled":{label:{"v1-1ne86nm-q":`Включить распознавание аудио`},help:{"v1-1v0x7te-2m":`Включите распознавание аудио, чтобы преобразовывать голосовые сообщения и аудиозаписи в текст для контекста агента.`}},"tools%2Emedia%2Eaudio%2Elanguage":{label:{"v1-1jzzbi3-s":`Язык распознавания аудио`},help:{"v1-1ruqt97-3z":`Языковая подсказка по умолчанию для провайдеров расшифровки аудио. Задайте её, если основной язык речи известен, а провайдер ненадёжно определяет его автоматически.`}},"tools%2Emedia%2Eaudio%2EmaxBytes":{label:{"v1-hqnl72-t":`Максимальный размер аудио для распознавания в байтах`},help:{"v1-1mcckc8-43":`Ограничение размера входного аудио по умолчанию для настроенных и автоматически обнаруженных моделей. Укажите максимальный размер записи, допустимый для ваших провайдеров и сети.`}},"tools%2Emedia%2Eaudio%2EmaxChars":{label:{"v1-1vhezc0-t":`Максимальное число символов расшифровки аудио`},help:{"v1-eo1dp-43":`Максимальная длина расшифровки по умолчанию для настроенных и автоматически обнаруженных моделей. Уменьшите значение, чтобы длинные голосовые сообщения не увеличивали контекст агента.`}},"tools%2Emedia%2Eaudio%2EpreferredModel":{label:{"v1-1h7yz8z-z":`Предпочтительная модель распознавания аудио`},help:{"v1-1n5zya1-3c":`Отдавать предпочтение одной записи tools.media.models с меткой соответствующей возможности для транскрибирования аудио перед остальными совместимыми резервными вариантами.`}},"tools%2Emedia%2Eaudio%2Eprompt":{label:{"v1-1gqi94r-q":`Промпт для анализа аудио`},help:{"v1-1v5jtay-4b":`Промпт по умолчанию для транскрибирования аудио, если он не переопределён в записи модели. Не меняйте инструкцию, если последующие рабочие процессы зависят от стиля расшифровки.`}},"tools%2Emedia%2Eaudio%2Escope":{label:{"v1-erazqj-p":`Область применения анализа аудио`},help:{"v1-1pptfg0-3w":`Ограничьте анализ аудио по каналу, типу чата или ключу источника. Сужайте область применения, если автоматическое транскрибирование связано с конфиденциальными данными или высокими затратами.`}},"tools%2Emedia%2Eaudio%2EtimeoutSeconds":{label:{"v1-1ja2x9w-x":`Тайм-аут анализа аудио (сек)`},help:{"v1-n8wc6c-3b":`Тайм-аут по умолчанию для запросов на анализ аудио. Увеличьте его для длинных записей или медленных локальных моделей транскрибирования.`}},"tools%2Emedia%2Econcurrency":{label:{"v1-1ru9noi-v":`Параллельность анализа медиа`},help:{"v1-13kr9np-58":`Максимальное число одновременных операций анализа медиа за один ход для всех задач обработки изображений, аудио и видео. Уменьшите это значение в средах с ограниченными ресурсами, чтобы избежать перегрузки процессора и сети.`}},"tools%2Emedia%2Eimage%2Eattachments":{label:{"v1-19jrjw9-11":`Политика обработки вложений для анализа изображений`},help:{"v1-11hofbw-3e":`Выберите, какие подходящие вложения с изображениями обрабатывать. Обрабатывайте только первое вложение, если анализ нескольких изображений не требуется.`}},"tools%2Emedia%2Eimage%2Eenabled":{label:{"v1-dbw751-q":`Включить анализ изображений`},help:{"v1-1b2zw34-50":`Включите анализ изображений, чтобы преобразовывать прикреплённые или указанные по ссылке изображения в текстовый контекст. Отключите, если требуется работа только с текстом или вы хотите избежать затрат на обработку изображений.`}},"tools%2Emedia%2Eimage%2EmaxBytes":{label:{"v1-943dvt-t":`Максимальный размер изображения для анализа в байтах`},help:{"v1-jwwpd1-3v":`Ограничение размера входного изображения по умолчанию для настроенных и автоматически обнаруженных моделей. Задайте значение с учётом ограничений провайдера на размер передаваемых данных и доступной пропускной способности сети.`}},"tools%2Emedia%2Eimage%2EmaxChars":{label:{"v1-1p6mqsn-t":`Максимальная длина описания изображения в символах`},help:{"v1-ebnxhk-3q":`Максимальная длина описания изображения по умолчанию. Используйте меньшее значение для компактного контекста или большее — для подробного распознавания текста и анализа сцены.`}},"tools%2Emedia%2Eimage%2EpreferredModel":{label:{"v1-gy243w-z":`Предпочтительная модель анализа изображений`},help:{"v1-1o2uwo6-3c":`Использовать для анализа изображений одну запись tools.media.models с отметкой о поддерживаемой возможности в приоритетном порядке, перед остальными совместимыми резервными вариантами.`}},"tools%2Emedia%2Eimage%2Eprompt":{label:{"v1-i4kxh2-q":`Промпт для анализа изображений`},help:{"v1-1jdcu8b-3u":`Промпт для анализа изображений по умолчанию, если он не переопределён в записи. Формулируйте его однозначно, если потребителям результата нужны стабильные описания.`}},"tools%2Emedia%2Eimage%2Escope":{label:{"v1-xpdk4k-p":`Область применения анализа изображений`},help:{"v1-tievo1-3s":`Ограничьте анализ изображений по каналу, типу чата или ключу источника. В активных или недоверенных каналах задавайте узкую область применения, чтобы контролировать обработку.`}},"tools%2Emedia%2Eimage%2EtimeoutSeconds":{label:{"v1-60t1jb-x":`Время ожидания анализа изображений (с)`},help:{"v1-1wcm84x-31":`Время ожидания по умолчанию для запросов на анализ изображений. Увеличьте его для больших изображений или медленных локальных моделей компьютерного зрения.`}},"tools%2Emedia%2Emodels":{label:{"v1-b1r5p4-x":`Общие модели анализа медиа`},help:{"v1-f34u65-47":`Основной список моделей анализа медиа. Укажите для каждой записи теги возможностей image, audio или video, чтобы каждый конвейер выбирал только совместимые резервные модели.`}},"tools%2Emedia%2Evideo%2Eattachments":{label:{"v1-e4yzf-11":`Правила обработки вложений для анализа видео`},help:{"v1-1qm1qrc-3e":`Выберите, какие из подходящих видеовложений обрабатывать. Обрабатывайте только первое вложение, если анализ нескольких видео не требуется.`}},"tools%2Emedia%2Evideo%2Eenabled":{label:{"v1-sg3427-q":`Включить анализ видео`},help:{"v1-1ltx5gl-58":`Включите анализ видео, чтобы преобразовывать ролики в текстовые сводки для дальнейших рассуждений и ответов. Отключите, если обработка видео запрещена правилами или слишком затратна для вашего развёртывания.`}},"tools%2Emedia%2Evideo%2EmaxBytes":{label:{"v1-wzauwr-t":`Максимальный размер видео для анализа в байтах`},help:{"v1-2mp77v-3v":`Ограничение размера входного видео по умолчанию для настроенных и автоматически обнаруженных моделей. Установите значение с учётом ограничений провайдера на размер передаваемых данных и пропускной способности сети вашего развёртывания.`}},"tools%2Emedia%2Evideo%2EmaxChars":{label:{"v1-gb00od-t":`Максимальное число символов в описании видео`},help:{"v1-1j0x40b-3j":`Максимальная длина описания видео по умолчанию. Используйте меньшее значение для компактного контекста или большее — для подробного описания сцен.`}},"tools%2Emedia%2Evideo%2EpreferredModel":{label:{"v1-11pflaa-z":`Предпочтительная модель анализа видео`},help:{"v1-1cygq5k-3c":`Предпочитать одну запись tools.media.models с меткой возможности анализа видео остальным совместимым резервным вариантам.`}},"tools%2Emedia%2Evideo%2Eprompt":{label:{"v1-dq4his-q":`Промпт для анализа видео`},help:{"v1-ul2jx4-3r":`Промпт для анализа видео по умолчанию, если запись его не переопределяет. Используйте детерминированный промпт, если потребителям важна стабильность сводок.`}},"tools%2Emedia%2Evideo%2Escope":{label:{"v1-iwg12i-p":`Область применения анализа видео`},help:{"v1-7gfrx3-3s":`Ограничение анализа видео по каналу, типу чата или ключу источника. В активных или недоверенных каналах сужайте область применения, чтобы контролировать обработку.`}},"tools%2Emedia%2Evideo%2EtimeoutSeconds":{label:{"v1-syt2z1-x":`Тайм-аут анализа видео (с)`},help:{"v1-e8rzsy-33":`Тайм-аут по умолчанию для запросов на анализ видео. Увеличьте его для длинных роликов или медленных локальных моделей анализа.`}},"tools%2Emessage%2Eactions%2Eallow":{label:{"v1-a6trwv-o":`Список разрешённых действий с сообщениями`},help:{"v1-1iceqwa-5c":`Глобальный список разрешённых действий с сообщениями для инструмента message. Используйте его, только если вся среда выполнения должна предоставлять и принимать сокращённый набор действий; для публичных агентов или агентов в песочнице предпочтительны отдельные списки разрешённых действий.`}},"tools%2Emessage%2Ebroadcast%2Eenabled":{label:{"v1-awk06q-o":`Включить рассылку сообщений`},help:{"v1-1ms74z7-14":`Включить действие рассылки (по умолчанию: true).`}},"tools%2Emessage%2EcrossContext%2EallowAcrossProviders":{label:{"v1-lzee7y-12":`Разрешить обмен между контекстами разных провайдеров`},help:{"v1-276qxo-2s":`Разрешить отправку сообщений между разными провайдерами (по умолчанию: true). Установите false, чтобы запретить отправку сообщений между провайдерами.`}},"tools%2Emessage%2EcrossContext%2EallowWithinProvider":{label:{"v1-1ujg1kq-z":`Разрешить отправку между контекстами (один провайдер)`},help:{"v1-1sg4x49-1z":`Разрешить отправку в другие каналы в рамках одного провайдера (по умолчанию: true).`}},"tools%2Emessage%2EcrossContext%2Emarker%2Eenabled":{label:{"v1-4n38r9-k":`Метка отправки между контекстами`},help:{"v1-1fg6jrp-1z":`Добавлять видимую метку источника при отправке между контекстами (по умолчанию: true).`}},"tools%2Emessage%2EcrossContext%2Emarker%2Eprefix":{label:{"v1-vaqy0z-r":`Префикс метки отправки между контекстами`},help:{"v1-eblsru-1p":`Текстовый префикс меток отправки между контекстами (поддерживает «{channel}»).`}},"tools%2Emessage%2EcrossContext%2Emarker%2Esuffix":{label:{"v1-wa9bei-r":`Суффикс метки отправки между контекстами`},help:{"v1-1nk0jub-1p":`Текстовый суффикс меток отправки между контекстами (поддерживает «{channel}»).`}},"tools%2Eprofile":{label:{"v1-89srgu-c":`Профиль инструментов`},help:{"v1-h6k98q-5k":`Имя глобального профиля инструментов, используемого для выбора предустановленной базовой политики инструментов перед применением переопределений разрешений и запретов. Используйте его для единообразной настройки среды всех агентов и сохраняйте имена профилей неизменными.`}},"tools%2Esandbox":{label:{"v1-5qrg9w-j":`Политика инструментов песочницы`},help:{"v1-ea7awo-4k":`Оболочка политики инструментов для запусков агентов в песочнице, позволяющая задавать отдельные ограничения возможностей для таких запусков. Используйте её для усиления безопасности в песочнице.`}},"tools%2Esandbox%2Etools":{label:{"v1-y6y4ns-u":`Политика разрешений и запретов инструментов песочницы`},help:{"v1-ub701o-4t":`Политика разрешений и запретов инструментов, применяемая при запуске агентов в изолированных средах выполнения. Предоставляйте минимум разрешений, чтобы задачи в песочнице не могли приводить к ненужным внешним действиям.`}},"tools%2Esessions%2Evisibility":{label:{"v1-sk4wbc-o":`Видимость сеансов для инструментов`},help:{"v1-1vtq2rh-c5":`Определяет, к каким сеансам могут обращаться sessions_list/sessions_history/sessions_search/sessions_send/session_status. ("all" по умолчанию = любой сеанс на Gateway, включая сеансы других агентов и пользователей; "agent" = любой сеанс с идентификатором текущего агента; "self" = только текущий; "tree" = текущий сеанс + сеансы созданных субагентов). Доступ между агентами включён по умолчанию и ограничивается настройкой tools.agentToAgent; для ограничения доступа сузьте область видимости.`}},"tools%2Esubagents":{label:{"v1-5a8obi-k":`Политика инструментов субагентов`},help:{"v1-1xoug01-4z":`Обёртка политики инструментов для создаваемых субагентов, позволяющая ограничивать или расширять доступность инструментов относительно настроек родительского агента по умолчанию. Используйте её, чтобы ограничить возможности делегированных агентов рамками задачи.`}},"tools%2Esubagents%2Etools":{label:{"v1-m8ydym-v":`Политика разрешения и запрета инструментов субагентов`},help:{"v1-7vxsbf-5d":`Политика разрешения и запрета инструментов, применяемая к средам выполнения создаваемых субагентов. Задавайте более узкие разрешения, чем у родительского агента. Инструменты родительского агента, такие как progress_card, всегда запрещены, в том числе через allow/alsoAllow.`}},"tools%2Eswarm":{label:{"v1-1a8h35r-5":`Рой`},help:{"v1-1q96vvs-45":`Оркестрация субагентов в режиме сбора результатов. Включена по умолчанию; для отключения задайте false. Разрешения на использование инструментов по-прежнему применяются к agents_wait и параметрам создания группы субагентов.`}},"tools%2Eswarm%2EdefaultAgentId":{label:{"v1-wwvduv-j":`Агент группы по умолчанию`},help:{"v1-p4alpg-2m":`Целевой агент по умолчанию при создании группы субагентов без указания agentId. Список разрешённых субагентов по-прежнему применяется.`}},"tools%2Eswarm%2Eenabled":{label:{"v1-1ppe1ta-c":`Включить группу субагентов`},help:{"v1-1nnnrq9-2e":`Включает субагентов в режиме сбора результатов и agents_wait. По умолчанию включено; для отключения задайте false.`}},"tools%2Eswarm%2EmaxChildrenPerGroup":{label:{"v1-1vzvgye-t":`Активные дочерние агенты на группу роя`},help:{"v1-kfx6qp-1c":`Максимальное число активных дочерних агентов-сборщиков на группу роя.`}},"tools%2Eswarm%2EmaxConcurrent":{label:{"v1-1dmgf1f-p":`Одновременно работающие дочерние агенты роя`},help:{"v1-1d46jtm-1s":`Максимальное число одновременно работающих дочерних агентов-сборщиков на группу роя.`}},"tools%2Eswarm%2EmaxTotalPerGroup":{label:{"v1-1r1vzms-u":`Общее число дочерних агентов на группу роя`},help:{"v1-1gc9vl1-1e":`Максимальное число создаваемых агентов-сборщиков за всё время существования группы роя.`}},"tools%2Eswarm%2EwaitTimeoutSecondsMax":{label:{"v1-1naot35-q":`Максимальный тайм-аут ожидания роя`},help:{"v1-bog18y-1g":`Максимальный тайм-аут, принимаемый agents_wait, в секундах.`}},"tools%2EtoolSearch":{label:{"v1-pq1rnt-b":`Поиск инструментов`},help:{"v1-s0kx04-7y":`Сокращайте объём больших каталогов инструментов OpenClaw, MCP и клиентских инструментов. Если настройка не задана, среды выполнения OpenClaw автоматически используют структурированный Tool Search; активный Code Mode имеет приоритет, а Codex использует собственный поиск. Установите false для отключения, true для моста кода или используйте объектную форму для выбора режима.`}},"tools%2EtoolSearch%2EcodeTimeoutMs":{label:{"v1-yyul8h-o":`Тайм-аут выполнения кода поиска инструментов`},help:{"v1-105r499-34":"Максимальное время одного выполнения `tool_search_code` в миллисекундах. Среда выполнения ограничивает значения поддерживаемым диапазоном от 1 до 60 секунд."}},"tools%2EtoolSearch%2Eenabled":{label:{"v1-14qildc-i":`Включить поиск инструментов`},help:{"v1-1vm3hfr-4h":"Включает поиск инструментов. При включении OpenClaw скрывает большие каталоги инструментов за `tool_search_code` или структурированными инструментами поиска, описания и вызова во время работы во встроенной среде выполнения."}},"tools%2EtoolSearch%2EmaxSearchLimit":{label:{"v1-396rdd-n":`Максимальное число результатов поиска инструментов`},help:{"v1-7du4kh-32":`Максимальное количество результатов поиска инструментов, которое может запросить модель. При выполнении значения ограничиваются поддерживаемым диапазоном 1..50.`}},"tools%2EtoolSearch%2Emode":{label:{"v1-1qs9bxi-j":`Интерфейс поиска инструментов`},help:{"v1-jybcbe-7x":'Выберите интерфейс для модели: "code" предоставляет `tool_search_code`; "tools" предоставляет структурированные резервные инструменты поиска, описания и вызова; "directory" сохраняет видимым ограниченный каталог инструментов, предоставляет ограниченный набор схем вероятно нужных или обязательных инструментов, а остальные делает доступными через поиск, описание и вызов.'}},"tools%2EtoolSearch%2EsearchDefaultLimit":{label:{"v1-fq001m-r":`Количество результатов поиска инструментов по умолчанию`},help:{"v1-1uchq7t-39":"Количество результатов поиска инструментов, возвращаемых по умолчанию, если модель не указала лимит. При выполнении это значение ограничивается `maxSearchLimit`."}},"tools%2EupdatePlan":{label:{"v1-1u23ymq-r":`Включить инструмент структурированного планирования`},help:{"v1-1xgegme-4o":"Единый инструмент статуса `progress_card` для сохраняемых планов и текстовых заметок в родительских сеансах. Включён по умолчанию; для отключения задайте false. Всегда недоступен субагентам."}},"tools%2Eweb":{label:{"v1-3b07wa-9":`Веб-инструменты`},help:{"v1-fpsy5-4y":`Группа настроек политики веб-инструментов для поставщиков поиска и загрузки, лимитов и резервного поведения. Согласуйте включённые настройки с наличием ключей API и политикой исходящих сетевых подключений.`}},"tools%2Eweb%2Efetch%2EcacheTtlMinutes":{label:{"v1-1odhu2w-p":`Время жизни кеша веб-загрузки (мин)`},help:{"v1-1hk89qp-17":`Время жизни кеша результатов web_fetch в минутах.`}},"tools%2Eweb%2Efetch%2Eenabled":{label:{"v1-zuwpji-l":`Включить инструмент веб-загрузки`},help:{"v1-yrswld-1f":`Включить инструмент web_fetch (облегчённая загрузка по HTTP).`}},"tools%2Eweb%2Efetch%2Eheaders":{label:{"v1-3129be-p":`Заголовки запросов веб-загрузки`},help:{"v1-16bjkv5-me":"Дополнительные заголовки, отправляемые с прямыми запросами web_fetch, например заголовки маршрутизации через шлюз или аутентификации. Каждое настроенное значение считается конфиденциальным и скрывается в раскрываемой конфигурации и отладочных данных. Значения представляют собой обычные строки, поддерживают подстановку ${VAR} и глобальное экранирование $${VAR} для передачи литерала и отправляются на URL, выбранные моделью. Записи проверяются при формировании запроса, а не при загрузке конфигурации, поэтому некорректное имя или значение, которое невозможно отправить, отбрасывается с записью в журнал, не отключая функциональность; Accept, Accept-Language, User-Agent и заголовки формирования сообщений, такие как Transfer-Encoding, также отбрасываются. Для изменения агента пользователя используйте tools.web.fetch.userAgent. При перенаправлениях на другой источник сохраняются только заголовки из списка разрешённых безопасных заголовков guarded-fetch, а изменение фактически отправляемых заголовков приводит к использованию отдельного раздела кеша загрузки."}},"tools%2Eweb%2Efetch%2EmaxChars":{label:{"v1-1wbzc7m-j":`Максимум символов веб-загрузки`},help:{"v1-12d1fw7-1d":`Максимальное число символов, возвращаемых web_fetch (с обрезкой).`}},"tools%2Eweb%2Efetch%2EmaxCharsCap":{label:{"v1-141potx-o":`Жёсткий лимит символов веб-загрузки`},help:{"v1-cl2mf1-1v":`Жёсткий верхний предел maxChars для web_fetch (применяется к конфигурации и вызовам инструмента).`}},"tools%2Eweb%2Efetch%2EmaxRedirects":{label:{"v1-81lxou-n":`Максимум перенаправлений веб-загрузки`},help:{"v1-t6eak9-1h":`Максимальное число перенаправлений, разрешённых для web_fetch (по умолчанию: 3).`}},"tools%2Eweb%2Efetch%2EmaxResponseBytes":{label:{"v1-uabe8-z":`Максимальный размер веб-загрузки (байты)`},help:{"v1-q6ld9c-10":`Максимальный размер загрузки до обрезки.`}},"tools%2Eweb%2Efetch%2Eprovider":{label:{"v1-1xu05t2-i":`Провайдер веб-загрузки`},help:{"v1-6pb3nv-v":`Идентификатор резервного провайдера загрузки веб-страниц.`}},"tools%2Eweb%2Efetch%2Ereadability":{label:{"v1-32zds-w":`Извлечение содержимого веб-страниц с помощью Readability`},help:{"v1-19exqzx-2c":`Использовать Readability для извлечения основного содержимого из HTML (с базовой очисткой HTML в качестве резервного варианта).`}},"tools%2Eweb%2Efetch%2EssrfPolicy":{label:{"v1-jaq5z9-l":`Политика защиты от SSRF при загрузке веб-страниц`},help:{"v1-qtn7zx-3c":`Точечные переопределения политики защиты от SSRF для web_fetch. Ограничивайте их область действия и включайте только для известных прокси-сред в локальной сети.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowedHostnames":{label:{"v1-1r9zld3-r":`Разрешённые имена хостов для загрузки веб-страниц`},help:{"v1-1j9ctya-35":`Точные имена хостов или явно заданные IP-адреса, разрешённые для web_fetch, включая адреса, которые иначе были бы заблокированы. Сохраняйте список минимальным.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-t82ara-13":`Разрешить диапазон уникальных локальных IPv6-адресов для загрузки веб-страниц`},help:{"v1-1eyz55i-3b":`Разрешить уникальные локальные IPv6-адреса (fc00::/7) для совместимости с доверенными прокси, использующими fake-IP, такими как sing-box, Clash или Surge.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-4hkyhg-14":`Разрешить тестовый диапазон RFC 2544 для загрузки веб-страниц`},help:{"v1-u5asdb-2y":`Разрешить IP-адреса из тестового диапазона RFC 2544 (198.18.0.0/15) для совместимости с прокси, использующими fake-IP, такими как Clash или Surge.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EblockedHostnames":{label:{"v1-1gm3p1b-r":`Заблокированные имена хостов для загрузки веб-страниц`},help:{"v1-1164vvk-66":`Шаблоны имён хостов, блокируемых до разрешения DNS и применения разрешающих правил при каждом перенаправлении web_fetch. Поддерживаются точные имена хостов и "*.example.com" только для поддоменов; для блокировки корневого домена добавьте "example.com" отдельно. Если значение пустое или не задано, дополнительные запреты не применяются.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-1rhrboq-17":`Опасное разрешение доступа к частной сети при веб-загрузке`},help:{"v1-2s6mv7-3t":`Разрешает web_fetch доступ к ресурсам частных и внутренних сетей. Оставьте отключённым, если в этом развёртывании нельзя доверять URL, выбранным моделью.`}},"tools%2Eweb%2Efetch%2EtimeoutSeconds":{label:{"v1-ry7npa-n":`Тайм-аут веб-загрузки (с)`},help:{"v1-1c3yfr4-16":`Тайм-аут запросов web_fetch в секундах.`}},"tools%2Eweb%2Efetch%2EuserAgent":{label:{"v1-5t3azc-k":`User-Agent для веб-загрузки`},help:{"v1-s7pe8j-1e":`Переопределяет заголовок User-Agent для запросов web_fetch.`}},"tools%2Eweb%2Efetch%2EuseTrustedEnvProxy":{label:{"v1-1pkpnd9-r":`Доверенный прокси из переменных окружения для веб-загрузки`},help:{"v1-1ypkqj7-54":`Направляет web_fetch через доверенный HTTP(S)-прокси, заданный переменными окружения, и передаёт ему разрешение DNS. Включайте, только если этот прокси контролируется оператором и применяет политику исходящих соединений после разрешения DNS.`}},"tools%2Eweb%2Esearch%2EcacheTtlMinutes":{label:{"v1-14u7axu-q":`Время жизни кеша веб-поиска (мин)`},help:{"v1-6trzlf-18":`Время жизни кеша результатов web_search в минутах.`}},"tools%2Eweb%2Esearch%2Eenabled":{label:{"v1-1yn3rki-m":`Включить инструмент веб-поиска`},help:{"v1-n1cm4y-27":`Включает управляемый web_search и дополнительный встроенный поиск Codex для поддерживаемых моделей.`}},"tools%2Eweb%2Esearch%2EmaxResults":{label:{"v1-jy940f-m":`Максимальное число результатов веб-поиска`},help:{"v1-mrw7mi-z":`Количество возвращаемых результатов (1–10).`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EallowedDomains":{label:{"v1-aqtmld-l":`Разрешённые домены Codex`},help:{"v1-1cv4y44-43":`Список разрешённых доменов для встроенного web_search Codex. На шагах со встроенным поиском он также ограничивает управляемый web_fetch; шаги с управляемым провайдером остаются без изменений.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EcontextSize":{label:{"v1-1s2nw4o-p":`Размер контекста поиска Codex`},help:{"v1-antack-1u":`Рекомендуемый размер контекста встроенного поиска Codex: "low", "medium" или "high".`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2Eenabled":{label:{"v1-1eejtq4-u":`Включить встроенный веб-поиск Codex`},help:{"v1-ek2jzd-1k":`Включить встроенный веб-поиск Codex для моделей с поддержкой Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2Emode":{label:{"v1-1eic0y9-l":`Режим веб-поиска Codex`},help:{"v1-1ahyq9f-32":`Предпочтительный режим встроенного веб-поиска Codex: "cached" (по умолчанию; на шагах Codex без ограничений используется "live") или "live".`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Ecity":{label:{"v1-1p5e722-f":`Город пользователя Codex`},help:{"v1-1y95orp-1d":`Примерный город местонахождения пользователя, передаваемый во встроенный веб-поиск Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Ecountry":{label:{"v1-u0nthl-i":`Страна пользователя Codex`},help:{"v1-1xkm5ms-1g":`Примерная страна местонахождения пользователя, передаваемая во встроенный веб-поиск Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Eregion":{label:{"v1-1pmca79-h":`Регион пользователя Codex`},help:{"v1-lhar02-1l":`Приблизительный регион или штат, передаваемый встроенному веб-поиску Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Etimezone":{label:{"v1-by3d62-j":`Часовой пояс пользователя Codex`},help:{"v1-fgv9fh-1h":`Приблизительный часовой пояс, передаваемый встроенному веб-поиску Codex.`}},"tools%2Eweb%2Esearch%2Eprovider":{label:{"v1-rztytk-j":`Провайдер веб-поиска`},help:{"v1-10omglr-1x":`Идентификатор провайдера поиска. Если не указан, определяется автоматически по доступным ключам API.`}},"tools%2Eweb%2Esearch%2EtimeoutSeconds":{label:{"v1-2gxsb4-o":`Тайм-аут веб-поиска (сек)`},help:{"v1-i0egvw-17":`Тайм-аут в секундах для запросов web_search.`}},transcripts:{label:{"v1-1iqk6o8-b":`Расшифровки`},help:{"v1-1i0sc09-66":`Основные настройки сохранения расшифровок для заметок о встречах, инструментов агента с возможностью записи и настроенных источников автоматического запуска записи текущих встреч. Плагины встреч по умолчанию сохраняют заметки для длительного хранения; установите enabled в false, чтобы отключить это глобально.`}},"transcripts%2EautoStart":{label:{"v1-1ocjrmc-u":`Источники автозапуска расшифровок`},help:{"v1-1mzsl79-5s":`Источники расшифровок в реальном времени, управляемые автоматически с момента запуска Gateway. Наличие записи включает соответствующий источник; удалите запись, чтобы отключить его. Источники ведут запись непрерывно, если не включён whenOccupied.`}},"transcripts%2EautoStart%5B%5D%2EaccountId":{label:{"v1-1ffe8lp-l":`ID учётной записи для расшифровки`},help:{"v1-6g2kjj-4b":`Необязательный идентификатор учётной записи провайдера или рабочего пространства для источников расшифровок, которым необходимо различать учётные записи. Используйте формат идентификатора учётной записи, указанный в документации провайдера.`}},"transcripts%2EautoStart%5B%5D%2EchannelId":{label:{"v1-ujvqt-l":`ID канала расшифровки`},help:{"v1-1lk9d5o-4u":`Идентификатор канала провайдера для источника транскрипции в реальном времени, например голосового канала Discord или канала встреч Slack. Перед включением автозапуска проверьте особенности использования идентификаторов у провайдера.`}},"transcripts%2EautoStart%5B%5D%2EguildId":{label:{"v1-tdpg2t-g":`ID сервера Discord`},help:{"v1-fyfgnk-4l":`Необязательный идентификатор сервера Discord для источников транскрипции голосовых каналов Discord. Укажите его вместе с соответствующим channelId, если провайдеру требуется поиск голосового канала в пределах сервера.`}},"transcripts%2EautoStart%5B%5D%2EmeetingUrl":{label:{"v1-f1fo9f-m":`URL встречи для транскрипции`},help:{"v1-1xtt9ci-4f":`Необязательный URL встречи для провайдеров, которые подключаются по URL, а не по идентификатору канала. Используйте только доверенные ссылки на встречи, поскольку автозапуск может привести к подключению к встрече и записи её содержимого.`}},"transcripts%2EautoStart%5B%5D%2EproviderId":{label:{"v1-1dnfgvi-t":`ID провайдера источника транскрипции`},help:{"v1-1uur06p-3s":`Идентификатор провайдера источника транскрипции, например провайдера голосовых каналов Discord или будущего провайдера встреч Slack. Используйте точный идентификатор, предоставляемый плагином провайдера.`}},"transcripts%2EautoStart%5B%5D%2EsessionId":{label:{"v1-1q57lkc-l":`ID сеанса транскрипции`},help:{"v1-xyo4x5-5o":`Необязательный фиксированный идентификатор сеанса транскрипции для этого источника автозапуска. Игнорируется, если whenOccupied имеет значение true. Оставьте незаданным для автоматической генерации идентификаторов, если вам не нужен стабильный ежедневный селектор и вы не можете избежать конфликтов идентификаторов в течение одного дня.`}},"transcripts%2EautoStart%5B%5D%2Etitle":{label:{"v1-11w5opp-g":`Название транскрипции`},help:{"v1-ycjnmp-5y":`Необязательное название для будущих сеансов записи расшифровок. Изменение только названий не прерывает текущие сеансы и не меняет их первоначальные названия или сохранённые заметки. При других изменениях источника действуют обычные правила перезапуска.`}},"transcripts%2EautoStart%5B%5D%2EwhenOccupied":{label:{"v1-12ewhvp-w":`Запись расшифровки при наличии участников`},help:{"v1-34jid4-78":`Начинать новый сеанс расшифровки каждый раз, когда в источнике появляются люди, и останавливать его (создавая заметки), когда последний человек уходит. Требуется провайдер, сообщающий о присутствии участников, например discord-voice. По умолчанию: false (непрерывная запись с момента запуска Gateway).`}},"transcripts%2Eenabled":{label:{"v1-d2c4ax-j":`Расшифровки включены`},help:{"v1-fyqqr0-6d":`Включает автоматическое создание и долговременное хранение заметок о встречах, инструмент агента transcripts и настроенные источники с автоматическим запуском. По умолчанию: true. Установите false, чтобы отключить сохранение и инструмент; в явно выбранном режиме расшифровки встречи сохраняется ограниченный по объёму буфер последних данных в реальном времени.`}},tts:{label:{"v1-bmxkk9-e":`Синтез речи`},help:{"v1-1o27tk2-4n":`Правила синтеза речи для озвучивания ответов агента в поддерживаемых голосовых или аудиоинтерфейсах. Оставьте отключённым, если воспроизведение речи не входит в рабочий процесс оператора или пользователя.`}},"tts%2Epersona":{label:{"v1-118fea6-b":`Голосовой профиль TTS`},help:{"v1-1r0opcb-29":`Идентификатор голосового профиля TTS по умолчанию. Локальные настройки голосового профиля TTS могут переопределять его для каждого хоста.`}},"tts%2Epersonas":{label:{"v1-1gi7idj-c":`Голосовые профили TTS`},help:{"v1-19aybhl-2l":`Именованные голосовые профили TTS, задающие постоянный образ звучания и привязки к параметрам речи конкретных провайдеров.`}},"tts%2Epersonas%2E*":{label:{"v1-118fea6-b":`Голосовой профиль TTS`},help:{"v1-10s52ah-2l":`Один голосовой профиль TTS. Используйте привязки к конкретным провайдерам, чтобы точно задать голоса, модели и шаблоны промптов.`}},"tts%2Epersonas%2E*%2Eproviders":{label:{"v1-dji537-t":`Привязки голосового профиля TTS к провайдерам`},help:{"v1-993jop-3e":`Привязки голосового профиля TTS к провайдерам, где ключами служат идентификаторы речевых провайдеров. Для активного профиля они объединяются с tts.providers, переопределяя совпадающие настройки.`}},"tts%2Eproviders":{label:{"v1-1y7c1ro-l":`Настройки провайдеров TTS`},help:{"v1-1k80nl4-4y":`Настройки TTS для отдельных провайдеров, где ключами служат идентификаторы речевых провайдеров. Используйте этот раздел вместо встроенных ключей верхнего уровня для отдельных провайдеров, чтобы речевые плагины оставались независимыми от основной схемы конфигурации.`}},"tts%2Eproviders%2E*":{label:{"v1-15ged0b-j":`Конфигурация провайдера TTS`},help:{"v1-dwapva-3d":`Конфигурация TTS для одного речевого провайдера, заданного идентификатором. Используйте только поля, относящиеся к плагину, которому принадлежит этот провайдер.`}},"tts%2Eproviders%2E*%2EapiKey":{label:{"v1-68k8k0-k":`Ключ API провайдера TTS`},help:{"v1-1m2fj0i-2o":`Ключ API, используемый этим речевым провайдером, когда его плагину требуется аутентификация для доступа к TTS.`}},tui:{label:{"v1-c8hus1-b":`Терминальный интерфейс`},help:{"v1-1fg9vw2-3s":`Настройки отображения терминального интерфейса. Используйте этот раздел для настройки оформления только в терминале, не меняя поведение Gateway или других интерфейсов.`}},"tui%2Efooter":{label:{"v1-1nnfi3c-i":`Нижняя панель терминального интерфейса`},help:{"v1-6e12l3-3k":`Настройки отображения нижней панели терминального интерфейса. Размещайте дополнительный контекст компактно, чтобы сведения о сеансе, модели, цели и токенах оставались читаемыми.`}},ui:{label:{"v1-ye4dff-2":`Интерфейс`},help:{"v1-dt1924-42":`Настройки оформления интерфейса: акцентные элементы и параметры отображения для оператора. Используйте их для улучшения читаемости, не меняя поведение во время выполнения.`}},"ui%2Eprefs%2Eaccent":{label:{"v1-1e4sxpj-h":`Пользовательский акцентный цвет`},help:{"v1-16klzws-4z":`Акцентный цвет Control UI: #RRGGBB для пользовательского цвета или 'theme' для палитры выбранной темы. Переопределяет ui.seamColor; очистите значение, чтобы использовать настроенный цвет разделителя или цвет темы по умолчанию.`}},"ui%2EseamColor":{label:{"v1-1ddt13c-c":`Акцентный цвет`},help:{"v1-14q3r4h-4g":`Основной акцентный цвет элементов интерфейса для выделения, значков и визуальной идентификации. Используйте высококонтрастные значения, сохраняющие читаемость в светлой и тёмной темах.`}},update:{label:{"v1-k12u1x-7":`Обновления`},help:{"v1-11c5k8v-5c":`Настройки канала обновлений и проверки при запуске для поддержания актуальной версии среды выполнения OpenClaw. В рабочих средах используйте консервативные каналы, а экспериментальные — только в контролируемых средах.`}},"update%2Eauto%2Eenabled":{label:{"v1-1ahdhbe-j":`Автообновление включено`},help:{"v1-49xs2h-3c":`Включает фоновое автообновление для пакетных установок stable и beta; обновления extended-stable никогда не применяются автоматически (по умолчанию: false).`}},"update%2Echannel":{label:{"v1-zk8ncv-e":`Канал обновлений`},help:{"v1-lqtdvf-5b":`Канал обновлений для установок через git + npm ("stable", "extended-stable", "beta" или "dev"). Канал extended-stable доступен только для пакетных установок: установка выполняется только в основном процессе, с необязательными информационными подсказками при запуске.`}},"update%2EcheckOnStart":{label:{"v1-10js111-l":`Проверка обновлений при запуске`},help:{"v1-qy3q9g-5v":`Проверяет наличие обновлений при запуске Gateway, включая уведомления для extended-stable без применения обновлений (по умолчанию: true). Установите false, чтобы отключить автоматическую проверку и применение обновлений Gateway и узлов без графического интерфейса, а также анонимные запросы к сервису обновлений.`}},voicewake:{label:{"v1-txt1wb-a":`Голосовая активация`}},web:{label:{"v1-1ae9z56-b":`Веб-канал`}},wizard:{label:{"v1-28jonk-h":`Параметры настройки`},help:{"v1-14jh6rm-3b":`Пользовательские параметры настройки. История мастера и состояние подтверждений, относящиеся к компьютеру, хранятся в общей базе данных состояния.`}},"wizard%2EaccessMode":{label:{"v1-1ayx2hy-m":`Доступ к обнаружению при настройке`},help:{"v1-1nqxt0w-38":`Согласие на обнаружение при пошаговой настройке: "full" выполняет сканирование без запросов, а "guarded" запрашивает разрешение перед проверкой локальных приложений.`}},"wizard%2EappRecommendations":{label:{"v1-jc89qd-p":`Рекомендации приложений при настройке`},help:{"v1-ub8uoi-30":`Определяет, может ли мастер пошаговой настройки использовать названия установленных приложений для рекомендации подходящих плагинов и навыков.`}},"wizard%2ElastRunAt":{label:{"v1-1puf3az-p":`Время последнего запуска мастера`},help:{"v1-1y0fbk-1k":`Время последнего запуска мастера, результаты которого были успешно сохранены.`}},"wizard%2ElastRunCommand":{label:{"v1-3f99ei-n":`Команда последнего запуска мастера`},help:{"v1-x2pfkk-15":`Команда, использованная для последнего запуска мастера.`}},"wizard%2ElastRunCommit":{label:{"v1-1a2uglw-m":`Коммит последнего запуска мастера`},help:{"v1-h0jkmt-1i":`Коммит исходного кода, использованный при последнем запуске мастера в среде разработки.`}},"wizard%2ElastRunMode":{label:{"v1-p2iydm-k":`Режим последнего запуска мастера`},help:{"v1-16508qy-1r":`Тип настройки при последнем запуске мастера: "local" или "remote".`}},"wizard%2ElastRunVersion":{label:{"v1-1kvlwlr-n":`Версия последнего запуска мастера`},help:{"v1-1tr4z9d-19":`Версия OpenClaw, использованная при последнем запуске мастера.`}},"wizard%2EsecurityAcknowledgedAt":{label:{"v1-17xanyw-15":`Время подтверждения ознакомления с мерами безопасности в мастере`},help:{"v1-86i182-2a":`Время подтверждения ознакомления с мерами безопасности при настройке, сохранённое вместе с целевой конфигурацией.`}},worktreeAcceleration:{label:{"v1-128z6h8-l":`Ускорение работы с рабочими деревьями`},help:{"v1-9es3gc-4r":`Использовать ускорение файловой системы для новых управляемых рабочих деревьев, если оно поддерживается (по умолчанию: true). Установите false, чтобы использовать обычные операции Git checkout и копирования файлов. Применяется только к новым рабочим деревьям.`}},worktreeRoot:{label:{"v1-bqutg0-d":`Корневой каталог рабочих деревьев`},help:{"v1-1tgti9j-5d":`Общий каталог для новых управляемых рабочих деревьев. Используйте абсолютный путь или ~ для домашнего каталога; по умолчанию — <state-dir>/worktrees. При изменении этого параметра существующие рабочие деревья сохраняют ранее записанные пути.`}}}}})))()}export{t as n,n as t};